  // ---------------------------------------------------------------------------
  if (config.corsAllowedOrigins.length > 0) {
    const allowedOrigins = new Set(config.corsAllowedOrigins);
    const allowedMethods = 'GET, HEAD, POST, DELETE, OPTIONS';
    const allowedHeaders = 'Authorization, Content-Type';
    const maxAgeSeconds = '600';
    app.addHook('onRequest', async (request, reply) => {
      const origin = request.headers.origin;
      if (typeof origin !== 'string' || !allowedOrigins.has(origin)) return;
      reply.header('Access-Control-Allow-Origin', origin);
      // La respuesta depende del `Origin` de la request: es cacheable por origen (RFC 9110).
      reply.header('Vary', 'Origin');
      if (request.method !== 'OPTIONS') return;
      // Preflight: se responde acá mismo, antes del enrutado, para que no caiga en el
      // handler de 404/405 ni en el de errores.
      reply.header('Access-Control-Allow-Methods', allowedMethods);
      reply.header('Access-Control-Allow-Headers', allowedHeaders);
      reply.header('Access-Control-Max-Age', maxAgeSeconds);
      await reply.status(204).send();
      return reply;
    });
  }

  // ---------------------------------------------------------------------------
  // Parseo del cuerpo: cualquier cuerpo se interpreta como JSON. Un cuerpo que no sea
  // JSON válido produce VALIDATION_ERROR (422) — HU-09-01 RN-3.
  //
  // El fallo de parseo NO se emite acá: el parser corre antes que los handlers, y el rate
  // limiting es el **paso 0** de la precedencia, anterior a cualquier validación "incluso
  // la de esquema" (HU-01-01 RN-9/RN-10, HU-01-02 RN-8/RN-9). Por eso el error queda
  // diferido en la request y lo levanta el handler *después* de evaluar el límite y, en los
  // recursos protegidos, después de autenticar (HU-09-02 RN-9 / AT-09-05-04). Para las
  // rutas sin cuerpo ni precedencia propia, el hook `preHandler` de más abajo lo levanta
  // antes del handler, de modo que nunca se ignora en silencio.
  // ---------------------------------------------------------------------------
  app.removeContentTypeParser(['application/json', 'text/plain']);
  app.addContentTypeParser('*', { parseAs: 'string' }, (request, body: string, done) => {
    const contentType = request.headers['content-type'];
    if (contentType && !/json/i.test(contentType)) {
      deferBodyError(
        request,
        validationError([{ field: 'Content-Type', message: 'Se espera application/json.' }]),
      );
      done(null, undefined);
      return;
    }
    if (body === undefined || body === null || body.length === 0) {
      done(null, undefined);
      return;
    }
    try {
      done(null, JSON.parse(body));
    } catch {
      deferBodyError(
        request,
        validationError([{ field: 'body', message: 'El cuerpo no es JSON válido.' }]),
      );
      done(null, undefined);
    }
  });

  // Rutas cuyo handler levanta el error diferido en el punto exacto que le fija su
  // precedencia (después del rate limiting y de la autenticación). Para cualquier otra
  // ruta, la red de seguridad de abajo lo levanta antes del handler, de modo que un cuerpo
  // que no parsea nunca se ignora en silencio.
  const ROUTES_WITH_ORDERED_BODY_CHECK = new Set([
    '/api/v1/auth/register',
    '/api/v1/auth/login',
    '/api/v1/me',
    '/api/v1/deposit-address',
    '/internal/deposit-addresses',
  ]);
  app.addHook('preHandler', async (request) => {
    if (ROUTES_WITH_ORDERED_BODY_CHECK.has(normalizePath(request.url))) return;
    throwDeferredBodyError(request);
  });

  // ---------------------------------------------------------------------------
  // Manejo uniforme de errores (HU-09-05).
  // ---------------------------------------------------------------------------
  function sendError(reply: FastifyReply, error: AppError): FastifyReply {
    if (error.headers) {
      for (const [name, value] of Object.entries(error.headers)) reply.header(name, value);
    }
    return reply.status(error.httpStatus).send(error.toEnvelope());
  }

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      return sendError(reply, error);
    }
    const fastifyCode = (error as { code?: string }).code ?? '';
    if (
      fastifyCode.startsWith('FST_ERR_CTP_') ||
      fastifyCode === 'FST_ERR_VALIDATION' ||
      (typeof (error as { statusCode?: number }).statusCode === 'number' &&
        (error as { statusCode: number }).statusCode === 400)
    ) {
      return sendError(
        reply,
        validationError([{ field: 'body', message: 'Cuerpo o parámetros inválidos.' }]),
      );
    }
    // INTERNAL_ERROR no filtra detalles sensibles (HU-09-05 RN-9); el detalle queda en el
    // log del servidor.
    request.log.error({ err: error }, 'error interno no clasificado');
    return sendError(reply, new AppError('INTERNAL_ERROR', 'Error interno del servidor.'));
  });

  app.setNotFoundHandler((request, reply) => {
    const pathname = normalizePath(request.url);
    const allowed = ROUTE_METHODS[pathname];
    if (allowed && !allowed.includes(request.method)) {
      return sendError(
        reply,
        new AppError('METHOD_NOT_ALLOWED', 'Método no permitido sobre la ruta.', {
          method: request.method,
          allowed,
        }),
      );
    }
    return sendError(
      reply,
      new AppError('NOT_FOUND', 'Recurso inexistente.', { resource: 'route', id: pathname }),
    );
  });

  // ---------------------------------------------------------------------------
  // Autenticación (HU-09-02 RN-1..RN-4): se evalúa antes que cualquier validación de
  // esquema o regla de negocio (RN-9).
  // ---------------------------------------------------------------------------
  function authenticate(request: FastifyRequest): { accountId: string } {
    const header = request.headers.authorization;
    if (!header || typeof header !== 'string') throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    // El nombre del esquema es case-insensitive (RFC 7235); el valor del token no.
    const match = /^Bearer[ \t]+(.+)$/i.exec(header.trim());
    if (!match) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    const identity = sessions.resolve(match[1].trim());
    if (!identity) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    return { accountId: identity.accountId };
  }

  function enforceApiRateLimit(accountId: string, routeKey: string): void {
    const decision = apiLimiter.consume(`${accountId}|${routeKey}`);
    if (decision.limited) {
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de solicitudes permitido.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
  }

  // ---------------------------------------------------------------------------
  // Health check
  // ---------------------------------------------------------------------------
  app.get('/health', async () => ({
    status: 'ok',
    service: 'cex-backend',
    time: nowIso(),
    network: NETWORK_NAME,
    chainId: CHAIN_ID,
    rpcConfigured: config.ethRpcUrl !== '',
  }));

  // ---------------------------------------------------------------------------
  // HU-01-01 — Registro (público, 201)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/register', async (request, reply) => {
    // Paso 0 de la precedencia (HU-01-01 RN-9/RN-10): rate limiting antes de todo.
    const decision = registerLimiter.consume(`${request.ip}`);
    if (decision.limited) {
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de registros permitido desde este origen.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-9).
    throwDeferredBodyError(request);
    const account = await accounts.register(request.body, request.ip ?? null);
    return reply.status(201).send(account);
  });

  // ---------------------------------------------------------------------------
  // HU-01-02 — Login (público, 200)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/login', async (request, reply) => {
    // Paso 0: rate limiting de intentos fallidos por (origen, email), uniforme y sin
    // revelar la existencia del email (HU-01-02 RN-8/RN-9).
    const rawEmail =
      typeof request.body === 'object' &&
      request.body !== null &&
      typeof (request.body as Record<string, unknown>).email === 'string'
        ? normalizeEmail((request.body as Record<string, string>).email)
        : '';
    const limiterKey = `${request.ip}|${rawEmail}`;
    // Si el cuerpo no parseó no hay email: el paso 0 se evalúa igual, con el origen como
    // granularidad, para que una solicitud con payload inválido responda 429 y no 422
    // (HU-01-02 RN-8).
    const decision =
      rawEmail === ''
        ? loginFailureLimiter.peekByPrefix(`${request.ip}|`)
        : loginFailureLimiter.peek(limiterKey);
    if (decision.limited) {
      audit.record({
        event: 'LOGIN',
        email: rawEmail || null,
        result: 'FAILURE',
        reason: 'RATE_LIMITED',
        origin: request.ip ?? null,
      });
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de intentos de autenticación.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-8).
    throwDeferredBodyError(request);
    try {
      const result = await accounts.login(request.body, request.ip ?? null);
      return reply.status(200).send(result);
    } catch (err) {
      if (err instanceof AppError && err.code === 'INVALID_CREDENTIALS') {
        loginFailureLimiter.record(limiterKey);
      }
      throw err;
    }
  });

  // ---------------------------------------------------------------------------
  // HU-01-04 — Consulta de perfil propio (protegido, 200) — `GET /api/v1/me`
  // (mapa de endpoints de HU-09-01, AT-09-01-03).
  //
  // Sobre AT-01-04-05/06 (perfil de una cuenta ajena, `UNAUTHORIZED` 403): esos AT están
  // redactados **condicionalmente** ("Si la API expone el perfil por identificador, p. ej.
  // `/accounts/{accountId}`" — HU-01-04 RN-3). El contrato de la épica 09 **no** expone
  // `/accounts/{accountId}`: el único endpoint de perfil es `GET /api/v1/me`, que resuelve
  // la cuenta exclusivamente desde el token (RN-2 / HU-09-02 RN-4), así que no existe
  // superficie por la cual pedir el perfil de otra cuenta y la premisa del condicional no
  // se cumple. No se inventan rutas que la épica 09 no declara.
  //
  // En consecuencia, cualquier selector de cuenta inyectado (`?accountId=`, `X-Account-Id`,
  // un cuerpo con `accountId`) se **ignora**, igual que en `GET /api/v1/deposit-address`
  // (HU-06-04 RN-2): la respuesta es siempre el perfil del dueño del token, nunca un 403.
  // Eso mantiene el criterio del catálogo de errores (`UNAUTHORIZED` queda reservado a
  // operaciones que actúan explícitamente **a nombre de** otra cuenta, y los recursos
  // ajenos referenciados por id usan la familia NOT_FOUND para no filtrar existencia:
  // `modelo-de-errores.md` §3.1 y la nota de §3.4) y no filtra si la cuenta ajena existe.
  // La precedencia RN-8 se preserva de todos modos: sin credencial válida la respuesta es
  // `UNAUTHENTICATED` (401) antes de cualquier otra evaluación (AT-01-04-06).
  // ---------------------------------------------------------------------------
  app.get('/api/v1/me', async (request, reply) => {
    // Precedencia: UNAUTHENTICATED → rate limiting por cuenta y endpoint → esquema.
    const identity = authenticate(request);
    enforceApiRateLimit(identity.accountId, 'GET /api/v1/me');
    // Recién ahora, después de la autenticación (HU-09-02 RN-9 / AT-09-05-04), se reporta
    // un cuerpo que no parsea: sin token la respuesta es UNAUTHENTICATED, no
    // VALIDATION_ERROR. Verificado por test: en un `GET` el cuerpo no se parsea, así que
    // hoy esto (y la pertenencia de la ruta a `ROUTES_WITH_ORDERED_BODY_CHECK`) es
    // defensivo — sostiene la precedencia por construcción, igual que en
    // `GET /api/v1/deposit-address`, sin depender de ese detalle del framework.
    throwDeferredBodyError(request);

    const account = accounts.repository.findById(identity.accountId);
    // Defensa en profundidad: un token válido siempre resuelve a una cuenta existente
    // (la sesión tiene FK contra `accounts`). Si no existiera, se responde con el código
    // de cuentas del catálogo (`modelo-de-errores.md` §3.6) y nunca un 500.
    if (!account) {
      // `details` sigue la forma que el catálogo espera para este código: `{ accountId }`
      // (`modelo-de-errores.md` §3.6). Es la cuenta propia del token, no una ajena, así
      // que no revela nada de terceros.
      throw new AppError('ACCOUNT_NOT_FOUND', 'La cuenta no existe.', {
        accountId: identity.accountId,
      });
    }
    // Proyección explícita de los cuatro campos de identidad (HU-01-04 RN-4): sin
    // balances (RN-6), sin hash, sin sal y sin token (RN-5). La lectura no toca la sesión:
    // no se renueva `expires_at` (RN-7).
    return reply.status(200).send({
      accountId: account.accountId,
      email: account.email,
      status: account.status,
      createdAt: account.createdAt,
    });
  });

  // ---------------------------------------------------------------------------
  // HU-06-04 — Consulta de dirección de depósito (protegido, 200)
  // ---------------------------------------------------------------------------
  app.get('/api/v1/deposit-address', async (request, reply) => {
    // Precedencia (HU-06-04 RN-9): UNAUTHENTICATED → UNAUTHORIZED → esquema/activo →
    // red → asignación/lectura.
    const identity = authenticate(request);
    enforceApiRateLimit(identity.accountId, 'GET /api/v1/deposit-address');
    // Recién ahora, después de la autenticación (HU-09-02 RN-9 / AT-09-05-04), se reporta
    // un cuerpo que no parsea: sin token la respuesta es UNAUTHENTICATED, no
    // VALIDATION_ERROR.
    throwDeferredBodyError(request);

    const query = (request.query ?? {}) as Record<string, unknown>;
    const asset = singleQueryValue(query.asset);
    if (asset === undefined || !SUPPORTED_ASSETS.includes(asset as SupportedAsset)) {
      throw validationError([
        {
          field: 'asset',
          message: `El activo debe ser uno de: ${SUPPORTED_ASSETS.join(', ')}.`,
        },
      ]);
    }

    // La red es implícitamente Sepolia; si la consulta declara otra, se rechaza (RN-4).
    const chainIdParam = singleQueryValue(query.chainId);
    if (chainIdParam !== undefined && chainIdParam.trim() !== CHAIN_ID) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: chainIdParam,
      });
    }
    const networkParam = singleQueryValue(query.network);
    if (networkParam !== undefined && networkParam.trim().toLowerCase() !== NETWORK_NAME) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: networkParam,
      });
    }

    // La identidad sale exclusivamente del token: cualquier selector de cuenta inyectado
    // por query o body se ignora (RN-2).
    const record = wallet.getOrAssign(identity.accountId);

    const body: Record<string, string> = {
      asset,
      address: record.address,
      network: record.network,
      chainId: record.chainId,
      derivationPath: record.derivationPath,
    };
    if (asset === 'USDC') body.tokenAddress = config.usdcContractAddress;
    return reply.status(200).send(body);
  });

  // ---------------------------------------------------------------------------
  // Consulta interna del conjunto de direcciones asignadas (HU-06-03 RN-11).
  // No es pública: requiere `X-Internal-Token` o provenir de loopback.
  // ---------------------------------------------------------------------------
  app.get('/internal/deposit-addresses', async (request, reply) => {
    const token = request.headers['x-internal-token'];
    const isLoopback = ['127.0.0.1', '::1', '::ffff:127.0.0.1'].includes(request.ip);
    const authorized = config.internalApiToken
      ? token === config.internalApiToken
      : isLoopback;
    if (!authorized) throw new AppError('UNAUTHENTICATED', 'Credencial interna ausente o inválida.');
    throwDeferredBodyError(request);
    return reply.status(200).send({
      network: NETWORK_NAME,
      chainId: CHAIN_ID,
      items: wallet.listAll().map((record) => ({
        accountId: record.accountId,
        addressIndex: record.addressIndex,
        address: record.address,
        derivationPath: record.derivationPath,
        network: record.network,
        chainId: record.chainId,
        createdAt: record.createdAt,
      })),
    });
  });

  return app;
}

