/**
 * Cliente HTTP de la API del exchange (contrato de la épica 09).
 *
 * - Ruta base `/api/v1` (HU-09-01: "todos los recursos cuelgan de `/api/v1`").
 * - Autenticación por header `Authorization: Bearer <token>` (HU-09-02 RN-1). El contrato
 *   **no** usa cookies de sesión (HU-10-01 RN-3), así que no se envían credenciales de
 *   navegador (`credentials: 'omit'`).
 * - Toda respuesta de error se traduce a `ApiError` con el `code` del catálogo; cualquier
 *   otra falla (red, respuesta ilegible) a `NetworkError`.
 */
import { ApiError, NetworkError } from './errors';

export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

export interface ApiClientOptions {
  /** Prefijo de la API. Por defecto, `VITE_API_BASE_URL` o `/api/v1`. */
  baseUrl?: string;
  /** Implementación de `fetch` (inyectable para tests). */
  fetchImpl?: FetchLike;
  /** Token Bearer vigente, o `null` si no hay sesión. */
  getToken?: () => string | null;
  /**
   * Se invoca cuando una llamada **protegida** responde `UNAUTHENTICATED` (401): el cliente
   * limpia la sesión local y vuelve a login (HU-10-01 RN-7 / RNE-4).
   */
  onUnauthenticated?: () => void;
}

export interface RequestOptions {
  method?: 'GET' | 'POST' | 'DELETE';
  body?: unknown;
  /** Adjunta el header `Authorization` si hay token. */
  auth?: boolean;
  /**
   * Si es `false`, un `UNAUTHENTICATED` no dispara el manejo global de sesión expirada.
   * Lo usa la validación de sesión del arranque, que tiene su propio tratamiento
   * (HU-10-01 RN-11: limpia la sesión y **permanece** en login, sin aviso de expiración).
   */
  handleUnauthenticated?: boolean;
}

function resolveDefaultBaseUrl(): string {
  const fromEnv = import.meta.env?.VITE_API_BASE_URL;
  return typeof fromEnv === 'string' && fromEnv.trim() !== '' ? fromEnv.trim() : '/api/v1';
}

function joinUrl(baseUrl: string, path: string): string {
  const base = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
  const suffix = path.startsWith('/') ? path : `/${path}`;
  return `${base}${suffix}`;
}

/** Extrae `{ code, details }` del envelope uniforme; `null` si el cuerpo no lo respeta. */
function readErrorEnvelope(payload: unknown): { code: string; details?: Record<string, unknown> } | null {
  if (typeof payload !== 'object' || payload === null) return null;
  const error = (payload as Record<string, unknown>).error;
  if (typeof error !== 'object' || error === null) return null;
  const { code, details } = error as Record<string, unknown>;
  if (typeof code !== 'string' || code === '') return null;
  return {
    code,
    details:
      typeof details === 'object' && details !== null && !Array.isArray(details)
        ? (details as Record<string, unknown>)
        : undefined,
  };
}

export class ApiClient {
  private readonly baseUrl: string;
  private readonly fetchImpl: FetchLike;
  private readonly getToken: () => string | null;
  private readonly onUnauthenticated: (() => void) | undefined;

  constructor(options: ApiClientOptions = {}) {
    this.baseUrl = options.baseUrl ?? resolveDefaultBaseUrl();
    this.fetchImpl =
      options.fetchImpl ??
      ((input, init) => {
        if (typeof globalThis.fetch !== 'function') {
          return Promise.reject(new NetworkError());
        }
        return globalThis.fetch(input, init);
      });
    this.getToken = options.getToken ?? (() => null);
    this.onUnauthenticated = options.onUnauthenticated;
  }

  async request<T>(path: string, options: RequestOptions = {}): Promise<T> {
    const { method = 'GET', body, auth = false, handleUnauthenticated = true } = options;
    const headers: Record<string, string> = { accept: 'application/json' };
    if (body !== undefined) headers['content-type'] = 'application/json';
    if (auth) {
      const token = this.getToken();
      // El token viaja sólo en el header: nunca en la URL ni en el cuerpo (RN-3 / RNE-4).
      if (token) headers.authorization = `Bearer ${token}`;
    }

    let response: Response;
    try {
      response = await this.fetchImpl(joinUrl(this.baseUrl, path), {
        method,
        headers,
        credentials: 'omit',
        ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
      });
    } catch {
      // Fallo de red: no se filtra el detalle del error subyacente (RN-8).
      throw new NetworkError();
    }

    const raw = await response.text().catch(() => '');
    let payload: unknown = undefined;
    if (raw !== '') {
      try {
        payload = JSON.parse(raw);
      } catch {
        payload = undefined;
      }
    }

    if (!response.ok) {
      const envelope = readErrorEnvelope(payload);
      // Una respuesta de error sin envelope del catálogo no es interpretable por `code`
      // (RN-10): se trata como falla de conexión y se informa con el mensaje de RN-8.
      if (!envelope) throw new NetworkError();
      if (envelope.code === 'UNAUTHENTICATED' && handleUnauthenticated) {
        this.onUnauthenticated?.();
      }
      throw new ApiError(envelope.code, response.status, envelope.details);
    }

    return payload as T;
  }
}
/**
 * Endpoints de autenticación y perfil que consume la pantalla de login (HU-10-01).
 *
 * Contrato: `spec/09-api-http-websocket/HU-09-01-contrato-rest.md`
 *   POST /api/v1/auth/login → 200 { token, tokenType, expiresAt }   (épica 01, HU-01-02)
 *   GET  /api/v1/me         → 200 { accountId, email, status, createdAt }  (HU-01-04)
 */
import type { ApiClient } from './client';

export interface LoginRequest {
  email: string;
  password: string;
}

/** Respuesta de login. `expiresAt` es ISO 8601 UTC (HU-01-02 RN-3). */
export interface LoginResponse {
  token: string;
  tokenType?: string;
  expiresAt: string;
}

/** Perfil propio: sólo identidad, sin balances ni secretos (HU-01-04 RN-4/RN-5/RN-6). */
export interface Profile {
  accountId: string;
  email: string;
  status: string;
  createdAt: string;
}

export function login(api: ApiClient, credentials: LoginRequest): Promise<LoginResponse> {
  // El login es un endpoint **público** (HU-09-02 RN-1): un 401 acá es
  // `INVALID_CREDENTIALS`, no la expiración de una sesión, así que no debe disparar el
  // manejo global de sesión expirada de RN-7.
  return api.request<LoginResponse>('/auth/login', {
    method: 'POST',
    body: credentials,
    handleUnauthenticated: false,
  });
}

/**
 * Llamada liviana de validación de sesión (HU-10-01 RN-11). `handleUnauthenticated` queda
 * a cargo de quien la invoca: en el arranque un 401 limpia la sesión y **permanece** en
 * login, sin el aviso de expiración de RN-7.
 */
export function getProfile(
  api: ApiClient,
  options: { handleUnauthenticated?: boolean } = {},
): Promise<Profile> {
  return api.request<Profile>('/me', {
    auth: true,
    handleUnauthenticated: options.handleUnauthenticated ?? true,
  });
}
/**
 * Catálogo de errores de la API y derivación de los mensajes que ve el usuario.
 *
 * Fuente de verdad: `spec/00-fundaciones/modelo-de-errores.md` y
 * `spec/09-api-http-websocket/HU-09-05-modelo-de-errores-api.md`.
 *
 * Regla central (épica 10 RNE-3 / HU-10-01 RN-10): **todo error se discrimina por su
 * `code`**, nunca por el `message` del servidor. El `message` que llega en el envelope
 * está orientado a diagnóstico y su literal no es estable: no se muestra en la UI, para no
 * acoplarse a él y para no filtrar detalle del error (HU-10-01 RN-8).
 */

/** Códigos del catálogo (espacio de nombres plano y cerrado, §3 del modelo de errores). */
export const ERROR_CODES = [
  // 3.1 Autenticación y autorización
  'UNAUTHENTICATED',
  'UNAUTHORIZED',
  'RATE_LIMITED',
  // 3.2 Validación general
  'VALIDATION_ERROR',
  'NOT_FOUND',
  'METHOD_NOT_ALLOWED',
  // 3.3 Trading: validación de órdenes
  'INVALID_PRICE_TICK',
  'INVALID_LOT_SIZE',
  'BELOW_MIN_NOTIONAL',
  'INVALID_SIDE',
  'INVALID_ORDER_TYPE',
  'PRICE_REQUIRED',
  'PRICE_NOT_ALLOWED',
  // 3.4 Trading: estado y ejecución
  'INSUFFICIENT_FUNDS',
  'ORDER_NOT_FOUND',
  'ORDER_NOT_CANCELLABLE',
  'SELF_TRADE_BLOCKED',
  'MARKET_NO_LIQUIDITY',
  'MARKET_BUDGET_INSUFFICIENT',
  'DUPLICATE_CLIENT_ORDER_ID',
  // 3.5 On-chain
  'INVALID_ADDRESS',
  'WITHDRAWAL_BELOW_MIN',
  'WITHDRAWAL_AMOUNT_INVALID',
  'DEPOSIT_ALREADY_CREDITED',
  'DEPOSIT_NOT_CONFIRMED',
  'CHAIN_ID_MISMATCH',
  'NONCE_CONFLICT',
  'BROADCAST_FAILED',
  // 3.6 Cuentas
  'EMAIL_ALREADY_EXISTS',
  'INVALID_CREDENTIALS',
  'ACCOUNT_NOT_FOUND',
  // 3.7 Genéricos / sistema
  'CONFLICT',
  'INTERNAL_ERROR',
] as const;

export type ErrorCode = (typeof ERROR_CODES)[number];

export function isErrorCode(value: unknown): value is ErrorCode {
  return typeof value === 'string' && (ERROR_CODES as readonly string[]).includes(value);
}

/** Una causa de fallo de esquema, tal como viaja en `details.issues` (HU-10-01 RN-5). */
export interface ValidationIssue {
  field: string;
  message: string;
}

/**
 * Error de dominio devuelto por la API: `{ error: { code, message, details } }`.
 *
 * Deliberadamente **no** conserva el `message` del servidor: la UI deriva su texto del
 * `code` (RN-10) y así ningún detalle del error del backend puede terminar en pantalla
 * (RN-8).
 */
export class ApiError extends Error {
  readonly code: ErrorCode | string;
  readonly httpStatus: number;
  readonly details: Record<string, unknown> | undefined;

  constructor(code: ErrorCode | string, httpStatus: number, details?: Record<string, unknown>) {
    super(`ApiError(${code})`);
    this.name = 'ApiError';
    this.code = code;
    this.httpStatus = httpStatus;
    this.details = details;
  }

  /** `details.issues` normalizado, o `[]` si el error no trae issues utilizables. */
  get issues(): ValidationIssue[] {
    const raw = this.details?.issues;
    if (!Array.isArray(raw)) return [];
    const issues: ValidationIssue[] = [];
    for (const item of raw) {
      if (typeof item === 'string') {
        issues.push({ field: '', message: item });
        continue;
      }
      if (typeof item !== 'object' || item === null) continue;
      const record = item as Record<string, unknown>;
      const field = record.field ?? record.path ?? record.name ?? '';
      const message = record.message ?? record.msg ?? '';
      issues.push({
        field: typeof field === 'string' ? field : String(field),
        message: typeof message === 'string' ? message : '',
      });
    }
    return issues;
  }

  /**
   * `details.retryAfterSeconds` de `RATE_LIMITED`. Es un **conteo** y viaja como entero
   * JSON, no como string (HU-10-01, escenario 6).
   *
   * Se tolera además un string de dígitos (`"30"`): no es la forma que fija la spec, pero
   * aceptarlo no puede alterar el caso conforme y evita perder la espera si el servidor la
   * serializa como monto por error. Devuelve `null` si no hay un entero no negativo
   * utilizable.
   */
  get retryAfterSeconds(): number | null {
    const raw = this.details?.retryAfterSeconds;
    if (typeof raw === 'number') {
      return Number.isInteger(raw) && raw >= 0 ? raw : null;
    }
    if (typeof raw === 'string' && /^(0|[1-9][0-9]*)$/.test(raw)) {
      const parsed = Number(raw);
      return Number.isSafeInteger(parsed) ? parsed : null;
    }
    return null;
  }
}

/**
 * Fallo que impide obtener una respuesta de dominio: el servidor no fue alcanzable, la
 * conexión se cortó, o la respuesta no trae un envelope de error del catálogo. Se muestra
 * con el mismo mensaje no técnico que `INTERNAL_ERROR` (HU-10-01 RN-8).
 */
export class NetworkError extends Error {
  constructor() {
    super('NetworkError');
    this.name = 'NetworkError';
  }
}

/** Mensaje no técnico y sin detalle sensible para el fallo de red / 500 (RN-8). */
export const CONNECTION_ERROR_MESSAGE = 'No se pudo conectar, reintentá';

/** Mensaje genérico de credenciales, que no revela si el email existe (RN-4). */
export const INVALID_CREDENTIALS_MESSAGE = 'Email o contraseña incorrectos';

/** Aviso de sesión expirada al volver a login (RN-7). */
export const SESSION_EXPIRED_MESSAGE = 'Tu sesión expiró, ingresá nuevamente';

/** Texto por `code` del catálogo, en español y sin datos del error del servidor (RN-10). */
const MESSAGE_BY_CODE: Partial<Record<ErrorCode, string>> = {
  UNAUTHENTICATED: SESSION_EXPIRED_MESSAGE,
  UNAUTHORIZED: 'No tenés permiso para esta operación',
  RATE_LIMITED: 'Demasiados intentos. Esperá unos segundos antes de reintentar',
  VALIDATION_ERROR: 'Revisá los datos ingresados',
  NOT_FOUND: 'El recurso solicitado no existe',
  METHOD_NOT_ALLOWED: CONNECTION_ERROR_MESSAGE,
  INVALID_CREDENTIALS: INVALID_CREDENTIALS_MESSAGE,
  ACCOUNT_NOT_FOUND: 'El recurso solicitado no existe',
  EMAIL_ALREADY_EXISTS: 'Ya existe una cuenta con ese email',
  CONFLICT: 'La operación no se pudo completar por un conflicto de estado',
  INTERNAL_ERROR: CONNECTION_ERROR_MESSAGE,
};

/**
 * Mensaje a mostrar para un error cualquiera. Un `code` desconocido (o un fallo de red)
 * cae en el mensaje no técnico de RN-8: nunca se muestra texto proveniente del servidor.
 */
export function messageForError(error: unknown): string {
  if (error instanceof ApiError) {
    if (isErrorCode(error.code)) {
      return MESSAGE_BY_CODE[error.code] ?? CONNECTION_ERROR_MESSAGE;
    }
    return CONNECTION_ERROR_MESSAGE;
  }
  return CONNECTION_ERROR_MESSAGE;
}
/**
 * Persistencia local de la sesión (HU-10-01 RN-3).
 *
 * El contrato de la épica 09 **no** emite cookies de sesión: la autenticación es por
 * header `Authorization: Bearer <token>`. Por eso el cliente "mantiene el token en memoria
 * de la SPA y lo persiste del lado del cliente junto con su expiración para sobrevivir
 * recargas, re-validando la sesión contra el servidor al cargar la app" (RN-3 / RN-11).
 *
 * Se usa `localStorage` para que la sesión sobreviva la recarga y el cierre de la pestaña
 * hasta su expiración. El token **nunca** se escribe en la URL, ni se renderiza, ni se
 * loguea (RNE-4). Si el almacenamiento no está disponible (modo privado, cuota, etc.) la
 * sesión sigue funcionando sólo en memoria: la lectura/escritura degrada sin romper.
 */

const STORAGE_KEY = 'cex.web.session.v1';

/** Sesión tal como se persiste: token y su expiración declarada por el servidor. */
export interface StoredSession {
  token: string;
  expiresAt: string;
}

function storage(): Storage | null {
  try {
    return globalThis.localStorage ?? null;
  } catch {
    return null;
  }
}

export function readStoredSession(): StoredSession | null {
  const store = storage();
  if (!store) return null;
  let raw: string | null;
  try {
    raw = store.getItem(STORAGE_KEY);
  } catch {
    return null;
  }
  if (!raw) return null;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) return null;
    const { token, expiresAt } = parsed as Record<string, unknown>;
    if (typeof token !== 'string' || token === '') return null;
    if (typeof expiresAt !== 'string' || expiresAt === '') return null;
    // Un `expiresAt` que no es una fecha parseable no permite aplicar el chequeo local de
    // expiración de RN-11: se descarta el registro entero.
    if (Number.isNaN(Date.parse(expiresAt))) return null;
    return { token, expiresAt };
  } catch {
    return null;
  }
}

export function writeStoredSession(session: StoredSession): void {
  const store = storage();
  if (!store) return;
  try {
    store.setItem(STORAGE_KEY, JSON.stringify(session));
  } catch {
    /* almacenamiento no disponible: la sesión queda sólo en memoria */
  }
}

export function clearStoredSession(): void {
  const store = storage();
  if (!store) return;
  try {
    store.removeItem(STORAGE_KEY);
  } catch {
    /* nada que limpiar si el almacenamiento no está disponible */
  }
}

/** `true` si la expiración registrada ya pasó (chequeo **local** de RN-11). */
export function isExpired(session: StoredSession, now: number = Date.now()): boolean {
  const expiresAtMs = Date.parse(session.expiresAt);
  if (Number.isNaN(expiresAtMs)) return true;
  return expiresAtMs <= now;
}
/**
 * Estado de sesión del cliente (HU-10-01 RN-3, RN-7, RN-9, RN-11).
 *
 * Máquina de estados:
 *
 *   validating ──(GET /me → 200)──────────────► authenticated
 *        │                                            │
 *        ├─(sin token | token expirado local | 401)──►│
 *        │                                            │
 *        ▼                                            ▼
 *     anonymous ◄──(UNAUTHENTICATED en llamada protegida: limpia sesión + aviso)──┘
 *
 * `validating` es el estado inicial sólo si hay un token persistido y no expirado: en ese
 * caso la validez la decide el servidor con una llamada liviana `GET /me` (RN-11), no la
 * inspección del token.
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { ApiClient, type FetchLike } from '../api/client';
import { getProfile } from '../api/auth';
import { ApiError, SESSION_EXPIRED_MESSAGE } from '../api/errors';
import type { Profile } from '../api/auth';
import {
  clearStoredSession,
  isExpired,
  readStoredSession,
  writeStoredSession,
  type StoredSession,
} from './storage';

export type SessionStatus = 'validating' | 'anonymous' | 'authenticated';

export interface SessionContextValue {
  status: SessionStatus;
  /** Perfil de la cuenta autenticada, cuando la validación de RN-11 lo devolvió. */
  profile: Profile | null;
  /** Aviso a mostrar en la pantalla de login (p. ej. sesión expirada, RN-7). */
  notice: string | null;
  /** La validación de RN-11 no pudo completarse por falta de conexión (no hubo 401). */
  validationUnavailable: boolean;
  api: ApiClient;
  /** Establece la sesión tras un login exitoso (RN-3). */
  establish(session: StoredSession): void;
  /** Limpia la sesión local; con `notice` muestra un aviso al volver a login (RN-7). */
  clear(notice?: string | null): void;
  /** Reintenta la validación de sesión de RN-11 (usado cuando falló por red). */
  revalidate(): void;
  /** Descarta el aviso pendiente (se consume al mostrarlo). */
  dismissNotice(): void;
}

const SessionContext = createContext<SessionContextValue | null>(null);

export interface SessionProviderProps {
  children: ReactNode;
  /** Sobrescribe el prefijo de la API (tests / configuración explícita). */
  baseUrl?: string;
  /** Sobrescribe la implementación de `fetch` (tests). */
  fetchImpl?: FetchLike;
}

export function SessionProvider({ children, baseUrl, fetchImpl }: SessionProviderProps) {
  // Token en memoria de la SPA (RN-3): la copia persistida es sólo para sobrevivir recargas.
  const tokenRef = useRef<string | null>(null);
  const onUnauthenticatedRef = useRef<() => void>(() => {});
  // Identifica la validación en curso: una sesión establecida o limpiada mientras el
  // `GET /me` viaja invalida su resultado.
  const generationRef = useRef(0);

  const [status, setStatus] = useState<SessionStatus>('anonymous');
  const [profile, setProfile] = useState<Profile | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [validationUnavailable, setValidationUnavailable] = useState(false);

  const api = useMemo(
    () =>
      new ApiClient({
        ...(baseUrl !== undefined ? { baseUrl } : {}),
        ...(fetchImpl !== undefined ? { fetchImpl } : {}),
        getToken: () => tokenRef.current,
        onUnauthenticated: () => onUnauthenticatedRef.current(),
      }),
    [baseUrl, fetchImpl],
  );

  const clear = useCallback((nextNotice: string | null = null) => {
    generationRef.current += 1;
    tokenRef.current = null;
    clearStoredSession();
    setProfile(null);
    setValidationUnavailable(false);
    setStatus('anonymous');
    setNotice(nextNotice);
  }, []);

  // RN-7 / RNE-4: `UNAUTHENTICATED` en cualquier llamada protegida limpia la sesión local y
  // devuelve al login con el aviso de sesión expirada. Se registra antes del efecto de
  // validación de más abajo (los efectos corren en orden de declaración), así que ninguna
  // request puede resolver sin el handler puesto.
  useEffect(() => {
    onUnauthenticatedRef.current = () => clear(SESSION_EXPIRED_MESSAGE);
  }, [clear]);

  const establish = useCallback((session: StoredSession) => {
    generationRef.current += 1;
    tokenRef.current = session.token;
    writeStoredSession(session);
    setNotice(null);
    setValidationUnavailable(false);
    setProfile(null);
    setStatus('authenticated');
  }, []);

  const validate = useCallback(() => {
    const stored = readStoredSession();
    // Token ausente, o expirado según la expiración registrada: se limpia todo estado de
    // sesión local y se permanece en login (RN-11). No se muestra aviso de expiración: el
    // de RN-7 corresponde a una sesión que estaba activa y se cayó, no al arranque.
    if (!stored || isExpired(stored)) {
      if (stored) clearStoredSession();
      tokenRef.current = null;
      setProfile(null);
      setValidationUnavailable(false);
      setStatus('anonymous');
      return;
    }

    const generation = generationRef.current + 1;
    generationRef.current = generation;
    tokenRef.current = stored.token;
    setValidationUnavailable(false);
    setStatus('validating');

    // La validez la decide el servidor (RNE-2): 200 ⇒ sesión válida; 401 ⇒ se limpia.
    getProfile(api, { handleUnauthenticated: false }).then(
      (loaded) => {
        if (generationRef.current !== generation) return;
        setProfile(loaded);
        setStatus('authenticated');
      },
      (error: unknown) => {
        if (generationRef.current !== generation) return;
        if (error instanceof ApiError && error.code === 'UNAUTHENTICATED') {
          tokenRef.current = null;
          clearStoredSession();
          setProfile(null);
          setStatus('anonymous');
          return;
        }
        // Sin respuesta del servidor no hay veredicto: sólo un 401 invalida la sesión
        // (RNE-2). Se muestra el login con el aviso de conexión y opción de reintentar,
        // conservando el token persistido.
        setValidationUnavailable(true);
        setStatus('anonymous');
      },
    );
  }, [api]);

  useEffect(() => {
    validate();
  }, [validate]);

  const value = useMemo<SessionContextValue>(
    () => ({
      status,
      profile,
      notice,
      validationUnavailable,
      api,
      establish,
      clear,
      revalidate: validate,
      dismissNotice: () => setNotice(null),
    }),
    [status, profile, notice, validationUnavailable, api, establish, clear, validate],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): SessionContextValue {
  const value = useContext(SessionContext);
  if (!value) throw new Error('useSession requiere un <SessionProvider> ancestro');
  return value;
}

