  INTERNAL_ERROR: 500,
} as const;

export type ErrorCode = keyof typeof ERROR_HTTP_STATUS;

export type ErrorDetails = Record<string, unknown>;

export interface ErrorEnvelope {
  error: {
    code: ErrorCode;
    message: string;
    details?: ErrorDetails;
  };
}

/** Error de dominio con `code` del catálogo. Su status HTTP se deriva del catálogo. */
export class AppError extends Error {
  readonly code: ErrorCode;
  readonly details?: ErrorDetails;
  /** Headers extra a agregar en la respuesta (p. ej. `Retry-After`). */
  readonly headers?: Record<string, string>;

  constructor(
    code: ErrorCode,
    message: string,
    details?: ErrorDetails,
    headers?: Record<string, string>,
  ) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.details = details;
    this.headers = headers;
  }

  get httpStatus(): number {
    return ERROR_HTTP_STATUS[this.code];
  }

  toEnvelope(): ErrorEnvelope {
    const envelope: ErrorEnvelope = {
      error: { code: this.code, message: this.message },
    };
    if (this.details !== undefined) envelope.error.details = this.details;
    return envelope;
  }
}

/** Una causa de fallo de esquema, tal como se serializa en `details.issues`. */
export interface ValidationIssue {
  field: string;
  message: string;
}

export function validationError(issues: ValidationIssue[], message?: string): AppError {
  return new AppError(
    'VALIDATION_ERROR',
    message ?? 'El payload no cumple el esquema esperado.',
    { issues },
  );
}

export function unauthenticated(): AppError {
  // El mensaje no distingue el motivo (token ausente / inválido / expirado): HU-09-02 RN-3.
  return new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
}

/**
 * Asignación y consulta de direcciones de depósito (HU-06-03, HU-06-04).
 *
 * Biyección cuenta ↔ `address_index` ↔ dirección: el índice es único, monótono creciente
 * desde 0, sin reúso e inmutable (INV-EPICA-06-A). La única fuente de huecos admitida es un
 * índice que produzca una clave BIP-32 inválida (~2⁻¹²⁷), que se salta de forma
 * determinista y queda auditado en `derivation_skips` (HU-06-03 RN-1 / HU-06-02 RN-8).
 */
import { EventEmitter } from 'node:events';
import { AppError } from '../../core/errors';
import { CHAIN_ID, NETWORK_NAME } from '../../core/config';
import { nowIso } from '../../core/time';
import { isUniqueConstraintError, transaction, type Db } from '../../db/index';
import { MAX_ADDRESS_INDEX, deriveAccountFromIndexOrNext } from '../../wallet/hd';

export interface DepositAddressRecord {
  accountId: string;
  addressIndex: number;
  address: string;
  derivationPath: string;
  network: string;
  chainId: string;
  createdAt: string;
}

export interface DepositAddressAssignedEvent {
  accountId: string;
  addressIndex: number;
  address: string;
  chainId: string;
}

export const DEPOSIT_ADDRESS_ASSIGNED = 'DepositAddressAssigned';

export class WalletService {
  readonly events = new EventEmitter();
  private pendingEvents: DepositAddressAssignedEvent[] = [];

  constructor(private readonly db: Db, private readonly seed: Buffer) {}

  find(accountId: string): DepositAddressRecord | undefined {
    return this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses WHERE account_id = ?`,
      )
      .get(accountId) as DepositAddressRecord | undefined;
  }

  listAll(): DepositAddressRecord[] {
    return this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses ORDER BY address_index ASC`,
      )
      .all() as unknown as DepositAddressRecord[];
  }

  /**
   * Asigna la dirección de la cuenta **dentro de una transacción ya abierta** (alta de
   * cuenta, HU-06-03 RN-12). Es idempotente: si la cuenta ya tiene índice, no hace nada.
   */
  assignForAccountInTransaction(accountId: string): DepositAddressRecord {
    const existing = this.find(accountId);
    if (existing) return existing;

    // RN-10: sólo se asigna dirección a una cuenta existente. Se verifica **antes** de
    // derivar y de tocar el contador de índices, de modo que una referencia inválida no
    // consume un índice ni produce una dirección (AT-06-03-08).
    const account = this.db
      .prepare('SELECT 1 AS present FROM accounts WHERE account_id = ?')
      .get(accountId) as { present: number } | undefined;
    if (!account) {
      throw new AppError('ACCOUNT_NOT_FOUND', 'La cuenta referenciada no existe.', { accountId });
    }

    const row = this.db
      .prepare('SELECT MAX(address_index) AS maxIndex FROM deposit_addresses')
      .get() as { maxIndex: number | null };
    const startIndex = row.maxIndex === null ? 0 : row.maxIndex + 1;
    if (startIndex > MAX_ADDRESS_INDEX) {
      // HU-06-03 RN-13: nunca se produce silenciosamente un índice hardened.
      throw new AppError(
        'INTERNAL_ERROR',
        'Se agotó el espacio de índices de derivación no-hardened.',
      );
    }

    const derived = deriveAccountFromIndexOrNext(this.seed, startIndex);
    // Auditoría de índices saltados por clave BIP-32 inválida (RN-1).
    for (let skipped = startIndex; skipped < derived.addressIndex; skipped += 1) {
      this.db
        .prepare(
          'INSERT OR IGNORE INTO derivation_skips (address_index, reason, created_at) VALUES (?, ?, ?)',
        )
        .run(skipped, 'INVALID_BIP32_KEY', nowIso());
    }

    const record: DepositAddressRecord = {
      accountId,
      addressIndex: derived.addressIndex,
      address: derived.address,
      derivationPath: derived.derivationPath,
      network: NETWORK_NAME,
      chainId: CHAIN_ID,
      createdAt: nowIso(),
    };
    this.db
      .prepare(
        `INSERT INTO deposit_addresses
           (account_id, address_index, address, derivation_path, network, chain_id, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        record.accountId,
        record.addressIndex,
        record.address,
        record.derivationPath,
        record.network,
        record.chainId,
        record.createdAt,
      );

    const event: DepositAddressAssignedEvent = {
      accountId: record.accountId,
      addressIndex: record.addressIndex,
      address: record.address,
      chainId: record.chainId,
    };
    // El evento de dominio se persiste dentro de la misma transacción (queda disponible
    // para la épica 07 aunque el proceso caiga inmediatamente después) y se publica
    // in-process recién tras el commit.
    this.db
      .prepare('INSERT INTO domain_events (type, payload, created_at) VALUES (?, ?, ?)')
      .run(DEPOSIT_ADDRESS_ASSIGNED, JSON.stringify(event), record.createdAt);
    this.pendingEvents.push(event);
    return record;
  }

  /** Publica los eventos encolados por asignaciones ya committeadas (HU-06-03 RN-11). */
  publishPendingEvents(): void {
    const events = this.pendingEvents;
    this.pendingEvents = [];
    for (const event of events) {
      this.events.emit(DEPOSIT_ADDRESS_ASSIGNED, event);
    }
  }

  /**
   * Fallback idempotente de HU-06-04 RN-5: devuelve la dirección de la cuenta y, si no
   * existiera, la asigna. Nunca asigna un segundo índice a una cuenta que ya tiene uno.
   */
  getOrAssign(accountId: string): DepositAddressRecord {
    const existing = this.find(accountId);
    if (existing) return existing;
    let record: DepositAddressRecord;
    try {
      record = transaction(this.db, () => this.assignForAccountInTransaction(accountId));
    } catch (err) {
      if (isUniqueConstraintError(err)) {
        // Otra asignación concurrente ganó la carrera: se devuelve la ya persistida.
        const winner = this.find(accountId);
        if (winner) return winner;
      }
      throw err;
    }
    this.publishPendingEvents();
    return record;
  }

  /** Eventos de dominio persistidos (inspección interna / épica 07 al arrancar). */
  listEvents(type = DEPOSIT_ADDRESS_ASSIGNED): DepositAddressAssignedEvent[] {
    const rows = this.db
      .prepare('SELECT payload FROM domain_events WHERE type = ? ORDER BY id ASC')
      .all(type) as unknown as { payload: string }[];
    return rows.map((r) => JSON.parse(r.payload) as DepositAddressAssignedEvent);
  }
}
=====CONFIG=====
/**
 * Configuración del backend, leída del entorno y validada al arranque.
 *
 * Una configuración inválida **impide el arranque** (no se inicia el servicio en estado
 * inválido): HU-01-02 RN-3 (rango del TTL) y HU-06-01 RN-6/RN-11 (credencial de cifrado).
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import { isValidChecksumAddress, toChecksumAddress } from '../wallet/hd';

/** Red única del proyecto: Sepolia (spec/00-fundaciones/activos-y-par-de-trading.md §1). */
export const CHAIN_ID = '11155111';
export const NETWORK_NAME = 'sepolia';
/** Confirmaciones requeridas (constante fundacional; la consumen las épicas 07/08). */
export const CONFIRMACIONES_REQUERIDAS = 12;

export class ConfigError extends Error {}

export interface RateLimitPolicy {
  enabled: boolean;
  max: number;
  windowSeconds: number;
}

export interface Config {
  host: string;
  port: number;
  databasePath: string;
  /** TTL del token de sesión en segundos; entero en [60, 86400] (HU-01-02 RN-3). */
  sessionTtlSeconds: number;
  /**
   * Credencial de cifrado del seed **tal como viene del entorno**, sin decodificar
   * (HU-06-01 RN-6). Ni su ausencia ni su formato inválido se resuelven acá: ambos casos
   * los decide el provisioning, que es el único punto donde se distingue "no hay seed
   * todavía" (`VALIDATION_ERROR`) de "hay un seed persistido que no se puede descifrar"
   * (`INTERNAL_ERROR`, AT-06-01-11) — la credencial ausente **o incorrecta** sobre un seed
   * ya persistido aborta siempre con `INTERNAL_ERROR`.
   */
  walletEncryptionKeyRaw?: string;
  /** Mnemonic importado por configuración (opcional); si falta, se genera uno nuevo. */
  walletMnemonic?: string;
  walletMnemonicPassphrase: string;
  /** Dirección del contrato USDC-mock del entorno (checksum EIP-55). */
  usdcContractAddress: string;
  /** Endpoint JSON-RPC de Sepolia (opcional en esta etapa; sin default de terceros). */
  ethRpcUrl: string;
  /** Rate limit por cuenta y endpoint para endpoints autenticados (HU-09-02 RN-12). */
  apiRateLimit: RateLimitPolicy;
  /** Anti-flood del registro (HU-01-01 RN-10); desactivado salvo configuración explícita. */
  registerRateLimit: RateLimitPolicy;
  /** Anti-fuerza-bruta del login sobre intentos fallidos (HU-01-02 RN-9). */
  loginRateLimit: RateLimitPolicy;
  /** Token para las rutas internas (`/internal/*`); si falta, sólo se admite loopback. */
  internalApiToken?: string;
  /**
   * Orígenes exactos habilitados para CORS (`CORS_ALLOWED_ORIGINS`). Lista **vacía** =
   * CORS deshabilitado (el backend no emite ningún header de CORS), que es el default.
   * La spec no define CORS; es soporte de despliegue para el cliente web de la épica 10,
   * que corre en otro origen (`http://localhost:5173` en desarrollo).
   */
  corsAllowedOrigins: string[];
  logLevel: string;
}

function readEnvFile(file: string): void {
  if (!fs.existsSync(file)) return;
  const content = fs.readFileSync(file, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
      (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
    ) {
      value = value.slice(1, -1);
    }
    if (process.env[key] === undefined) process.env[key] = value;
  }
}

function parseIntStrict(value: string, name: string): number {
  if (!/^-?\d+$/.test(value.trim())) {
    throw new ConfigError(`${name} debe ser un entero; se recibió "${value}".`);
  }
  return Number.parseInt(value.trim(), 10);
}

function parseBool(value: string | undefined, fallback: boolean): boolean {
  if (value === undefined || value.trim() === '') return fallback;
  const v = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(v)) return true;
  if (['0', 'false', 'no', 'off'].includes(v)) return false;
  throw new ConfigError(`Valor booleano inválido: "${value}".`);
}

/** Credencial de cifrado con formato/longitud inválidos (la clasifica el provisioning). */
export class EncryptionKeyFormatError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EncryptionKeyFormatError';
  }
}

/**
 * Decodifica la credencial AES-256-GCM del entorno (64 hex, con o sin `0x`, o base64 de 32
 * bytes). El mensaje de error nunca incluye el valor recibido (HU-06-01 RN-5).
 */
export function decodeEncryptionKey(raw: string): Buffer {
  const value = raw.trim();
  let buf: Buffer;
  if (/^(0x)?[0-9a-fA-F]{64}$/.test(value)) {
    buf = Buffer.from(value.replace(/^0x/, ''), 'hex');
  } else {
    buf = Buffer.from(value, 'base64');
  }
  if (buf.length !== 32) {
    throw new EncryptionKeyFormatError(
      'WALLET_ENCRYPTION_KEY debe ser una clave de 32 bytes (64 hex o 44 caracteres base64). ' +
        'Podés generar una con: npm run genkey',
    );
  }
  return buf;
}

function rateLimitFrom(
  env: NodeJS.ProcessEnv,
  enabledVar: string,
  maxVar: string,
  windowVar: string,
  defaults: RateLimitPolicy,
  /**
   * `true` para las políticas **opcionales** de la épica 01: cuando se activan, umbral y
   * ventana son obligatorios y deben estar declarados en el entorno (HU-01-01 RN-10,
   * HU-01-02 RN-9); activarlas sin declararlos impide el arranque en vez de caer en
   * defaults silenciosos. `false` para el límite de HU-09-02 RN-12, cuyos parámetros
   * (60 req / 60 s por cuenta y endpoint) los fija la propia spec.
   */
  parametersRequiredWhenEnabled: boolean,
): RateLimitPolicy {
  const enabled = parseBool(env[enabledVar], defaults.enabled);
  if (!enabled) return { enabled: false, max: defaults.max, windowSeconds: defaults.windowSeconds };
  const rawMax = env[maxVar];
  const rawWindow = env[windowVar];
  const declaredMax = rawMax !== undefined && rawMax.trim() !== '';
  const declaredWindow = rawWindow !== undefined && rawWindow.trim() !== '';
  if (parametersRequiredWhenEnabled && (!declaredMax || !declaredWindow)) {
    const faltantes = [!declaredMax ? maxVar : null, !declaredWindow ? windowVar : null]
      .filter((name): name is string => name !== null)
      .join(' y ');
    throw new ConfigError(
      `Con ${enabledVar}=true, el umbral y la ventana del rate limiting son obligatorios y ` +
        `deben estar declarados en el entorno; falta declarar ${faltantes}.`,
    );
  }
  const max = declaredMax ? parseIntStrict(rawMax as string, maxVar) : defaults.max;
  const windowSeconds = declaredWindow
    ? parseIntStrict(rawWindow as string, windowVar)
    : defaults.windowSeconds;
  if (max <= 0) throw new ConfigError(`${maxVar} debe ser un entero positivo.`);
  if (windowSeconds <= 0) throw new ConfigError(`${windowVar} debe ser un entero positivo.`);
  return { enabled: true, max, windowSeconds };
}

/**
 * Normaliza la dirección del contrato USDC del entorno a `0x` + 40 hex con checksum EIP-55
 * (HU-09-01 RN-10 / HU-06-04 RN-6): es el valor que se emite como `tokenAddress`.
 *
 * - Formato inválido (no son 40 hex con prefijo `0x`) ⇒ no se arranca.
 * - Caja mixta ⇒ debe traer un checksum EIP-55 correcto; si no coincide, se trata como
 *   error de tipeo y no se arranca.
 * - Toda en minúsculas o toda en mayúsculas (formas "sin checksum" según EIP-55) ⇒ se
 *   normaliza a la forma con checksum.
 */
export function normalizeContractAddress(raw: string, name: string): string {
  const value = raw.trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(value)) {
    throw new ConfigError(
      `${name} debe ser una dirección Ethereum: "0x" seguido de 40 dígitos hexadecimales; ` +
        `se recibió "${value}".`,
    );
  }
  const body = value.slice(2);
  const hasMixedCase = body !== body.toLowerCase() && body !== body.toUpperCase();
  if (hasMixedCase && !isValidChecksumAddress(value)) {
    throw new ConfigError(
      `${name} tiene caja mixta pero su checksum EIP-55 no verifica; ` +
        `la forma correcta de esa dirección es ${toChecksumAddress(value)}.`,
    );
  }
  return toChecksumAddress(value);
}

/**
 * Parsea `CORS_ALLOWED_ORIGINS`: lista separada por comas de orígenes **exactos**
 * (`esquema://host[:puerto]`), p. ej. `http://localhost:5173,http://127.0.0.1:5173`.
 *
 * Vacía o ausente ⇒ lista vacía ⇒ CORS deshabilitado. Un origen mal formado (con path,
 * query, fragmento, credenciales, esquema no HTTP(S), o el comodín `*`) **impide el
 * arranque**, con el mismo mecanismo que el resto de las validaciones de configuración.
 * Se tolera una barra final (`http://host:5173/`) y se normaliza.
 */
export function parseCorsAllowedOrigins(raw: string | undefined): string[] {
  if (raw === undefined || raw.trim() === '') return [];
  const origins: string[] = [];
  for (const part of raw.split(',')) {
    const value = part.trim().replace(/\/$/, '');
    if (value === '') continue;
    if (value === '*') {
      throw new ConfigError(
        'CORS_ALLOWED_ORIGINS no admite el comodín "*": hay que listar orígenes exactos.',
      );
    }
    let url: URL;
    try {
      url = new URL(value);
    } catch {
      throw new ConfigError(
        `CORS_ALLOWED_ORIGINS debe listar orígenes con la forma "esquema://host[:puerto]"; ` +
          `se recibió "${value}".`,
      );
    }
    const wellFormed =
      (url.protocol === 'http:' || url.protocol === 'https:') &&
      url.username === '' &&
      url.password === '' &&
      url.search === '' &&
      url.hash === '' &&
      (url.pathname === '' || url.pathname === '/') &&
      url.origin === value;
    if (!wellFormed) {
      throw new ConfigError(
        `CORS_ALLOWED_ORIGINS debe listar orígenes exactos "esquema://host[:puerto]" (http o ` +
          `https, sin path, query, fragmento ni credenciales); se recibió "${value}".`,
      );
    }
    if (!origins.includes(url.origin)) origins.push(url.origin);
  }
  return origins;
}

/**
 * Dirección por defecto del USDC-mock en Sepolia. Es un parámetro del despliegue
 * (spec/00-fundaciones/activos-y-par-de-trading.md §2.2): se sobreescribe con
 * `USDC_CONTRACT_ADDRESS`.
 */
export const DEFAULT_USDC_CONTRACT_ADDRESS = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238';

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  if (parseBool(env.LOAD_DOTENV, true)) {
    readEnvFile(path.resolve(process.cwd(), '.env'));
  }

  const port = env.PORT ? parseIntStrict(env.PORT, 'PORT') : 3000;
  if (port < 0 || port > 65535) throw new ConfigError('PORT fuera de rango.');

  const sessionTtlSeconds = env.SESSION_TTL_SECONDS
    ? parseIntStrict(env.SESSION_TTL_SECONDS, 'SESSION_TTL_SECONDS')
    : 3600;
  // HU-01-02 RN-3: TTL entero positivo en [60, 86400]; fuera de rango => no se arranca.
  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86400) {
    throw new ConfigError(
      `SESSION_TTL_SECONDS debe ser un entero en el rango [60, 86400]; se recibió ${sessionTtlSeconds}.`,
    );
  }

  const chainIdEnv = (env.CHAIN_ID ?? CHAIN_ID).trim();
  if (chainIdEnv !== CHAIN_ID) {
    throw new ConfigError(
      `La única red soportada es Sepolia (chainId ${CHAIN_ID}); se configuró ${chainIdEnv}.`,
    );
  }

  return {
    host: env.HOST?.trim() || '0.0.0.0',
    port,
    databasePath: env.DATABASE_PATH?.trim() || path.resolve(process.cwd(), 'data', 'exchange.db'),
    sessionTtlSeconds,
    walletEncryptionKeyRaw: env.WALLET_ENCRYPTION_KEY,
    walletMnemonic: env.WALLET_MNEMONIC?.trim() ? env.WALLET_MNEMONIC.trim() : undefined,
    walletMnemonicPassphrase: env.WALLET_MNEMONIC_PASSPHRASE ?? '',
    usdcContractAddress: normalizeContractAddress(
      env.USDC_CONTRACT_ADDRESS?.trim() || DEFAULT_USDC_CONTRACT_ADDRESS,
      'USDC_CONTRACT_ADDRESS',
    ),
    ethRpcUrl: env.ETH_RPC_URL?.trim() || '',
    apiRateLimit: rateLimitFrom(
      env,
      'API_RATE_LIMIT_ENABLED',
      'API_RATE_LIMIT_MAX',
      'API_RATE_LIMIT_WINDOW_SECONDS',
      // HU-09-02 RN-12: 60 requests por minuto, por cuenta y por endpoint.
      { enabled: true, max: 60, windowSeconds: 60 },
      false,
    ),
    registerRateLimit: rateLimitFrom(
      env,
      'REGISTER_RATE_LIMIT_ENABLED',
      'REGISTER_RATE_LIMIT_MAX',
      'REGISTER_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-01 RN-10: opcional; desactivado salvo configuración explícita del entorno.
      { enabled: false, max: 20, windowSeconds: 60 },
      true,
    ),
    loginRateLimit: rateLimitFrom(
      env,
      'LOGIN_RATE_LIMIT_ENABLED',
      'LOGIN_RATE_LIMIT_MAX_FAILURES',
      'LOGIN_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-02 RN-9: opcional; cuenta intentos fallidos por (origen, email).
      { enabled: false, max: 5, windowSeconds: 60 },
      true,
    ),
    internalApiToken: env.INTERNAL_API_TOKEN?.trim() || undefined,
    corsAllowedOrigins: parseCorsAllowedOrigins(env.CORS_ALLOWED_ORIGINS),
    logLevel: env.LOG_LEVEL?.trim() || 'info',
  };
}

