/**
 * Utilidades de direcciones Ethereum (EIP-55) para el cliente mobile.
 *
 * Se usan en dos lugares de HU-11-06:
 *  - **Depósito (RN-2 / AT-11-06-01):** la dirección se muestra en texto con checksum
 *    EIP-55 y se codifica en el QR (ver `eip681.ts`).
 *  - **Retiro (RN-5 / AT-11-06-06):** feedback temprano sobre la dirección destino, y
 *    validación del address extraído de un QR escaneado (RN-9 / AT-11-06-13).
 *
 * El backend sigue siendo **autoritativo** (responde `INVALID_ADDRESS` 422 ante un destino
 * inválido, RN-5): este módulo sólo adelanta el diagnóstico en el cliente, con la **misma
 * semántica** que la implementación del backend (`src/wallet/hd.ts`, HU-06-02 RN-4), para
 * que cliente y servidor no discrepen sobre qué direcciones son válidas.
 *
 * Módulo TypeScript puro: sin React Native, sin `node:crypto` ni ninguna API de Node.
 * El Keccak-256 viene de `@noble/hashes` (JS puro, funciona en Hermes/React Native).
 */

import { keccak_256 } from '@noble/hashes/sha3';
import { utf8ToBytes } from '@noble/hashes/utils';

/** `0x` + 40 dígitos hexadecimales, en cualquier caja (forma sintáctica de RN-2/RN-5). */
const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;

/**
 * `true` si `value` tiene la **forma** de una dirección Ethereum: `0x` + 40 hex.
 *
 * NO mira el checksum EIP-55: separa el error de formato (largo/prefijo/caracteres) del
 * error de checksum, para que la UI pueda dar mensajes distintos mientras el usuario
 * todavía está tipeando el destino (RN-5, feedback temprano).
 */
export function isAddressLike(value: string): boolean {
  return typeof value === 'string' && ADDRESS_RE.test(value);
}

/**
 * Devuelve la dirección con checksum EIP-55.
 *
 * Acepta la entrada con o sin prefijo `0x` y en cualquier caja (por ejemplo la forma
 * enteramente en minúsculas que puede devolver un explorer o un QR ajeno). El algoritmo es
 * el del EIP-55: `Keccak-256` sobre la cadena ASCII del hexadecimal en minúsculas (sin
 * `0x`), y se pasa a mayúscula el dígito `i` si el nibble `i` del hash es `>= 8`.
 *
 * Lanza si la entrada no es `0x` + 40 hex: no hay "mejor esfuerzo" posible sobre una
 * dirección de otro largo, y silenciar el caso podría terminar generando un QR hacia una
 * dirección que no existe (RN-2).
 */
export function toChecksumAddress(value: string): string {
  if (typeof value !== 'string') {
    throw new Error('dirección inválida: se esperaba una cadena de texto');
  }
  const raw = value.startsWith('0x') || value.startsWith('0X') ? value.slice(2) : value;
  if (!/^[0-9a-fA-F]{40}$/.test(raw)) {
    throw new Error('dirección inválida: se esperan 40 dígitos hexadecimales (20 bytes)');
  }
  const lower = raw.toLowerCase();

  const hash = keccak_256(utf8ToBytes(lower));
  let out = '0x';
  for (let i = 0; i < lower.length; i++) {
    const ch = lower[i]!;
    // nibble i del hash: byte i>>1, mitad alta si i es par.
    const nibble = i % 2 === 0 ? hash[i >> 1]! >> 4 : hash[i >> 1]! & 0x0f;
    out += nibble >= 8 ? ch.toUpperCase() : ch;
  }
  return out;
}

/**
 * `true` si `value` es `0x` + 40 hex **y** su checksum EIP-55 verifica (RN-5).
 *
 * Decisión deliberada, idéntica a la del backend (`src/wallet/hd.ts`): una dirección
 * **enteramente en minúsculas** o **enteramente en mayúsculas** devuelve `false`, porque no
 * transporta un checksum EIP-55 verificable (el EIP las considera "sin checksum"; que
 * coincidieran con la forma canónica sería casualidad). Aceptarlas acá haría que el cliente
 * diera por buena una dirección que el backend rechaza con `INVALID_ADDRESS` (422).
 *
 * Único caso en que la regla anterior no aplica: direcciones **sin ningún dígito alfabético**
 * (`a`-`f`), donde minúsculas y mayúsculas son la misma cadena y el checksum sí es
 * verificable sin ambigüedad; ahí se compara contra la forma canónica.
 */
export function isValidChecksumAddress(value: string): boolean {
  if (!isAddressLike(value)) return false;
  const body = value.slice(2);
  const hasCase = body.toLowerCase() !== body.toUpperCase();
  if (hasCase && (body === body.toLowerCase() || body === body.toUpperCase())) return false;
  return toChecksumAddress(body) === value;
}
