/**
 * Cliente del **canal WebSocket privado** del usuario (HU-09-04) con el ciclo de vida y la
 * reconexión que exige el cliente mobile (épica 11: RG-5, RG-10, RG-11; HU-11-01 RN-12).
 *
 * Decisiones que fija la spec y que este módulo implementa al pie de la letra:
 *
 * - **Handshake (HU-09-04 RN-1):** apenas abre el socket, el **primer** mensaje es
 *   `{"type":"auth","token":"<token>"}`. El token **nunca** viaja en la URL/query (RN-1 lo
 *   prohíbe explícitamente para no exponerlo en logs) ni se loggea (HU-11-01 RN-7 /
 *   AT-11-01-11): en este archivo no hay una sola llamada a `console.*`.
 * - **Suscripción (HU-09-04 RN-2):** tras `{"type":"authenticated"}` se envía un
 *   `{"type":"subscribe","channel":...}` por cada canal configurado.
 * - **`UNAUTHENTICATED` (HU-11-01 RN-12 / AT-11-01-12):** llegue en el handshake o en un
 *   mensaje del canal ya autenticado, se avisa **una sola vez por intento** vía
 *   `onUnauthenticated(tokenUsed)`, se cierra el socket y **no** se reintenta: el servidor ya
 *   rechazó ese token, así que reintentar sería un bucle. El manejo de sesión (logout
 *   singleton, RG-8) vive fuera de este módulo; acá sólo se notifica con el token usado para
 *   que un 401 tardío de una sesión ya reemplazada pueda descartarse.
 * - **Backoff (RG-10):** 1 s inicial, factor 2×, tope 30 s, jitter ±500 ms, reintentos
 *   indefinidos mientras la pantalla esté en foreground. El contador se resetea tras una
 *   conexión exitosa (`authenticated`).
 * - **Ciclo de vida (RG-5):** en `background`/`inactive` se cierra el socket y se cancelan los
 *   timers (estado `suspended`); al volver a `active` se reconecta de inmediato, y como la
 *   reconexión implica un nuevo `auth` + nuevos `subscribe`, el servidor manda un **snapshot
 *   fresco** antes de los deltas (RG-API-7), o sea que la re-sincronización es la propia
 *   re-suscripción.
 * - **Testabilidad (RG-11):** el WebSocket, los timers y la fuente del jitter son
 *   inyectables, de modo que los tests no dependen del tiempo real ni de un socket real.
 *
 * El módulo es autónomo: no importa React ni `react-native`. El ciclo de vida entra por
 * `handleAppStateChange`, que la capa de UI alimenta con el `AppState` de React Native.
 */

export type ConnectionStatus = 'idle' | 'connecting' | 'live' | 'reconnecting' | 'suspended';

/** Parámetros de reconexión del contrato de evaluación (RG-10). */
export const BACKOFF_INITIAL_MS = 1000;
export const BACKOFF_FACTOR = 2;
export const BACKOFF_MAX_MS = 30000;
export const BACKOFF_JITTER_MS = 500;

/** Canales privados del contrato (HU-09-04 RN-2). */
export type PrivateChannelName = 'orders' | 'balances' | 'withdrawals';

/** Evento de mensaje mínimo que consumimos del socket. */
export interface WebSocketMessageEventLike {
  data: unknown;
}

/** Instancia mínima de socket que necesita este cliente. */
export interface WebSocketInstanceLike {
  send(data: string): void;
  close(code?: number, reason?: string): void;
  onopen: ((event?: unknown) => void) | null;
  onmessage: ((event: WebSocketMessageEventLike) => void) | null;
  onerror: ((event?: unknown) => void) | null;
  onclose: ((event?: unknown) => void) | null;
}

/**
 * Constructor de WebSocket (el global del runtime, o un doble en los tests — RG-11).
 * Recibe **sólo** la url: el token va en el primer mensaje, nunca en la url (HU-09-04 RN-1).
 */
export type WebSocketLike = new (url: string) => WebSocketInstanceLike;

export interface PrivateChannelOptions {
  /** URL del WS (`ws://host/api/v1/ws`, RG-API-11). */
  url: string;
  /** Token vigente del almacenamiento seguro; `null` si no hay sesión. */
  getToken: () => string | null;
  /**
   * Se invoca cuando el canal recibe `UNAUTHENTICATED` (handshake o mensaje del canal).
   * Recibe el token con el que se autenticó ese intento, para que el manejo de sesión
   * pueda ignorar un 401 tardío de una sesión ya reemplazada (RN-12 + RG-8).
   */
  onUnauthenticated: (tokenUsed: string | null) => void;
  /** Canales privados a los que suscribirse al autenticar. */
  channels?: PrivateChannelName[];
  /** Mensajes ya parseados del servidor (snapshot/deltas). */
  onMessage?: (message: unknown) => void;
  onStatusChange?: (status: ConnectionStatus) => void;
  /** Inyectables para tests (RG-11). */
  webSocketImpl?: WebSocketLike;
  setTimeoutImpl?: typeof setTimeout;
  clearTimeoutImpl?: typeof clearTimeout;
  random?: () => number;
}

type TimerHandle = ReturnType<typeof setTimeout>;

/** Lee `error.code` del envelope uniforme de la épica 09 (RG-3); `null` si no lo respeta. */
function readErrorCode(message: unknown): string | null {
  if (typeof message !== 'object' || message === null) return null;
  const error = (message as Record<string, unknown>).error;
  if (typeof error !== 'object' || error === null) return null;
  const code = (error as Record<string, unknown>).code;
  return typeof code === 'string' && code !== '' ? code : null;
}

/** Lee `type` de un mensaje del protocolo WS; `null` si no lo trae. */
function readMessageType(message: unknown): string | null {
  if (typeof message !== 'object' || message === null) return null;
  const type = (message as Record<string, unknown>).type;
  return typeof type === 'string' && type !== '' ? type : null;
}

export class PrivateChannel {
  private readonly url: string;
  private readonly getToken: () => string | null;
  private readonly onUnauthenticated: (tokenUsed: string | null) => void;
  private readonly channels: PrivateChannelName[];
  private readonly onMessage: ((message: unknown) => void) | undefined;
  private readonly onStatusChange: ((status: ConnectionStatus) => void) | undefined;
  private readonly webSocketImpl: WebSocketLike | undefined;
  private readonly setTimeoutImpl: typeof setTimeout;
  private readonly clearTimeoutImpl: typeof clearTimeout;
  private readonly random: () => number;

  private socket: WebSocketInstanceLike | null = null;
  private retryTimer: TimerHandle | null = null;
  private currentStatus: ConnectionStatus = 'idle';
  /** Cantidad de reintentos ya agendados desde la última conexión exitosa (RG-10). */
  private retryCount = 0;
  /** `start()` pedido y todavía no revertido por `stop()`. */
  private started = false;
  /** La app está en background/inactive: no se reintenta hasta volver a foreground (RG-5). */
  private suspended = false;
  /** El servidor rechazó el token: la sesión terminó, no se reintenta (RN-12). */
  private sessionEnded = false;
  /** Token del intento en curso, para reportarlo con el `UNAUTHENTICATED`. */
  private tokenUsed: string | null = null;
  /** Evita notificar dos veces el mismo `UNAUTHENTICATED` (p. ej. mensaje + cierre). */
  private unauthenticatedNotified = false;

  constructor(options: PrivateChannelOptions) {
    this.url = options.url;
    this.getToken = options.getToken;
    this.onUnauthenticated = options.onUnauthenticated;
    this.channels = options.channels ?? [];
    this.onMessage = options.onMessage;
    this.onStatusChange = options.onStatusChange;
    this.webSocketImpl = options.webSocketImpl;
    this.setTimeoutImpl = options.setTimeoutImpl ?? setTimeout;
    this.clearTimeoutImpl = options.clearTimeoutImpl ?? clearTimeout;
    this.random = options.random ?? Math.random;
  }

  get status(): ConnectionStatus {
    return this.currentStatus;
  }

  /** Conecta (o reconecta). Idempotente: llamarlo dos veces no abre dos sockets. */
  start(): void {
    // Un `start()` explícito es intención fresca del usuario (típicamente tras un login
    // nuevo): limpia el "sesión terminada" y el backoff acumulado.
    this.started = true;
    this.suspended = false;
    this.sessionEnded = false;
    if (this.socket !== null || this.retryTimer !== null) return;
    this.retryCount = 0;
    this.connect();
  }

  /** Cierra el socket y cancela reintentos pendientes. */
  stop(): void {
    this.started = false;
    this.suspended = false;
    this.cancelRetry();
    this.closeSocket();
    this.retryCount = 0;
    this.setStatus('idle');
  }

  /** Ciclo de vida (RG-5): background suspende, foreground reconecta y re-sincroniza. */
  handleAppStateChange(state: 'active' | 'inactive' | 'background'): void {
    if (state === 'background' || state === 'inactive') {
      if (this.suspended) return;
      this.suspended = true;
      // Suspender **no** es un fallo de autenticación: se cancelan timers y se cierra el
      // socket sin tocar `onUnauthenticated` (RG-5, AT-11-01-10).
      this.cancelRetry();
      this.closeSocket();
      if (this.started) this.setStatus('suspended');
      return;
    }
    if (!this.suspended) return;
    this.suspended = false;
    if (!this.started || this.sessionEnded) return;
    // Foreground: se reconecta **de inmediato** (delay 0) y el nuevo handshake + los nuevos
    // `subscribe` traen un snapshot fresco antes de los deltas (RG-5 + RG-API-7).
    this.cancelRetry();
    this.retryCount = 0;
    this.connect();
  }

  /**
   * Delay del próximo reintento (RG-10): `1000 · 2^n` topeado en 30000, más jitter uniforme
   * en ±500 ms, nunca negativo. Consume una muestra de `random`, igual que el agendado real.
   */
  nextDelayMs(): number {
    const base = Math.min(
      BACKOFF_INITIAL_MS * Math.pow(BACKOFF_FACTOR, this.retryCount),
      BACKOFF_MAX_MS,
    );
    const jitter = (this.random() * 2 - 1) * BACKOFF_JITTER_MS;
    return Math.max(0, base + jitter);
  }

  // --- internos -------------------------------------------------------------------------

  private connect(): void {
    const token = this.getToken();
    // Sin sesión no hay canal privado que abrir (HU-09-04 RN-1: exige token).
    if (token === null || token === '') {
      this.setStatus('idle');
      return;
    }
    const WebSocketImpl = this.webSocketImpl ?? (globalThis as { WebSocket?: WebSocketLike }).WebSocket;
    if (WebSocketImpl === undefined) {
      this.setStatus('idle');
      return;
    }

    this.tokenUsed = token;
    this.unauthenticatedNotified = false;
    this.setStatus('connecting');

    // La url no lleva el token en ningún parámetro (HU-09-04 RN-1).
    const socket = new WebSocketImpl(this.url);
    this.socket = socket;

    socket.onopen = (): void => {
      if (this.socket !== socket) return;
      // Primer mensaje del handshake, antes de cualquier `subscribe` (HU-09-04 RN-1).
      this.send(socket, { type: 'auth', token });
    };
    socket.onmessage = (event: WebSocketMessageEventLike): void => {
      if (this.socket !== socket) return;
      this.handleMessage(socket, event);
    };
    socket.onerror = (): void => {
      this.handleDisconnect(socket);
    };
    socket.onclose = (): void => {
      this.handleDisconnect(socket);
    };
  }

  private handleMessage(socket: WebSocketInstanceLike, event: WebSocketMessageEventLike): void {
    const parsed = this.parse(event.data);
    if (parsed === undefined) return;

    // `UNAUTHENTICATED` en cualquier momento (handshake o canal ya autenticado):
    // HU-11-01 RN-12 / AT-11-01-12.
    if (readErrorCode(parsed) === 'UNAUTHENTICATED') {
      this.handleUnauthenticated(socket);
      return;
    }

    const type = readMessageType(parsed);
    if (type === 'authenticated') {
      // Conexión exitosa: se resetea el backoff a 1 s (RG-10) y se suscriben los canales.
      this.retryCount = 0;
      this.setStatus('live');
      for (const channel of this.channels) {
        this.send(socket, { type: 'subscribe', channel });
      }
      return;
    }

    // El resto (snapshots, deltas, `subscribed`, errores no-401) va a la capa de datos.
    this.onMessage?.(parsed);
  }

  private handleUnauthenticated(socket: WebSocketInstanceLike): void {
    if (this.socket !== socket) return;
    if (this.unauthenticatedNotified) return;
    this.unauthenticatedNotified = true;
    const tokenUsed = this.tokenUsed;

    // La sesión terminó: se cierra el socket y **no** hay reintento (reintentar con un token
    // que el servidor ya rechazó sería un bucle). El logout singleton lo resuelve el
    // consumidor (RG-8).
    this.sessionEnded = true;
    this.cancelRetry();
    this.closeSocket();
    this.setStatus('idle');
    this.onUnauthenticated(tokenUsed);
  }

  /** Error o cierre inesperado del socket ⇒ reconexión con backoff (RG-10). */
  private handleDisconnect(socket: WebSocketInstanceLike): void {
    if (this.socket !== socket) return;
    this.detach(socket);
    this.socket = null;

    if (this.sessionEnded || !this.started || this.suspended) return;

    this.scheduleRetry();
  }

  private scheduleRetry(): void {
    if (this.retryTimer !== null) return;
    const delay = this.nextDelayMs();
    // Reintentos indefinidos con el delay topeado mientras haya foreground (RG-10).
    this.retryCount += 1;
    this.setStatus('reconnecting');
    this.retryTimer = this.setTimeoutImpl(() => {
      this.retryTimer = null;
      if (this.sessionEnded || !this.started || this.suspended) return;
      this.connect();
    }, delay);
  }

  private cancelRetry(): void {
    if (this.retryTimer === null) return;
    this.clearTimeoutImpl(this.retryTimer);
    this.retryTimer = null;
  }

  /** Cierra el socket vigente sin disparar la reconexión (se desenganchan los handlers). */
  private closeSocket(): void {
    const socket = this.socket;
    if (socket === null) return;
    this.socket = null;
    this.detach(socket);
    try {
      socket.close();
    } catch {
      // Un socket ya cerrado no es un error del cliente; nada que reportar.
    }
  }

  private detach(socket: WebSocketInstanceLike): void {
    socket.onopen = null;
    socket.onmessage = null;
    socket.onerror = null;
    socket.onclose = null;
  }

  private send(socket: WebSocketInstanceLike, payload: unknown): void {
    try {
      socket.send(JSON.stringify(payload));
    } catch {
      // Si el socket se cerró justo antes del envío, el `onclose` dispara la reconexión.
      // No se loggea el payload: puede contener el token (HU-11-01 RN-7).
    }
  }

  private parse(data: unknown): unknown {
    if (typeof data === 'string') {
      try {
        return JSON.parse(data);
      } catch {
        // Mensaje no-JSON: se descarta (el contrato es JSON de texto, HU-09-04).
        return undefined;
      }
    }
    if (typeof data === 'object' && data !== null) return data;
    return undefined;
  }

  private setStatus(status: ConnectionStatus): void {
    if (this.currentStatus === status) return;
    this.currentStatus = status;
    this.onStatusChange?.(status);
  }
}
