/**
 * Pantalla de login mobile (HU-11-01).
 *
 * Contrato idéntico al del cliente web (RN-1): `POST /api/v1/auth/login` de la épica 09.
 * Los mensajes y el manejo de errores mantienen paridad funcional con HU-10-01 (RG-6);
 * lo propio de mobile es la validación local antes de enviar (RN-8) y que el token se
 * persista en el almacén cifrado del SO (RN-2, en `SessionStore`).
 *
 * La `password` sólo vive en el estado del formulario mientras se tipea y viaja en el
 * request: no se persiste ni se loguea (RN-7).
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';
import { login } from '../api/auth';
import {
  ApiError,
  CONNECTION_ERROR_MESSAGE,
  INVALID_CREDENTIALS_MESSAGE,
  messageForError,
} from '../api/errors';
import { useSession } from '../session/SessionProvider';
import { colors, radius, spacing } from '../ui/theme';

/**
 * Validación de formato de email como **feedback temprano** (RN-8). No sustituye la
 * autorización del backend ni habilita ningún bypass local: sólo evita un viaje de red
 * cuando el dato es obviamente inválido.
 */
export function isEmailShaped(value: string): boolean {
  const trimmed = value.trim();
  if (trimmed === '' || /\s/.test(trimmed)) return false;
  return /^[^@]+@[^@.]+(\.[^@.]+)+$/.test(trimmed);
}

export interface LocalValidation {
  email: string | null;
  password: string | null;
}

/** Errores de validación local del formulario (RN-8 / AT-11-01-07). */
export function validateCredentials(email: string, password: string): LocalValidation {
  const emailError =
    email.trim() === ''
      ? 'Ingresá tu email'
      : isEmailShaped(email)
        ? null
        : 'El email no tiene un formato válido';
  const passwordError = password === '' ? 'Ingresá tu contraseña' : null;
  return { email: emailError, password: passwordError };
}

export function LoginScreen() {
  const session = useSession();
  const { api, signIn, notice, dismissNotice } = session;

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [localErrors, setLocalErrors] = useState<LocalValidation>({ email: null, password: null });
  const [fieldErrors, setFieldErrors] = useState<LocalValidation>({ email: null, password: null });
  const [formError, setFormError] = useState<string | null>(null);
  const [retryAfterSeconds, setRetryAfterSeconds] = useState<number | null>(null);
  // Evita un segundo request si el press llega antes de que React re-renderice con
  // `submitting = true` (anti doble submit, paridad con HU-10-01 RN-2).
  const inFlight = useRef(false);
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  // RATE_LIMITED (429): se informa la espera de `details.retryAfterSeconds` y se rehabilita
  // el botón al agotarse (paridad con HU-10-01 RN-6).
  useEffect(() => {
    if (retryAfterSeconds === null) return;
    if (retryAfterSeconds <= 0) {
      setRetryAfterSeconds(null);
      setFormError(null);
      return;
    }
    const timer = setTimeout(() => {
      setRetryAfterSeconds((current) => (current === null ? null : current - 1));
    }, 1000);
    return () => clearTimeout(timer);
  }, [retryAfterSeconds]);

  const rateLimited = retryAfterSeconds !== null && retryAfterSeconds > 0;
  const disabled = submitting || rateLimited;

  const clearErrors = useCallback(() => {
    setFormError(null);
    setFieldErrors({ email: null, password: null });
  }, []);

  const onSubmit = useCallback(async () => {
    if (inFlight.current || disabled) return;

    // RN-8 / AT-11-01-07: la validación local **bloquea el envío**; no se llama a la API
    // hasta corregir los campos.
    const validation = validateCredentials(email, password);
    setLocalErrors(validation);
    if (validation.email !== null || validation.password !== null) {
      setFormError(null);
      return;
    }

    inFlight.current = true;
    setSubmitting(true);
    clearErrors();
    if (notice !== null) dismissNotice();

    try {
      const response = await login(api, { email: email.trim(), password });
      // RN-2 / AT-11-01-01: el token se persiste en el almacén cifrado y recién ahí la app
      // pasa a la vista autenticada. La password no se guarda en ningún medio.
      await signIn(response.token);
      if (mounted.current) setPassword('');
    } catch (error) {
      if (!mounted.current) return;
      if (error instanceof ApiError) {
        if (error.code === 'INVALID_CREDENTIALS' || error.code === 'UNAUTHENTICATED') {
          // RN-3 / AT-11-01-04: mensaje genérico que no revela si el email existe. Sobre un
          // endpoint público, `UNAUTHENTICATED` sólo puede significar credencial rechazada:
          // avisar de "sesión expirada" a quien nunca tuvo sesión sería engañoso.
          setFormError(INVALID_CREDENTIALS_MESSAGE);
          setPassword('');
        } else if (error.code === 'VALIDATION_ERROR') {
          const issues = error.issues;
          const byField: LocalValidation = { email: null, password: null };
          for (const issue of issues) {
            const field = issue.field.toLowerCase();
            const text = issue.message.slice(0, 200);
            if (field.includes('email')) byField.email = text;
            else if (field.includes('password')) byField.password = text;
          }
          setFieldErrors(byField);
          setFormError(
            byField.email === null && byField.password === null ? messageForError(error) : null,
          );
        } else if (error.code === 'RATE_LIMITED') {
          const seconds = error.retryAfterSeconds;
          setFormError(
            seconds === null
              ? messageForError(error)
              : `Demasiados intentos. Esperá ${seconds} segundos antes de reintentar`,
          );
          if (seconds !== null && seconds > 0) setRetryAfterSeconds(seconds);
        } else {
          setFormError(messageForError(error));
        }
      } else {
        // RN-9 / AT-11-01-09: fallo de red, distinguible de `INVALID_CREDENTIALS`. No se
        // persiste token, se conserva el email y se puede reintentar.
        setFormError(CONNECTION_ERROR_MESSAGE);
      }
    } finally {
      inFlight.current = false;
      if (mounted.current) setSubmitting(false);
    }
  }, [api, clearErrors, disabled, dismissNotice, email, notice, password, signIn]);

  const buttonLabel = useMemo(() => {
    if (submitting) return 'Ingresando…';
    if (rateLimited) return `Esperá ${retryAfterSeconds}s`;
    return 'Ingresar';
  }, [rateLimited, retryAfterSeconds, submitting]);

  return (
    <KeyboardAvoidingView
      style={styles.flex}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
        <Text style={styles.title}>Exchange</Text>
        <Text style={styles.subtitle}>Ingresá para operar</Text>

        {notice !== null ? (
          <Text style={styles.notice} testID="login-notice">
            {notice}
          </Text>
        ) : null}

        <Text style={styles.label} nativeID="login-email-label">
          Email
        </Text>
        <TextInput
          testID="login-email"
          accessibilityLabel="Email"
          accessibilityLabelledBy="login-email-label"
          style={styles.input}
          value={email}
          onChangeText={(value) => {
            setEmail(value);
            setLocalErrors((current) => ({ ...current, email: null }));
            setFieldErrors((current) => ({ ...current, email: null }));
          }}
          autoCapitalize="none"
          autoCorrect={false}
          autoComplete="email"
          keyboardType="email-address"
          inputMode="email"
          placeholder="tu@email.com"
          placeholderTextColor={colors.textMuted}
          editable={!disabled}
        />
        {localErrors.email !== null ? (
          <Text style={styles.fieldError} testID="login-email-error">
            {localErrors.email}
          </Text>
        ) : null}
        {fieldErrors.email !== null ? (
          <Text style={styles.fieldError} testID="login-email-issue">
            {fieldErrors.email}
          </Text>
        ) : null}

        <Text style={styles.label} nativeID="login-password-label">
          Contraseña
        </Text>
        <TextInput
          testID="login-password"
          accessibilityLabel="Contraseña"
          accessibilityLabelledBy="login-password-label"
          style={styles.input}
          value={password}
          onChangeText={(value) => {
            setPassword(value);
            setLocalErrors((current) => ({ ...current, password: null }));
            setFieldErrors((current) => ({ ...current, password: null }));
          }}
          // La password nunca se muestra en claro ni se copia al portapapeles (RN-7).
          secureTextEntry
          autoCapitalize="none"
          autoCorrect={false}
          autoComplete="current-password"
          placeholder="••••••••"
          placeholderTextColor={colors.textMuted}
          editable={!disabled}
          onSubmitEditing={() => {
            void onSubmit();
          }}
        />
        {localErrors.password !== null ? (
          <Text style={styles.fieldError} testID="login-password-error">
            {localErrors.password}
          </Text>
        ) : null}
        {fieldErrors.password !== null ? (
          <Text style={styles.fieldError} testID="login-password-issue">
            {fieldErrors.password}
          </Text>
        ) : null}

        {formError !== null ? (
          <Text style={styles.formError} testID="login-error">
            {formError}
          </Text>
        ) : null}

        <Pressable
          testID="login-submit"
          accessibilityRole="button"
          accessibilityState={{ disabled, busy: submitting }}
          style={({ pressed }) => [
            styles.button,
            disabled && styles.buttonDisabled,
            pressed && !disabled && styles.buttonPressed,
          ]}
          disabled={disabled}
          onPress={() => {
            void onSubmit();
          }}
        >
          {submitting ? <ActivityIndicator color={colors.accentText} testID="login-spinner" /> : null}
          <Text style={styles.buttonText}>{buttonLabel}</Text>
        </Pressable>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1, backgroundColor: colors.background },
  container: { padding: spacing.lg, paddingTop: spacing.xl * 2, gap: spacing.sm },
  title: { color: colors.text, fontSize: 30, fontWeight: '700' },
  subtitle: { color: colors.textMuted, fontSize: 15, marginBottom: spacing.lg },
