/**
 * Construcción del URI **EIP-681** que se codifica en el QR de la pantalla de depósito.
 *
 * Fuente de verdad: `spec/11-cliente-mobile/HU-11-06-depositos-y-retiros-mobile.md` RN-2 y
 * Escenario 26 (AT-11-06-26). Textualmente (RN-2):
 *
 *   «**Formato del QR (EIP-681):** para que las wallets externas no envíen el activo o la red
 *   equivocados, el QR se genera como URI EIP-681: para **ETH nativo**
 *   `ethereum:<depositAddress>@11155111`; para **USDC-mock**
 *   `ethereum:<USDC_CONTRACT_ADDRESS>@11155111/transfer?address=<depositAddress>` (donde
 *   `<USDC_CONTRACT_ADDRESS>` es el campo **`tokenAddress`** devuelto por
 *   `GET /deposit-address?asset=USDC`, épica 09 HU-09-01 RN-10 / HU-06-04 RN-6; es
 *   configuración por entorno, no un literal de la spec). Siempre se muestra **además** el
 *   address en texto con checksum EIP-55 como respaldo para wallets que no soporten
 *   EIP-681.»
 *
 * Notar la asimetría del caso ERC-20: el destinatario del URI es el **contrato** del token y
 * la dirección de depósito viaja como parámetro `address` de la llamada `transfer` — una
 * **única** dirección Ethereum recibe tanto ETH como USDC-mock (RN-2), la diferencia la hace
 * el tipo de transacción on-chain.
 *
 * Módulo TypeScript puro: sin React Native ni APIs de Node.
 */

import { isAddressLike, toChecksumAddress } from './address';

/**
 * `chainId` de **Sepolia**, la única red del proyecto (constante fundacional:
 * `spec/00-fundaciones/activos-y-par-de-trading.md`; RN-2 y RN-7 de HU-11-06). Se declara
 * como string porque su único uso acá es concatenarse en el URI, y así no queda expuesto a
 * la precisión de `number` al serializar.
 */
export const SEPOLIA_CHAIN_ID = '11155111';

/** Activos del proyecto que admiten depósito on-chain (par ETH/USDC-mock, fundaciones). */
export type DepositAsset = 'ETH' | 'USDC';

/**
 * Falta el `tokenAddress` (dirección del contrato USDC-mock) para armar el URI de un
 * depósito de USDC.
 *
 * **Decisión:** se lanza un error explícito en vez de devolver un URI incompleto o inventar
 * una dirección por defecto. El `tokenAddress` es **configuración por entorno** que llega en
 * la respuesta de `GET /api/v1/deposit-address?asset=USDC` (RN-2): hardcodear un default
 * dirigiría fondos reales a un contrato equivocado, y un URI a medias haría que la wallet
 * externa enviara el activo incorrecto — exactamente lo que RN-2 busca evitar.
 *
 * La pantalla captura este error y **degrada** mostrando sólo el address en texto con
 * checksum EIP-55, que RN-2 exige mostrar siempre como respaldo.
 */
export class MissingTokenAddressError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'MissingTokenAddressError';
  }
}

export interface DepositUriParams {
  asset: DepositAsset;
  /** Dirección de depósito de la cuenta, obtenida de la API (RN-1: el cliente no la deriva). */
  depositAddress: string;
  /** Dirección del contrato USDC-mock (`tokenAddress` de la API). Requerida para `USDC`. */
  tokenAddress?: string;
}

/**
 * Normaliza una dirección para incrustarla en el URI: exige la forma `0x` + 40 hex y la
 * emite con checksum EIP-55 (RN-2 pide el address con checksum).
 *
 * Deliberadamente NO se exige que la entrada **ya** venga con un checksum válido: la caja de
 * los dígitos no cambia los 20 bytes de la dirección, así que recalcularlo es seguro y evita
 * quedarse sin QR si la API devuelve la dirección en minúsculas. Lo que sí es error es un
 * largo/prefijo/carácter inválido: ahí no hay dirección que codificar.
 */
function normalizeForUri(value: string, label: string): string {
  if (!isAddressLike(value)) {
    throw new Error(`${label} inválida: se esperaba \`0x\` + 40 dígitos hexadecimales`);
  }
  return toChecksumAddress(value);
}

/**
 * Devuelve el URI EIP-681 a codificar en el QR de depósito (RN-2, AT-11-06-26):
 *  - `ETH`  => `ethereum:<depositAddress>@11155111`
 *  - `USDC` => `ethereum:<tokenAddress>@11155111/transfer?address=<depositAddress>`
 *
 * Lanza `MissingTokenAddressError` si `asset = 'USDC'` y no hay `tokenAddress` utilizable, y
 * `Error` si alguna dirección no tiene la forma `0x` + 40 hex.
 */
export function buildDepositUri(params: DepositUriParams): string {
  const { asset, depositAddress, tokenAddress } = params;
  const deposit = normalizeForUri(depositAddress, 'dirección de depósito');

  if (asset === 'ETH') {
    return `ethereum:${deposit}@${SEPOLIA_CHAIN_ID}`;
  }

  if (asset === 'USDC') {
    if (typeof tokenAddress !== 'string' || tokenAddress.length === 0) {
      throw new MissingTokenAddressError(
        'falta `tokenAddress` (contrato USDC-mock) para armar el URI EIP-681 del depósito de ' +
          'USDC; la pantalla debe mostrar sólo el address en texto (RN-2)'
      );
    }
    const token = normalizeForUri(tokenAddress, 'dirección del contrato USDC-mock');
    return `ethereum:${token}@${SEPOLIA_CHAIN_ID}/transfer?address=${deposit}`;
  }

  // `asset` está tipado como `DepositAsset`; este guard cubre datos que entran sin tipar
  // (p. ej. una respuesta de la API con un activo desconocido).
  throw new Error(`activo de depósito no soportado: ${String(asset)}`);
}
