/**
 * Canal WebSocket privado del mobile: handshake, `UNAUTHENTICATED`, backoff y ciclo de vida.
 *
 * Condiciones de prueba de la épica 11, RG-11: se usa un **WebSocket falso** con
 * `simulateOpen()` / `simulateMessage()` / `simulateDisconnect()` y timers inyectados, así que
 * ningún test depende del tiempo real ni de un socket real. El jitter se alimenta de un
 * `random` determinista.
 */
import {
  BACKOFF_MAX_MS,
  PrivateChannel,
  type ConnectionStatus,
  type WebSocketInstanceLike,
  type WebSocketLike,
  type WebSocketMessageEventLike,
} from '../src/ws/privateChannel';

const WS_URL = 'ws://localhost:3000/api/v1/ws';
const TOKEN = 'token-de-sesion-1';

/** Doble del WebSocket (RG-11): registra lo enviado y permite simular el servidor. */
class FakeWebSocket implements WebSocketInstanceLike {
  static instances: FakeWebSocket[] = [];

  readonly url: string;
  readonly sent: string[] = [];
  closeCalls = 0;

  onopen: ((event?: unknown) => void) | null = null;
  onmessage: ((event: WebSocketMessageEventLike) => void) | null = null;
  onerror: ((event?: unknown) => void) | null = null;
  onclose: ((event?: unknown) => void) | null = null;

  constructor(url: string) {
    this.url = url;
    FakeWebSocket.instances.push(this);
  }

  send(data: string): void {
    this.sent.push(data);
  }

  close(): void {
    this.closeCalls += 1;
  }

  /** Mensajes enviados por el cliente, ya parseados. */
  get sentMessages(): unknown[] {
    return this.sent.map((raw) => JSON.parse(raw) as unknown);
  }

  simulateOpen(): void {
    this.onopen?.();
  }

  simulateMessage(message: unknown): void {
    this.onmessage?.({ data: JSON.stringify(message) });
  }

  simulateDisconnect(): void {
    this.onclose?.();
  }

  simulateError(): void {
    this.onerror?.();
  }
}

/** Reloj falso: registra los delays agendados y los ejecuta a pedido (RG-11). */
class FakeTimers {
  private seq = 0;
  private readonly pending = new Map<number, () => void>();
  readonly delays: number[] = [];

  readonly setTimeoutImpl = ((handler: () => void, delay?: number): number => {
    this.seq += 1;
    this.pending.set(this.seq, handler);
    this.delays.push(delay ?? 0);
    return this.seq;
  }) as unknown as typeof setTimeout;

  readonly clearTimeoutImpl = ((handle?: unknown): void => {
    this.pending.delete(handle as number);
  }) as unknown as typeof clearTimeout;

  get pendingCount(): number {
    return this.pending.size;
  }

  /** Ejecuta los callbacks pendientes (equivale a "pasó el delay"). */
  runPending(): void {
    for (const [id, handler] of [...this.pending]) {
      this.pending.delete(id);
      handler();
    }
  }
}

interface Harness {
  channel: PrivateChannel;
  timers: FakeTimers;
  sockets: FakeWebSocket[];
  statuses: ConnectionStatus[];
  unauthenticated: Array<string | null>;
  messages: unknown[];
}

function makeChannel(
  overrides: {
    token?: string | null;
    channels?: Array<'orders' | 'balances' | 'withdrawals'>;
    random?: () => number;
  } = {},
): Harness {
  FakeWebSocket.instances = [];
  const timers = new FakeTimers();
  const statuses: ConnectionStatus[] = [];
  const unauthenticated: Array<string | null> = [];
  const messages: unknown[] = [];
  const token = overrides.token === undefined ? TOKEN : overrides.token;

  const channel = new PrivateChannel({
    url: WS_URL,
    getToken: () => token,
    onUnauthenticated: (tokenUsed) => unauthenticated.push(tokenUsed),
    channels: overrides.channels ?? ['orders', 'balances'],
    onMessage: (message) => messages.push(message),
    onStatusChange: (status) => statuses.push(status),
    webSocketImpl: FakeWebSocket as unknown as WebSocketLike,
    setTimeoutImpl: timers.setTimeoutImpl,
    clearTimeoutImpl: timers.clearTimeoutImpl,
    // Jitter determinista: `0.5` ⇒ ±0 ms, así el delay observado es el base de RG-10.
    random: overrides.random ?? ((): number => 0.5),
  });

  return { channel, timers, sockets: FakeWebSocket.instances, statuses, unauthenticated, messages };
}

/** Deja el canal autenticado y devuelve el socket vigente. */
function connectAndAuthenticate(h: Harness): FakeWebSocket {
  h.channel.start();
  const socket = h.sockets[h.sockets.length - 1]!;
  socket.simulateOpen();
  socket.simulateMessage({ type: 'authenticated' });
  return socket;
}

describe('PrivateChannel — handshake (HU-09-04 RN-1 / HU-11-01 RN-12)', () => {
  it('envía como primer mensaje {"type":"auth","token":"..."} y no pone el token en la URL', () => {
    const h = makeChannel();
    h.channel.start();

    const socket = h.sockets[0]!;
    expect(h.sockets).toHaveLength(1);
    expect(socket.url).toBe(WS_URL);
    // RN-1 prohíbe el token en la URL/query (no exponerlo en logs).
    expect(socket.url).not.toContain(TOKEN);
    expect(socket.sent).toHaveLength(0);

    socket.simulateOpen();
    // El **primer** mensaje es el `auth` (antes de cualquier `subscribe`).
    expect(socket.sentMessages[0]).toEqual({ type: 'auth', token: TOKEN });
    expect(h.channel.status).toBe('connecting');
  });

  it('sin token persistido no abre socket (HU-09-04 RN-1: el canal privado exige token)', () => {
    const h = makeChannel({ token: null });
    h.channel.start();

    expect(h.sockets).toHaveLength(0);
    expect(h.channel.status).toBe('idle');
  });

  it('`authenticated` ⇒ estado live y `subscribe` de los canales configurados (HU-09-04 RN-2)', () => {
    const h = makeChannel({ channels: ['orders', 'balances', 'withdrawals'] });
    const socket = connectAndAuthenticate(h);

    expect(h.channel.status).toBe('live');
    expect(socket.sentMessages).toEqual([
      { type: 'auth', token: TOKEN },
      { type: 'subscribe', channel: 'orders' },
      { type: 'subscribe', channel: 'balances' },
      { type: 'subscribe', channel: 'withdrawals' },
    ]);
    // `idle → connecting → live` (RG-10: indicador de estado de conexión).
    expect(h.statuses).toEqual(['connecting', 'live']);
  });

  it('start() dos veces no abre dos sockets (idempotencia)', () => {
    const h = makeChannel();
    h.channel.start();
    h.channel.start();
    h.sockets[0]!.simulateOpen();
    h.channel.start();

    expect(h.sockets).toHaveLength(1);
    expect(h.sockets[0]!.sentMessages).toEqual([{ type: 'auth', token: TOKEN }]);
  });

  it('reenvía al consumidor los mensajes de datos del canal (snapshot/deltas)', () => {
    const h = makeChannel({ channels: ['balances'] });
    const socket = connectAndAuthenticate(h);
    socket.simulateMessage({ type: 'subscribed', channel: 'balances' });
    socket.simulateMessage({ type: 'balance', asset: 'ETH', available: '1', locked: '0', total: '1' });

    expect(h.messages).toEqual([
      { type: 'subscribed', channel: 'balances' },
      { type: 'balance', asset: 'ETH', available: '1', locked: '0', total: '1' },
    ]);
  });
});

describe('PrivateChannel — UNAUTHENTICATED [AT-11-01-12] (HU-11-01 RN-12, RG-8)', () => {
  it('en el handshake: notifica una sola vez con el token usado, cierra y NO reintenta', () => {
    const h = makeChannel();
    h.channel.start();
    const socket = h.sockets[0]!;
    socket.simulateOpen();

    socket.simulateMessage({ error: { code: 'UNAUTHENTICATED' } });

    expect(h.unauthenticated).toEqual([TOKEN]);
    expect(socket.closeCalls).toBe(1);
    // No hay reintento agendado: el servidor ya rechazó ese token (evita el bucle).
    expect(h.timers.pendingCount).toBe(0);
    expect(h.timers.delays).toEqual([]);

    // Ni siquiera un cierre posterior del socket dispara reconexión ni un segundo aviso.
    socket.simulateDisconnect();
    h.timers.runPending();
    expect(h.sockets).toHaveLength(1);
    expect(h.unauthenticated).toEqual([TOKEN]);
    expect(h.channel.status).toBe('idle');
  });

  it('en un mensaje del canal ya autenticado: mismo flujo, una sola vez (RN-13 de HU-09-04)', () => {
    const h = makeChannel();
    const socket = connectAndAuthenticate(h);
    expect(h.channel.status).toBe('live');

    socket.simulateMessage({ error: { code: 'UNAUTHENTICATED' } });
    // El servidor cierra el socket tras el error (HU-09-04 RN-13): no debe re-notificar.
    socket.simulateDisconnect();

    expect(h.unauthenticated).toEqual([TOKEN]);
    expect(socket.closeCalls).toBe(1);
    expect(h.timers.pendingCount).toBe(0);
    expect(h.sockets).toHaveLength(1);
  });

  it('un error que NO es UNAUTHENTICATED no termina la sesión (RG-3)', () => {
    const h = makeChannel();
    const socket = connectAndAuthenticate(h);

    socket.simulateMessage({ error: { code: 'VALIDATION_ERROR' } });

    expect(h.unauthenticated).toEqual([]);
    expect(h.messages).toEqual([{ error: { code: 'VALIDATION_ERROR' } }]);
    expect(h.channel.status).toBe('live');
  });
});

describe('PrivateChannel — backoff de reconexión (RG-10)', () => {
  it('la secuencia de delays es 1000, 2000, 4000 … topeada en 30000', () => {
    const h = makeChannel();
    h.channel.start();

    // Seis desconexiones sucesivas: 1s, 2s, 4s, 8s, 16s y el tope de 30s (32s capado).
    for (let i = 0; i < 6; i += 1) {
      const socket = h.sockets[h.sockets.length - 1]!;
      socket.simulateOpen();
      socket.simulateDisconnect();
      expect(h.channel.status).toBe('reconnecting');
      h.timers.runPending();
    }

    expect(h.timers.delays).toEqual([1000, 2000, 4000, 8000, 16000, BACKOFF_MAX_MS]);
    // Reintentos indefinidos: cada retry abrió un socket nuevo con su handshake.
    expect(h.sockets).toHaveLength(7);
    expect(h.sockets[6]!.sent).toHaveLength(0);
    h.sockets[6]!.simulateOpen();
    expect(h.sockets[6]!.sentMessages[0]).toEqual({ type: 'auth', token: TOKEN });
  });

  it('aplica el jitter ±500 ms sobre el delay base y nunca devuelve un delay negativo', () => {
    const arriba = makeChannel({ random: () => 1 }); // +500 ms
    arriba.channel.start();
    arriba.sockets[0]!.simulateOpen();
    arriba.sockets[0]!.simulateDisconnect();
    expect(arriba.timers.delays).toEqual([1500]);

    const abajo = makeChannel({ random: () => 0 }); // -500 ms
    abajo.channel.start();
    abajo.sockets[0]!.simulateOpen();
    abajo.sockets[0]!.simulateDisconnect();
    expect(abajo.timers.delays).toEqual([500]);
