    socket.simulateDisconnect();
    expect(h.timers.pendingCount).toBe(1);
    h.timers.runPending();
    const reintento = h.sockets[1]!;
    reintento.simulateOpen();
    reintento.simulateDisconnect();
    expect(h.timers.pendingCount).toBe(1);

    h.channel.handleAppStateChange('background');

    expect(h.channel.status).toBe('suspended');
    expect(h.timers.pendingCount).toBe(0);
