    const h = makeChannel();
    const socket = connectAndAuthenticate(h);

    h.channel.handleAppStateChange('background');

    expect(socket.closeCalls).toBe(1);
    expect(h.channel.status).toBe('suspended');
    expect(h.sockets).toHaveLength(1);
