    expect(h.timers.pendingCount).toBe(0);
  });

  it('foreground reconecta de inmediato y re-autentica + re-suscribe (resync, RG-API-7)', () => {
    const h = makeChannel({ channels: ['orders'] });
    connectAndAuthenticate(h);
    h.channel.handleAppStateChange('background');

    h.channel.handleAppStateChange('active');

    // Reconexión inmediata: sin delay agendado (delay 0).
    expect(h.timers.delays).toEqual([]);
    expect(h.sockets).toHaveLength(2);
    const nuevo = h.sockets[1]!;
    nuevo.simulateOpen();
    expect(nuevo.sentMessages[0]).toEqual({ type: 'auth', token: TOKEN });
    nuevo.simulateMessage({ type: 'authenticated' });
    // Nuevo `subscribe` ⇒ snapshot fresco antes de los deltas.
    expect(nuevo.sentMessages[1]).toEqual({ type: 'subscribe', channel: 'orders' });
    expect(h.channel.status).toBe('live');
    expect(h.statuses).toEqual(['connecting', 'live', 'suspended', 'connecting', 'live']);
  });

  it('`inactive` suspende igual que `background` (AppState de React Native)', () => {
    const h = makeChannel();
    connectAndAuthenticate(h);

    h.channel.handleAppStateChange('inactive');

    expect(h.channel.status).toBe('suspended');
    expect(h.sockets[0]!.closeCalls).toBe(1);
  });

  it('tras UNAUTHENTICATED, volver a foreground no reconecta (la sesión terminó, RN-12)', () => {
    const h = makeChannel();
    const socket = connectAndAuthenticate(h);
    socket.simulateMessage({ error: { code: 'UNAUTHENTICATED' } });

    h.channel.handleAppStateChange('background');
    h.channel.handleAppStateChange('active');

    expect(h.sockets).toHaveLength(1);
    expect(h.unauthenticated).toEqual([TOKEN]);
  });

  it('stop() cierra el socket y cancela el reintento pendiente', () => {
    const h = makeChannel();
    h.channel.start();
    h.sockets[0]!.simulateOpen();
    h.sockets[0]!.simulateDisconnect();
    expect(h.timers.pendingCount).toBe(1);

    h.channel.stop();

    expect(h.timers.pendingCount).toBe(0);
    expect(h.channel.status).toBe('idle');
    h.timers.runPending();
    expect(h.sockets).toHaveLength(1);
  });
});

describe('PrivateChannel — seguridad (HU-11-01 RN-7 / AT-11-01-11)', () => {
  it('ni el token ni el handshake se loggean por consola', () => {
    const spies = [
      jest.spyOn(console, 'log').mockImplementation(() => undefined),
      jest.spyOn(console, 'warn').mockImplementation(() => undefined),
      jest.spyOn(console, 'error').mockImplementation(() => undefined),
    ];
    try {
      const h = makeChannel();
      const socket = connectAndAuthenticate(h);
      socket.simulateMessage({ type: 'balance', asset: 'ETH' });
      socket.simulateDisconnect();
      h.timers.runPending();
      h.sockets[1]!.simulateOpen();
      h.sockets[1]!.simulateMessage({ error: { code: 'UNAUTHENTICATED' } });

      for (const spy of spies) {
        for (const call of spy.mock.calls) {
          expect(JSON.stringify(call) ?? '').not.toContain(TOKEN);
        }
      }
      expect(h.unauthenticated).toEqual([TOKEN]);
    } finally {
      for (const spy of spies) spy.mockRestore();
    }
  });
});
