/**
 * Pantalla de depósito mobile (HU-11-06, Escenarios 1 y 26 — AT-11-06-01 / AT-11-06-26).
 *
 * Muestra la dirección de depósito de la cuenta con su **QR** y la acción de **copiar**,
 * aclarando la red (**Sepolia**, `chainId = 11155111`) y el activo.
 *
 * Alcance de esta corrida: **sólo** la presentación de la dirección. El seguimiento de
 * depósitos (RN-3) y los retiros quedan fuera porque su backend (épicas 07 y 08) no está
 * implementado.
 *
 * Reglas aplicadas:
 *  - RN-1: la dirección **viene de la API** (`GET /api/v1/deposit-address?asset=`); el
 *    cliente no la deriva ni accede a la seed.
 *  - RN-2: address en texto con checksum EIP-55 **siempre**, QR en formato EIP-681, y una
 *    **única** dirección recibe ETH y USDC-mock.
 *  - RN-11: ante `UNAUTHENTICATED` se limpia la sesión y se vuelve al login (lo hace el
 *    `ApiClient` vía `SessionStore`, flujo singleton RG-8).
 *  - RN-12: nunca se muestra ni se pide mnemonic, seed ni claves privadas.
 */
import { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import * as Clipboard from 'expo-clipboard';
import QRCode from 'react-native-qrcode-svg';
import { getProfile, type Profile } from '../api/auth';
import { getDepositAddress, type DepositAddress } from '../api/deposits';
import { ApiError, messageForError } from '../api/errors';
import { isValidChecksumAddress } from '../chain/address';
import { buildDepositUri, MissingTokenAddressError, type DepositAsset } from '../chain/eip681';
import { CHAIN_ID, NETWORK_LABEL } from '../config';
import { useSession } from '../session/SessionProvider';
import { colors, radius, spacing } from '../ui/theme';

const ASSETS: readonly DepositAsset[] = ['ETH', 'USDC'];

const ASSET_LABEL: Record<DepositAsset, string> = {
  ETH: 'ETH (nativo)',
  USDC: 'USDC-mock (ERC-20)',
};

export function DepositScreen() {
  const { api, signOut } = useSession();
  const [asset, setAsset] = useState<DepositAsset>('ETH');
  const [data, setData] = useState<DepositAddress | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const load = useCallback(
    async (target: DepositAsset) => {
      setError(null);
      try {
        const response = await getDepositAddress(api, target);
        setData(response);
      } catch (err) {
        setData(null);
        // Un `UNAUTHENTICATED` ya disparó el cierre de sesión en el `ApiClient`; acá sólo
        // se evita dejar la pantalla en un estado ambiguo.
        setError(messageForError(err));
        if (err instanceof ApiError && err.code === 'UNAUTHENTICATED') setError(null);
      }
    },
    [api],
  );

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void load(asset).finally(() => {
      if (!cancelled) setLoading(false);
    });
    return () => {
      cancelled = true;
    };
  }, [asset, load]);

  // El email de la cuenta identifica la sesión abierta. Es la primera petición autenticada
  // del arranque en frío junto con la dirección: si el token restaurado estaba expirado,
  // acá se detecta de forma reactiva (RN-10 de HU-11-01).
  useEffect(() => {
    let cancelled = false;
    getProfile(api).then(
      (loaded) => {
        if (!cancelled) setProfile(loaded);
      },
      () => {
        /* el perfil es informativo: su fallo no bloquea la pantalla de depósito */
      },
    );
    return () => {
      cancelled = true;
    };
  }, [api]);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    void load(asset).finally(() => setRefreshing(false));
  }, [asset, load]);

  const onCopy = useCallback(async () => {
    if (data === null) return;
    await Clipboard.setStringAsync(data.address);
    setCopied(true);
  }, [data]);

  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 2500);
    return () => clearTimeout(timer);
  }, [copied]);

  // RN-2: el QR es un URI EIP-681. Si faltara el `tokenAddress` de USDC no se inventa uno:
  // se degrada a mostrar sólo el address en texto, que es el respaldo que RN-2 exige.
  let qrValue: string | null = null;
  let qrUnavailable: string | null = null;
  if (data !== null) {
    try {
      qrValue = buildDepositUri({
        asset,
        depositAddress: data.address,
        ...(data.tokenAddress !== undefined ? { tokenAddress: data.tokenAddress } : {}),
      });
    } catch (err) {
      qrValue = null;
      qrUnavailable =
        err instanceof MissingTokenAddressError
          ? 'No se pudo generar el QR: la API no devolvió la dirección del contrato USDC-mock. Usá la dirección en texto.'
          : 'No se pudo generar el QR para esta dirección. Usá la dirección en texto.';
    }
  }

  return (
    <ScrollView
      style={styles.flex}
      contentContainerStyle={styles.container}
      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={colors.textMuted} />}
    >
      <View style={styles.header}>
        <View style={styles.headerText}>
          <Text style={styles.title}>Depositar</Text>
          {profile !== null ? (
            <Text style={styles.subtitle} testID="session-email">
              {profile.email}
            </Text>
          ) : null}
        </View>
        <Pressable
          testID="logout"
          accessibilityRole="button"
          onPress={() => {
            void signOut();
          }}
          style={styles.logout}
        >
          <Text style={styles.logoutText}>Cerrar sesión</Text>
        </Pressable>
      </View>

      <View style={styles.assetRow}>
        {ASSETS.map((candidate) => {
          const active = candidate === asset;
          return (
            <Pressable
              key={candidate}
              testID={`deposit-asset-${candidate}`}
              accessibilityRole="button"
              accessibilityState={{ selected: active }}
              style={[styles.assetButton, active && styles.assetButtonActive]}
              onPress={() => setAsset(candidate)}
            >
              <Text style={[styles.assetText, active && styles.assetTextActive]}>{candidate}</Text>
            </Pressable>
          );
        })}
      </View>

      <View style={styles.networkBanner}>
        <Text style={styles.networkText} testID="deposit-network">
          Red: {NETWORK_LABEL} (chainId {CHAIN_ID})
        </Text>
        <Text style={styles.networkSub} testID="deposit-asset-label">
          Activo: {ASSET_LABEL[asset]}
        </Text>
      </View>

      {loading ? (
        <View style={styles.center}>
          <ActivityIndicator color={colors.accent} testID="deposit-loading" />
        </View>
      ) : null}

      {!loading && error !== null ? (
        <View style={styles.card}>
          <Text style={styles.error} testID="deposit-error">
            {error}
          </Text>
          <Pressable
            testID="deposit-retry"
            accessibilityRole="button"
            style={styles.secondaryButton}
            onPress={() => {
              setLoading(true);
              void load(asset).finally(() => setLoading(false));
            }}
          >
            <Text style={styles.secondaryButtonText}>Reintentar</Text>
          </Pressable>
        </View>
      ) : null}

      {!loading && data !== null ? (
        <View style={styles.card}>
          {qrValue !== null ? (
            <View style={styles.qrFrame} testID="deposit-qr-frame">
              <QRCode value={qrValue} size={200} backgroundColor="#ffffff" color="#000000" />
            </View>
          ) : (
            <Text style={styles.warning} testID="deposit-qr-unavailable">
              {qrUnavailable}
            </Text>
          )}

          <Text style={styles.cardLabel}>Tu dirección de depósito</Text>
          <Text style={styles.address} testID="deposit-address" selectable>
            {data.address}
          </Text>
          {!isValidChecksumAddress(data.address) ? (
            <Text style={styles.warning} testID="deposit-address-checksum-warning">
              La dirección devuelta por la API no verifica el checksum EIP-55.
            </Text>
          ) : null}

          <Pressable
            testID="deposit-copy"
            accessibilityRole="button"
            style={styles.primaryButton}
            onPress={() => {
              void onCopy();
            }}
          >
            <Text style={styles.primaryButtonText}>
              {copied ? 'Dirección copiada' : 'Copiar dirección'}
            </Text>
          </Pressable>

          <Text style={styles.note} testID="deposit-note">
            Una única dirección recibe ETH y USDC-mock en {NETWORK_LABEL}: lo que distingue al
            activo es el tipo de transacción on-chain, no la dirección. Enviá fondos sólo por
            la red {NETWORK_LABEL} (chainId {CHAIN_ID}).
          </Text>
        </View>
      ) : null}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1, backgroundColor: colors.background },
  container: { padding: spacing.lg, gap: spacing.md, paddingBottom: spacing.xl },
  header: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },
  headerText: { flex: 1 },
  title: { color: colors.text, fontSize: 26, fontWeight: '700' },
  subtitle: { color: colors.textMuted, fontSize: 13 },
  logout: {
    borderColor: colors.border,
    borderWidth: 1,
    borderRadius: radius.sm,
    paddingHorizontal: spacing.sm,
    paddingVertical: spacing.xs + 2,
  },
  logoutText: { color: colors.textMuted, fontSize: 13 },
  assetRow: { flexDirection: 'row', gap: spacing.sm },
  assetButton: {
    flex: 1,
    alignItems: 'center',
    paddingVertical: spacing.sm + 2,
    borderRadius: radius.md,
    borderWidth: 1,
    borderColor: colors.border,
