/**
 * Criterios de aceptación de **HU-11-01 — Inicio de sesión en mobile y persistencia segura
 * del token** (`spec/11-cliente-mobile/HU-11-01-login-mobile.md`).
 *
 * Cada bloque cita el AT que verifica. El escenario 11 (AT-11-01-12, reconexión del
 * WebSocket privado con token expirado) se verifica en `tests/ws-private-channel.test.ts`
 * con un WebSocket falso, como fija RG-11 del README de la épica.
 */
import { act, fireEvent, render, screen, waitFor } from '@testing-library/react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { App } from '../src/App';
import { TOKEN_KEY } from '../src/session/secureStorage';
import { SessionStore } from '../src/session/sessionStore';
import {
  CONNECTION_ERROR_MESSAGE,
  INVALID_CREDENTIALS_MESSAGE,
  SESSION_EXPIRED_MESSAGE,
} from '../src/api/errors';
import {
  CUENTA,
  DEPOSITO,
  createFetchMock,
  errorResponse,
  installConsoleSpies,
  installSecureStoreFake,
  jsonResponse,
  type FetchMock,
  type SecureStoreFake,
} from './support';

const BASE_URL = 'http://backend.test/api/v1';

let fetchMock: FetchMock;
let secure: SecureStoreFake;

/** Handlers de las rutas que consume la vista autenticada, para que no falle por red. */
function stubAuthenticatedRoutes(): void {
  fetchMock.on('/me', () =>
    jsonResponse(200, {
      accountId: CUENTA.accountId,
      email: CUENTA.email,
      status: 'ACTIVE',
      createdAt: '2026-01-01T00:00:00.000Z',
    }),
  );
  fetchMock.on('/deposit-address', () =>
    jsonResponse(200, {
      asset: 'ETH',
      address: DEPOSITO.address,
      network: 'sepolia',
      chainId: '11155111',
    }),
  );
}

function stubLoginOk(): void {
  fetchMock.on('/auth/login', () =>
    jsonResponse(200, { token: CUENTA.token, tokenType: 'Bearer', expiresAt: CUENTA.expiresAt }),
  );
}

function renderApp(options: { onNavigate?: (route: string) => void } = {}) {
  return render(
    <App
      baseUrl={BASE_URL}
      fetchImpl={fetchMock.fetchImpl}
      wsUrl=""
      {...(options.onNavigate !== undefined ? { onNavigate: options.onNavigate } : {})}
    />,
  );
}

async function completarLogin(): Promise<void> {
  fireEvent.changeText(await screen.findByTestId('login-email'), CUENTA.email);
  fireEvent.changeText(screen.getByTestId('login-password'), CUENTA.password);
  fireEvent.press(screen.getByTestId('login-submit'));
}

beforeEach(() => {
  fetchMock = createFetchMock();
  secure = installSecureStoreFake();
  stubAuthenticatedRoutes();
});

afterEach(() => {
  jest.restoreAllMocks();
});

describe('Escenario 1 — Login exitoso persiste el token y navega [AT-11-01-01]', () => {
  it('persiste el token en el almacén cifrado y muestra la vista autenticada', async () => {
    stubLoginOk();
    renderApp();
    await completarLogin();

    // El token queda en el almacenamiento **cifrado** del SO (RN-2).
    await waitFor(() => expect(secure.set).toHaveBeenCalledWith(TOKEN_KEY, CUENTA.token));
    expect(secure.memory.get(TOKEN_KEY)).toBe(CUENTA.token);

    // Y la app navega a la vista autenticada.
    expect(await screen.findByTestId('deposit-address')).toBeTruthy();

    // La password no queda almacenada en ningún medio: el único `setItemAsync` es el del
    // token, y su valor no la contiene.
    for (const call of secure.set.mock.calls) {
      expect(String(call[1])).not.toContain(CUENTA.password);
    }
    // El request de login es el único lugar donde viaja la password.
    const loginRequests = fetchMock.requests.filter((request) => request.url.includes('/auth/login'));
    expect(loginRequests).toHaveLength(1);
    expect(JSON.parse(loginRequests[0].body ?? '{}')).toEqual({
      email: CUENTA.email,
      password: CUENTA.password,
    });
  });

  it('las peticiones autenticadas posteriores llevan el token en el header Authorization (RN-5)', async () => {
    stubLoginOk();
    renderApp();
    await completarLogin();
    await screen.findByTestId('deposit-address');

    const protegidas = fetchMock.requests.filter((request) =>
      request.url.includes('/deposit-address'),
    );
    expect(protegidas.length).toBeGreaterThan(0);
    for (const request of protegidas) {
      expect(request.headers.authorization).toBe(`Bearer ${CUENTA.token}`);
      // El token no viaja en la URL ni en el cuerpo (RN-7).
      expect(request.url).not.toContain(CUENTA.token);
      expect(request.body ?? '').not.toContain(CUENTA.token);
    }
  });
});

describe('Escenario 2 — Restauración de sesión al abrir la app (optimista) [AT-11-01-02]', () => {
  it('restaura la sesión sin pedir credenciales y sin llamada de validación previa (RN-10)', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    const store = new SessionStore();
    await store.restore();

    expect(store.getState().status).toBe('authenticated');
    expect(store.getState().token).toBe(CUENTA.token);
    // La restauración es puramente local: el store no tiene ninguna dependencia HTTP, y no
    // se emitió ninguna petición al backend.
    expect(fetchMock.requests).toHaveLength(0);
  });

  it('muestra directamente la vista autenticada en un arranque en frío', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    const navegaciones: string[] = [];
    renderApp({ onNavigate: (route) => navegaciones.push(route) });

    expect(await screen.findByTestId('deposit-address')).toBeTruthy();
    expect(screen.queryByTestId('login-submit')).toBeNull();
    // Nunca se pasó por el login: del splash directo a la vista autenticada.
    expect(navegaciones).toEqual(['splash', 'deposit']);
  });
});

describe('Escenario 3 (borde) — Apertura sin token persistido [AT-11-01-03]', () => {
  it('muestra el login y no llama a ningún endpoint autenticado', async () => {
    renderApp();

    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    expect(fetchMock.requests).toHaveLength(0);
  });
});

describe('Escenario 4 (error) — Credenciales inválidas [AT-11-01-04]', () => {
  it.each([
    ['email inexistente', 'nadie@example.com'],
    ['email existente con password incorrecta', CUENTA.email],
  ])('con %s muestra el mismo mensaje genérico y no persiste token', async (_caso, email) => {
    fetchMock.on('/auth/login', () => errorResponse(401, 'INVALID_CREDENTIALS'));
    renderApp();

    fireEvent.changeText(await screen.findByTestId('login-email'), email);
    fireEvent.changeText(screen.getByTestId('login-password'), 'incorrecta');
    fireEvent.press(screen.getByTestId('login-submit'));

    // Mensaje idéntico en ambos casos: no revela si el email existe (RN-3).
    expect(await screen.findByTestId('login-error')).toHaveTextContent(
      INVALID_CREDENTIALS_MESSAGE,
    );
    expect(secure.set).not.toHaveBeenCalled();
    // El usuario permanece en el login para reintentar, con la password limpia.
    expect(screen.getByTestId('login-submit')).toBeTruthy();
    expect(screen.getByTestId('login-password').props.value).toBe('');
  });
});

describe('Escenario 5 (error) — Token expirado en una petición autenticada [AT-11-01-05]', () => {
  it('borra el token persistido, limpia la sesión y redirige al login', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    fetchMock.on('/deposit-address', () => errorResponse(401, 'UNAUTHENTICATED'));
    fetchMock.on('/me', () => errorResponse(401, 'UNAUTHENTICATED'));
    const navegaciones: string[] = [];
    renderApp({ onNavigate: (route) => navegaciones.push(route) });

    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
    expect(secure.memory.has(TOKEN_KEY)).toBe(false);
    expect(await screen.findByTestId('login-notice')).toHaveTextContent(SESSION_EXPIRED_MESSAGE);
    expect(navegaciones).toEqual(['splash', 'deposit', 'login']);
  });
});

describe('Escenario 6 — Logout borra el token [AT-11-01-06]', () => {
  it('borra el token del almacén y de memoria, vuelve al login y no restaura al reabrir', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    const { unmount } = renderApp();

    fireEvent.press(await screen.findByTestId('logout'));

    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
    expect(secure.memory.has(TOKEN_KEY)).toBe(false);
    unmount();

    // Reabrir la app vuelve a pedir credenciales.
    renderApp();
    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    expect(screen.queryByTestId('deposit-address')).toBeNull();
  });
});

describe('Escenario 7 (borde) — Validación de campos en cliente [AT-11-01-07]', () => {
  it.each([
    ['ambos vacíos', '', ''],
    ['password vacía', CUENTA.email, ''],
    ['email vacío', '', CUENTA.password],
    ['email con formato inválido', 'no-es-un-email', CUENTA.password],
  ])('con %s bloquea el envío y muestra la validación local', async (_caso, email, password) => {
    stubLoginOk();
    renderApp();

    if (email !== '') fireEvent.changeText(await screen.findByTestId('login-email'), email);
    if (password !== '') {
      fireEvent.changeText(await screen.findByTestId('login-password'), password);
    }
    fireEvent.press(await screen.findByTestId('login-submit'));

    const mensajes = [
      screen.queryByTestId('login-email-error'),
      screen.queryByTestId('login-password-error'),
    ].filter((node) => node !== null);
    expect(mensajes.length).toBeGreaterThan(0);
    // No se hizo ninguna petición al backend hasta corregir los campos.
    expect(fetchMock.requests).toHaveLength(0);
  });

  it('corregidos los campos, el envío procede', async () => {
    stubLoginOk();
    renderApp();

    fireEvent.press(await screen.findByTestId('login-submit'));
    expect(fetchMock.requests).toHaveLength(0);

    await completarLogin();
    await waitFor(() =>
      expect(fetchMock.requests.some((request) => request.url.includes('/auth/login'))).toBe(true),
    );
  });
});

describe('Escenario 8a (seguridad) — el token sólo va al almacén cifrado [AT-11-01-08]', () => {
  it('SecureStore.setItemAsync recibe el token y AsyncStorage.setItem nunca se invoca', async () => {
    const asyncSet = jest.spyOn(AsyncStorage, 'setItem');
    const asyncMultiSet = jest.spyOn(AsyncStorage, 'multiSet');
    const asyncMerge = jest.spyOn(AsyncStorage, 'mergeItem');
    stubLoginOk();
    renderApp();
    await completarLogin();

    await waitFor(() => expect(secure.set).toHaveBeenCalledWith(TOKEN_KEY, CUENTA.token));
    // Ningún almacén en claro recibió jamás el token ni la password.
    for (const spy of [asyncSet, asyncMultiSet, asyncMerge]) {
      expect(spy).not.toHaveBeenCalled();
    }
  });
});

describe('Escenario 8b (seguridad) — ni token ni password se loggean [AT-11-01-11]', () => {
  it('ninguna invocación de console.* contiene el token ni la password', async () => {
    const consola = installConsoleSpies();
    stubLoginOk();
    renderApp();
    await completarLogin();
    await screen.findByTestId('deposit-address');

    const texto = consola.allText();
    expect(texto).not.toContain(CUENTA.token);
    expect(texto).not.toContain(CUENTA.password);
  });
});

describe('Escenario 9 (error) — Fallo de red durante el login [AT-11-01-09]', () => {
  it('muestra un error de conectividad distinto de INVALID_CREDENTIALS y permite reintentar', async () => {
    // Sin handler para `/auth/login`, la petición rechaza: no hay respuesta del backend.
    renderApp();
    await completarLogin();

    const error = await screen.findByTestId('login-error');
    expect(error).toHaveTextContent(CONNECTION_ERROR_MESSAGE);
    expect(error).not.toHaveTextContent(INVALID_CREDENTIALS_MESSAGE);
    expect(secure.set).not.toHaveBeenCalled();
    // El email ingresado se conserva para el reintento.
    expect(screen.getByTestId('login-email').props.value).toBe(CUENTA.email);

    stubLoginOk();
    fireEvent.changeText(screen.getByTestId('login-password'), CUENTA.password);
    fireEvent.press(screen.getByTestId('login-submit'));
    expect(await screen.findByTestId('deposit-address')).toBeTruthy();
  });
});

describe('Escenario 13 (concurrencia) — Logout singleton ante múltiples 401 [AT-11-01-14]', () => {
  it('varios UNAUTHENTICATED concurrentes producen un único borrado y una única navegación', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    const store = new SessionStore();
    await store.restore();
    expect(store.getState().status).toBe('authenticated');

    const transiciones: string[] = [];
    store.subscribe(() => transiciones.push(store.getState().status));

    // Tres peticiones en vuelo (balances + órdenes + market data, en el ejemplo de la spec)
    // reciben 401 a la vez.
    await Promise.all([
      store.handleUnauthenticated(CUENTA.token),
      store.handleUnauthenticated(CUENTA.token),
      store.handleUnauthenticated(CUENTA.token),
    ]);

    expect(secure.remove).toHaveBeenCalledTimes(1);
    // Una única limpieza de estado ⇒ una única transición a `anonymous` ⇒ una única
    // navegación al login (el destino se deriva del estado, ver `src/navigation/Router.tsx`).
    expect(transiciones).toEqual(['anonymous']);
    expect(store.getState()).toMatchObject({ status: 'anonymous', token: null });
  });

  it('un 401 posterior, con la sesión ya cerrada, es no-op', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    const store = new SessionStore();
    await store.restore();
    await store.handleUnauthenticated(CUENTA.token);
    secure.remove.mockClear();

    await store.handleUnauthenticated(CUENTA.token);
    expect(secure.remove).not.toHaveBeenCalled();
  });

  it('un 401 tardío de una sesión ya reemplazada no cierra la sesión nueva', async () => {
    const store = new SessionStore();
    await store.restore();
    await store.signIn('token-nuevo');

    await store.handleUnauthenticated('token-viejo');

    expect(store.getState()).toMatchObject({ status: 'authenticated', token: 'token-nuevo' });
    expect(secure.remove).not.toHaveBeenCalled();
  });
});

describe('Escenario 12 (borde, seguridad) — Fallo de lectura del almacén seguro [AT-11-01-13]', () => {
  it('se trata como "sin token": muestra el login sin exponer el error interno', async () => {
    secure.failReadsWith(new Error('Keychain item inaccessible: Before First Unlock'));
    const consola = installConsoleSpies();
    renderApp();

    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    // El detalle interno no llega ni a la UI ni a los logs.
    expect(screen.queryByText(/Keychain/i)).toBeNull();
    expect(screen.queryByText(/Before First Unlock/i)).toBeNull();
    expect(consola.allText()).not.toContain('Keychain');
    // Y no se llamó a ningún endpoint autenticado.
    expect(fetchMock.requests).toHaveLength(0);
  });

  it('el siguiente intento de lectura vuelve a consultar el almacén (RN-11)', async () => {
    secure.failReadsWith(new Error('Keychain item inaccessible'));
    const store = new SessionStore();
    await store.restore();
    expect(store.getState().status).toBe('anonymous');
    expect(secure.get).toHaveBeenCalledTimes(1);

    const otro = new SessionStore();
    await otro.restore();
    expect(secure.get).toHaveBeenCalledTimes(2);
  });
});

describe('Escenario 10 (ciclo de vida) — Reanudación desde background [AT-11-01-10]', () => {
  it('la sesión se mantiene sin re-autenticación al volver a foreground', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    const { AppState } = jest.requireActual<typeof import('react-native')>('react-native');
    renderApp();
    expect(await screen.findByTestId('deposit-address')).toBeTruthy();

    await act(async () => {
      // @ts-expect-error: en el entorno de test AppState expone el emisor interno.
      AppState.emit?.('change', 'background');
    });
    await act(async () => {
      // @ts-expect-error: idem al volver a foreground.
      AppState.emit?.('change', 'active');
    });

    expect(screen.getByTestId('deposit-address')).toBeTruthy();
    expect(screen.queryByTestId('login-submit')).toBeNull();
    expect(secure.remove).not.toHaveBeenCalled();
  });
});
