/**
 * Criterios de aceptación de la **pantalla de depósito** de HU-11-06
 * (`spec/11-cliente-mobile/HU-11-06-depositos-y-retiros-mobile.md`), alcance de esta
 * corrida: **Escenario 1 (AT-11-06-01)** y **Escenario 26 (AT-11-06-26)**.
 *
 * El seguimiento de depósitos y todo el flujo de retiros quedan fuera: su backend
 * (épicas 07 y 08) no está implementado.
 */
import { fireEvent, render, screen, waitFor } from '@testing-library/react-native';
import * as Clipboard from 'expo-clipboard';
import QRCode from 'react-native-qrcode-svg';
import { App } from '../src/App';
import { isValidChecksumAddress } from '../src/chain/address';
import { TOKEN_KEY } from '../src/session/secureStorage';
import {
  CUENTA,
  DEPOSITO,
  createFetchMock,
  installSecureStoreFake,
  jsonResponse,
  type FetchMock,
  type SecureStoreFake,
} from './support';

const BASE_URL = 'http://backend.test/api/v1';

let fetchMock: FetchMock;
let secure: SecureStoreFake;
let copiar: jest.SpyInstance;

/** Respuesta de `GET /deposit-address?asset=` tal como la fija HU-09-01 RN-10 / HU-06-04 RN-6. */
function stubDepositAddress(): void {
  fetchMock.on('/deposit-address', (request) => {
    const asset = request.url.includes('asset=USDC') ? 'USDC' : 'ETH';
    return jsonResponse(200, {
      asset,
      address: DEPOSITO.address,
      network: 'sepolia',
      chainId: '11155111',
      derivationPath: "m/44'/60'/0'/0/0",
      ...(asset === 'USDC' ? { tokenAddress: DEPOSITO.tokenAddress } : {}),
    });
  });
}

function qrValue(): string {
  return screen.UNSAFE_getByType(QRCode).props.value as string;
}

beforeEach(() => {
  fetchMock = createFetchMock();
  secure = installSecureStoreFake({ [TOKEN_KEY]: CUENTA.token });
  copiar = jest.spyOn(Clipboard, 'setStringAsync').mockResolvedValue(true);
  fetchMock.on('/me', () =>
    jsonResponse(200, {
      accountId: CUENTA.accountId,
      email: CUENTA.email,
      status: 'ACTIVE',
      createdAt: '2026-01-01T00:00:00.000Z',
    }),
  );
  stubDepositAddress();
  render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
});

afterEach(() => {
  jest.restoreAllMocks();
});

describe('Escenario 1 — Mostrar dirección de depósito con QR [AT-11-06-01]', () => {
  it('obtiene la dirección de la API y la muestra con checksum EIP-55', async () => {
    const address = await screen.findByTestId('deposit-address');
    expect(address).toHaveTextContent(DEPOSITO.address);
    // `0x` + 40 hex con checksum EIP-55 válido (RN-2).
    expect(/^0x[0-9a-fA-F]{40}$/.test(DEPOSITO.address)).toBe(true);
    expect(isValidChecksumAddress(DEPOSITO.address)).toBe(true);
    expect(screen.queryByTestId('deposit-address-checksum-warning')).toBeNull();

    // RN-1: la dirección **viene de la API**, con el token de la sesión.
    const consultas = fetchMock.requests.filter((request) =>
      request.url.includes('/deposit-address'),
    );
    expect(consultas.length).toBeGreaterThan(0);
    expect(consultas[0].url).toContain('asset=ETH');
    expect(consultas[0].headers.authorization).toBe(`Bearer ${CUENTA.token}`);
  });

  it('muestra el QR de la dirección (URI EIP-681 de ETH nativo)', async () => {
    await screen.findByTestId('deposit-address');
    expect(screen.getByTestId('deposit-qr-frame')).toBeTruthy();
    expect(qrValue()).toBe(`ethereum:${DEPOSITO.address}@11155111`);
  });

  it('ofrece copiar la dirección al portapapeles', async () => {
    await screen.findByTestId('deposit-address');
    fireEvent.press(screen.getByTestId('deposit-copy'));

    await waitFor(() => expect(copiar).toHaveBeenCalledWith(DEPOSITO.address));
    expect(await screen.findByText('Dirección copiada')).toBeTruthy();
  });

  it('aclara que la red es Sepolia (chainId 11155111) y el activo correspondiente', async () => {
    await screen.findByTestId('deposit-address');
    expect(screen.getByTestId('deposit-network')).toHaveTextContent('Sepolia');
    expect(screen.getByTestId('deposit-network')).toHaveTextContent('11155111');
    expect(screen.getByTestId('deposit-asset-label')).toHaveTextContent('ETH');

    fireEvent.press(screen.getByTestId('deposit-asset-USDC'));
    await waitFor(() =>
      expect(screen.getByTestId('deposit-asset-label')).toHaveTextContent('USDC'),
    );
    expect(screen.getByTestId('deposit-network')).toHaveTextContent('11155111');
  });
});

describe('Escenario 26 — QR EIP-681 de USDC-mock [AT-11-06-26]', () => {
  it('codifica ethereum:<tokenAddress>@11155111/transfer?address=<depositAddress>', async () => {
    await screen.findByTestId('deposit-address');
    fireEvent.press(screen.getByTestId('deposit-asset-USDC'));

    await waitFor(() =>
      expect(
        fetchMock.requests.some((request) => request.url.includes('asset=USDC')),
      ).toBe(true),
    );
    await waitFor(() =>
      expect(qrValue()).toBe(
        `ethereum:${DEPOSITO.tokenAddress}@11155111/transfer?address=${DEPOSITO.address}`,
      ),
    );
  });

  it('muestra además el address en texto con checksum EIP-55 como respaldo', async () => {
    await screen.findByTestId('deposit-address');
    fireEvent.press(screen.getByTestId('deposit-asset-USDC'));

    await waitFor(() =>
      expect(screen.getByTestId('deposit-asset-label')).toHaveTextContent('USDC'),
    );
    // La misma **única** dirección recibe ETH y USDC-mock (RN-2): sólo cambia el QR.
    expect(screen.getByTestId('deposit-address')).toHaveTextContent(DEPOSITO.address);
    expect(isValidChecksumAddress(DEPOSITO.address)).toBe(true);
  });

  it('sin `tokenAddress` en la respuesta degrada a sólo texto, sin inventar un contrato', async () => {
    fetchMock.on('/deposit-address', (request) =>
      jsonResponse(200, {
        asset: request.url.includes('asset=USDC') ? 'USDC' : 'ETH',
        address: DEPOSITO.address,
      }),
    );
    fireEvent.press(await screen.findByTestId('deposit-asset-USDC'));

    expect(await screen.findByTestId('deposit-qr-unavailable')).toBeTruthy();
    expect(screen.getByTestId('deposit-address')).toHaveTextContent(DEPOSITO.address);
    expect(screen.UNSAFE_queryByType(QRCode)).toBeNull();
  });
});

describe('RN-12 — la pantalla de depósito no expone secretos', () => {
  it('ni los requests ni lo renderizado mencionan mnemonic, seed o clave privada', async () => {
    await screen.findByTestId('deposit-address');
    fireEvent.press(screen.getByTestId('deposit-asset-USDC'));
    await waitFor(() =>
      expect(screen.getByTestId('deposit-asset-label')).toHaveTextContent('USDC'),
    );

    const salientes = JSON.stringify(fetchMock.requests);
    const renderizado = JSON.stringify(screen.toJSON());
    for (const secreto of ['mnemonic', 'seed', 'privateKey', 'private key', 'frase']) {
      expect(salientes.toLowerCase()).not.toContain(secreto.toLowerCase());
      expect(renderizado.toLowerCase()).not.toContain(secreto.toLowerCase());
    }
  });
});
