/**
 * Raíz de la app mobile (épica 11).
 *
 * Alcance de esta corrida: `HU-11-01` (login y persistencia segura del token) y la pantalla
 * de depósito de `HU-11-06` (dirección + QR). No hay más pantallas: el backend de las
 * épicas 02–08 no está implementado.
 */
import { StatusBar } from 'expo-status-bar';
import { StyleSheet } from 'react-native';
import {
  SafeAreaProvider,
  SafeAreaView,
  initialWindowMetrics,
} from 'react-native-safe-area-context';
import { Router, type RouteName } from './navigation/Router';
import { SessionProvider, useSession, type SessionProviderProps } from './session/SessionProvider';
import { PrivacyOverlay } from './ui/PrivacyOverlay';
import type { AppStateLike } from './ui/appState';
import { colors } from './ui/theme';

export interface AppProps extends Omit<SessionProviderProps, 'children'> {
  /** Observador de navegación (tests). */
  onNavigate?: (route: RouteName) => void;
}

interface ShellProps {
  onNavigate?: (route: RouteName) => void;
  appState?: AppStateLike;
}

function Shell({ onNavigate, appState }: ShellProps) {
  const { status } = useSession();
  return (
    // RG-9: el overlay de privacidad sólo tapa pantallas **autenticadas**; en el login no
    // hay datos de cuenta que proteger del screenshot del app switcher.
    <PrivacyOverlay
      enabled={status === 'authenticated'}
      {...(appState !== undefined ? { appState } : {})}
    >
      <SafeAreaView style={styles.safe} edges={['top', 'bottom']}>
        <StatusBar style="light" />
        <Router {...(onNavigate !== undefined ? { onNavigate } : {})} />
      </SafeAreaView>
    </PrivacyOverlay>
  );
}

export function App(props: AppProps = {}) {
  const { onNavigate, ...sessionProps } = props;
  const { appState } = props;
  return (
    // `initialWindowMetrics` evita el primer frame en blanco mientras el proveedor mide.
    <SafeAreaProvider initialMetrics={initialWindowMetrics}>
      <SessionProvider {...sessionProps}>
        <Shell
          {...(onNavigate !== undefined ? { onNavigate } : {})}
          {...(appState !== undefined ? { appState } : {})}
        />
      </SessionProvider>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.background },
});

