content.content:
/**
 * Overlay de privacidad en background (épica 11, RG-9).
 *
 * Al recibir `AppState = inactive`/`background` se superpone una capa **opaca** sobre toda
 * la pantalla **antes** de que el SO capture el screenshot para el app switcher, para no
 * exponer datos de la cuenta (dirección de depósito, balances, historial). Al volver a
 * `active` se retira.
 *
 * Aplica a las pantallas **autenticadas** y no interfiere con el ciclo de vida de las
 * suscripciones WebSocket (RG-5), que vive en `SessionProvider`.
 */
import { useEffect, useState, type ReactNode } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { currentAppState, resolveAppState, type AppStateLike, type AppStateStatus } from './appState';
import { colors, spacing } from './theme';

export interface PrivacyOverlayProps {
  children: ReactNode;
  /** Si es `false` no se tapa nada (pantallas no autenticadas: no hay datos que proteger). */
  enabled?: boolean;
  /** Fuente del ciclo de vida; por defecto el `AppState` de React Native (tests: doble). */
  appState?: AppStateLike;
}

export function PrivacyOverlay({ children, enabled = true, appState }: PrivacyOverlayProps) {
  const source = resolveAppState(appState);
  const [state, setState] = useState<AppStateStatus>(() => currentAppState(source));

  useEffect(() => {
    const subscription = source.addEventListener('change', setState);
    return () => subscription.remove();
  }, [source]);

  const hidden = enabled && state !== 'active';

  return (
    <View style={styles.container}>
      {children}
      {hidden ? (
        <View style={styles.overlay} testID="privacy-overlay" accessibilityElementsHidden>
          <Text style={styles.label}>Contenido protegido</Text>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  overlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    // Opaco (sin transparencia): el screenshot del app switcher no debe dejar ver nada.
    backgroundColor: colors.background,
    alignItems: 'center',
    justifyContent: 'center',
    padding: spacing.lg,
  },
  label: { color: colors.textMuted, fontSize: 16 },
});

