import { fireEvent, render, screen, waitFor } from '@testing-library/react-native';
import QRCode from 'react-native-qrcode-svg';
import { App } from '../src/App';
import { isValidChecksumAddress } from '../src/chain/address';
import { TOKEN_KEY } from '../src/session/secureStorage';
import { installSecureStoreFake, type SecureStoreFake } from './support';

const HABILITADO = process.env.MOBILE_E2E === '1';
const BASE_URL = process.env.MOBILE_E2E_API_BASE_URL ?? 'http://localhost:3000/api/v1';

const describeE2E = HABILITADO ? describe : describe.skip;

/** Cuenta nueva por corrida: el registro es idempotente sólo por email (HU-01-01 RN-4). */
const EMAIL = `mobile-e2e-${Date.now()}@example.com`;
const PASSWORD = 'Contraseña-E2E-12345';

let secure: SecureStoreFake;

describeE2E('Cliente mobile contra el backend real', () => {
  beforeAll(async () => {
    const response = await fetch(`${BASE_URL}/auth/register`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
    });
    if (response.status !== 201) {
      throw new Error(
        `no se pudo registrar la cuenta de prueba (HTTP ${response.status}): ${await response.text()}`,
      );
    }
  });

  beforeEach(() => {
    secure = installSecureStoreFake();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('permite loguearse y ver la dirección de depósito con su QR', async () => {
    render(<App baseUrl={BASE_URL} wsUrl="" />);

    fireEvent.changeText(await screen.findByTestId('login-email'), EMAIL);
    fireEvent.changeText(screen.getByTestId('login-password'), PASSWORD);
