    const address = (await screen.findByTestId('deposit-address')).props.children as string;
    expect(/^0x[0-9a-fA-F]{40}$/.test(address)).toBe(true);
    expect(isValidChecksumAddress(address)).toBe(true);
    expect(screen.getByTestId('deposit-network')).toHaveTextContent(/11155111/);
    expect(screen.UNSAFE_getByType(QRCode).props.value).toBe(`ethereum:${address}@11155111`);
    expect(screen.getByTestId('session-email')).toHaveTextContent(EMAIL);

    // El QR de USDC-mock usa el `tokenAddress` que devuelve la API (AT-11-06-26).
    fireEvent.press(screen.getByTestId('deposit-asset-USDC'));
    const respuestaUsdc = await (
      await fetch(`${BASE_URL}/deposit-address?asset=USDC`, {
        headers: { authorization: `Bearer ${token}` },
      })
    ).json();
    expect(respuestaUsdc.address).toBe(address);
    await waitFor(() =>
      expect(screen.UNSAFE_getByType(QRCode).props.value).toBe(
        `ethereum:${respuestaUsdc.tokenAddress}@11155111/transfer?address=${address}`,
      ),
    );
  });

  it('con credenciales incorrectas muestra el mensaje genérico y no persiste token', async () => {
    render(<App baseUrl={BASE_URL} wsUrl="" />);

    fireEvent.changeText(await screen.findByTestId('login-email'), EMAIL);
    fireEvent.changeText(screen.getByTestId('login-password'), 'password-incorrecta');
    fireEvent.press(screen.getByTestId('login-submit'));

    expect(await screen.findByTestId('login-error')).toHaveTextContent(
      'Email o contraseña incorrectos',
    );
    expect(secure.set).not.toHaveBeenCalled();
  });

  it('un token inválido dispara el cierre de sesión al primer 401 (RN-5/RN-10)', async () => {
    secure.memory.set(TOKEN_KEY, 'token-que-el-backend-no-conoce');
    render(<App baseUrl={BASE_URL} wsUrl="" />);

    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
    expect(await screen.findByTestId('login-notice')).toHaveTextContent(
      'Tu sesión expiró, ingresá nuevamente',
    );
  });
});
