/** Evita notificar dos veces el mismo `UNAUTHENTICATED` (p. ej. mensaje + cierre). */
private unauthenticatedNotified = false;

constructor(options: PrivateChannelOptions) {
  this.url = options.url;
  this.getToken = options.getToken;
  this.onUnauthenticated = options.onUnauthenticated;
  this.channels = options.channels ?? [];
  this.onMessage = options.onMessage;
  this.onStatusChange = options.onStatusChange;
  this.webSocketImpl = options.webSocketImpl;
  this.setTimeoutImpl = options.setTimeoutImpl ?? setTimeout;
  this.clearTimeoutImpl = options.clearTimeoutImpl ?? clearTimeout;
  this.random = options.random ?? Math.random;
}

get status(): ConnectionStatus {
  return this.currentStatus;
}

/** Conecta (o reconecta). Idempotente: llamarlo dos veces no abre dos sockets. */
start(): void {
  // Un `start()` explícito es intención fresca del usuario (típicamente tras un login
  // nuevo): limpia el "sesión terminada" y el backoff acumulado.
  this.started = true;
  this.suspended = false;
  this.sessionEnded = false;
  if (this.socket !== null || this.retryTimer !== null) return;
  this.retryCount = 0;
  this.connect();
}

/** Cierra el socket y cancela reintentos pendientes. */
stop(): void {
  this.started = false;
  this.suspended = false;
  this.cancelRetry();
  this.closeSocket();
  this.retryCount = 0;
  this.setStatus('idle');
}

/** Ciclo de vida (RG-5): background suspende, foreground reconecta y re-sincroniza. */
handleAppStateChange(state: 'active' | 'inactive' | 'background'): void {
  if (state === 'background' || state === 'inactive') {
    if (this.suspended) return;
    this.suspended = true;
    // Suspender **no** es un fallo de autenticación: se cancelan timers y se cierra el
    // socket sin tocar `onUnauthenticated` (RG-5, AT-11-01-10).
    this.cancelRetry();
    this.closeSocket();
    if (this.started) this.setStatus('suspended');
    return;
  }
  if (!this.suspended) return;
  this.suspended = false;
  if (!this.started || this.sessionEnded) return;
  // Foreground: se reconecta **de inmediato** (delay 0) y el nuevo handshake + los nuevos
  // `subscribe` traen un snapshot fresco antes de los deltas (RG-5 + RG-API-7).
  this.cancelRetry();
  this.retryCount = 0;
  this.connect();
}

/**
 * Delay del próximo reintento (RG-10): `1000 · 2^n` topeado en 30000, más jitter uniforme
 * en ±500 ms, nunca negativo. Consume una muestra de `random`, igual que el agendado real.
 */
nextDelayMs(): number {
  const base = Math.min(
    BACKOFF_INITIAL_MS * Math.pow(BACKOFF_FACTOR, this.retryCount),
    BACKOFF_MAX_MS,
  );
  const jitter = (this.random() * 2 - 1) * BACKOFF_JITTER_MS;
  return Math.max(0, base + jitter);
}

// --- internos -------------------------------------------------------------------------

private connect(): void {
  const token = this.getToken();
  // Sin sesión no hay canal privado que abrir (HU-09-04 RN-1: exige token).
  if (token === null || token === '') {
    this.setStatus('idle');
    return;
  }
  const WebSocketImpl = this.webSocketImpl ?? (globalThis as { WebSocket?: WebSocketLike }).WebSocket;
  if (WebSocketImpl === undefined) {
    this.setStatus('idle');
    return;
  }

  this.tokenUsed = token;
  this.unauthenticatedNotified = false;
  this.setStatus('connecting');

  // La url no lleva el token en ningún parámetro (HU-09-04 RN-1).
  const socket = new WebSocketImpl(this.url);
  this.socket = socket;

  socket.onopen = (): void => {
    if (this.socket !== socket) return;
    // Primer mensaje del handshake, antes de cualquier `subscribe` (HU-09-04 RN-1).
    this.send(socket, { type: 'auth', token });
  };
  socket.onmessage = (event: WebSocketMessageEventLike): void => {
    if (this.socket !== socket) return;
    this.handleMessage(socket, event);
  };
  socket.onerror = (): void => {
    this.handleDisconnect(socket);
  };
  socket.onclose = (): void => {
    this.handleDisconnect(socket);
  };
}

private handleMessage(socket: WebSocketInstanceLike, event: WebSocketMessageEventLike): void {
  const parsed = this.parse(event.data);
  if (parsed === undefined) return;

  // `UNAUTHENTICATED` en cualquier momento (handshake o canal ya autenticado):
  // HU-11-01 RN-12 / AT-11-01-12.
  if (readErrorCode(parsed) === 'UNAUTHENTICATED') {
    this.handleUnauthenticated(socket);
    return;
  }

  const type = readMessageType(parsed);
  if (type === 'authenticated') {
    // Conexión exitosa: se resetea el backoff a 1 s (RG-10) y se suscriben los canales.
    this.retryCount = 0;
    this.setStatus('live');
    for (const channel of this.channels) {
      this.send(socket, { type: 'subscribe', channel });
    }
    return;
