     1	/**
     2	 * Construcción del URI **EIP-681** que se codifica en el QR de la pantalla de depósito.
     3	 *
     4	 * Fuente de verdad: `spec/11-cliente-mobile/HU-11-06-depositos-y-retiros-mobile.md` RN-2 y
     5	 * Escenario 26 (AT-11-06-26). Textualmente (RN-2):
     6	 *
     7	 *   «**Formato del QR (EIP-681):** para que las wallets externas no envíen el activo o la red
     8	 *   equivocados, el QR se genera como URI EIP-681: para **ETH nativo**
     9	 *   `ethereum:<depositAddress>@11155111`; para **USDC-mock**
    10	 *   `ethereum:<USDC_CONTRACT_ADDRESS>@11155111/transfer?address=<depositAddress>` (donde
    11	 *   `<USDC_CONTRACT_ADDRESS>` es el campo **`tokenAddress`** devuelto por
    12	 *   `GET /deposit-address?asset=USDC`, épica 09 HU-09-01 RN-10 / HU-06-04 RN-6; es
    13	 *   configuración por entorno, no un literal de la spec). Siempre se muestra **además** el
    14	 *   address en texto con checksum EIP-55 como respaldo para wallets que no soporten
    15	 *   EIP-681.»
    16	 *
    17	 * Notar la asimetría del caso ERC-20: el destinatario del URI es el **contrato** del token y
    18	 * la dirección de depósito viaja como parámetro `address` de la llamada `transfer` — una
    19	 * **única** dirección Ethereum recibe tanto ETH como USDC-mock (RN-2), la diferencia la hace
    20	 * el tipo de transacción on-chain.
    21	 *
    22	 * Módulo TypeScript puro: sin React Native ni APIs de Node.
    23	 */
    24	
    25	import { isAddressLike, toChecksumAddress } from './address';
    26	
    27	/**
    28	 * `chainId` de **Sepolia**, la única red del proyecto (constante fundacional:
    29	 * `spec/00-fundaciones/activos-y-par-de-trading.md`; RN-2 y RN-7 de HU-11-06). Se declara
    30	 * como string porque su único uso acá es concatenarse en el URI, y así no queda expuesto a
    31	 * la precisión de `number` al serializar.
    32	 */
    33	export const SEPOLIA_CHAIN_ID = '11155111';
    34	
    35	/** Activos del proyecto que admiten depósito on-chain (par ETH/USDC-mock, fundaciones). */
    36	export type DepositAsset = 'ETH' | 'USDC';
    37	
    38	/**
    39	 * Falta el `tokenAddress` (dirección del contrato USDC-mock) para armar el URI de un
    40	 * depósito de USDC.
    41	 *
    42	 * **Decisión:** se lanza un error explícito en vez de devolver un URI incompleto o inventar
    43	 * una dirección por defecto. El `tokenAddress` es **configuración por entorno** que llega en
    44	 * la respuesta de `GET /api/v1/deposit-address?asset=USDC` (RN-2): hardcodear un default
    45	 * dirigiría fondos reales a un contrato equivocado, y un URI a medias haría que la wallet
    46	 * externa enviara el activo incorrecto — exactamente lo que RN-2 busca evitar.
    47	 *
    48	 * La pantalla captura este error y **degrada** mostrando sólo el address en texto con
    49	 * checksum EIP-55, que RN-2 exige mostrar siempre como respaldo.
    50	 */
    51	export class MissingTokenAddressError extends Error {
    52	  constructor(message: string) {
    53	    super(message);
    54	    this.name = 'MissingTokenAddressError';
    55	  }
    56	}
    57	
    58	export interface DepositUriParams {
    59	  asset: DepositAsset;
    60	  /** Dirección de depósito de la cuenta, obtenida de la API (RN-1: el cliente no la deriva). */
    61	  depositAddress: string;
    62	  /** Dirección del contrato USDC-mock (`tokenAddress` de la API). Requerida para `USDC`. */
    63	  tokenAddress?: string;
    64	}
    65	
    66	/**
    67	 * Normaliza una dirección para incrustarla en el URI: exige la forma `0x` + 40 hex y la
    68	 * emite con checksum EIP-55 (RN-2 pide el address con checksum).
    69	 *
    70	 * Deliberadamente NO se exige que la entrada **ya** venga con un checksum válido: la caja de
    71	 * los dígitos no cambia los 20 bytes de la dirección, así que recalcularlo es seguro y evita
    72	 * quedarse sin QR si la API devuelve la dirección en minúsculas. Lo que sí es error es un
    73	 * largo/prefijo/carácter inválido: ahí no hay dirección que codificar.
    74	 */
    75	function normalizeForUri(value: string, label: string): string {
    76	  if (!isAddressLike(value)) {
    77	    throw new Error(`${label} inválida: se esperaba \`0x\` + 40 dígitos hexadecimales`);
    78	  }
    79	  return toChecksumAddress(value);
    80	}
    81	
    82	/**
    83	 * Devuelve el URI EIP-681 a codificar en el QR de depósito (RN-2, AT-11-06-26):
    84	 *  - `ETH`  => `ethereum:<depositAddress>@11155111`
    85	 *  - `USDC` => `ethereum:<tokenAddress>@11155111/transfer?address=<depositAddress>`
    86	 *
    87	 * Lanza `MissingTokenAddressError` si `asset = 'USDC'` y no hay `tokenAddress` utilizable, y
    88	 * `Error` si alguna dirección no tiene la forma `0x` + 40 hex.
    89	 */
    90	export function buildDepositUri(params: DepositUriParams): string {
    91	  const { asset, depositAddress, tokenAddress } = params;
    92	  const deposit = normalizeForUri(depositAddress, 'dirección de depósito');
    93	
    94	  if (asset === 'ETH') {
    95	    return `ethereum:${deposit}@${SEPOLIA_CHAIN_ID}`;
    96	  }
    97	
    98	  if (asset === 'USDC') {
    99	    if (typeof tokenAddress !== 'string' || tokenAddress.length === 0) {
   100	      throw new MissingTokenAddressError(
   101	        'falta `tokenAddress` (contrato USDC-mock) para armar el URI EIP-681 del depósito de ' +
   102	          'USDC; la pantalla debe mostrar sólo el address en texto (RN-2)'
   103	      );
   104	    }
   105	    const token = normalizeForUri(tokenAddress, 'dirección del contrato USDC-mock');
   106	    return `ethereum:${token}@${SEPOLIA_CHAIN_ID}/transfer?address=${deposit}`;
   107	  }
   108	
   109	  // `asset` está tipado como `DepositAsset`; este guard cubre datos que entran sin tipar
   110	  // (p. ej. una respuesta de la API con un activo desconocido).
   111	  throw new Error(`activo de depósito no soportado: ${String(asset)}`);
   112	}
=== chain/address
     1	/**
     2	 * Utilidades de direcciones Ethereum (EIP-55) para el cliente mobile.
     3	 *
     4	 * En el alcance de esta corrida los usa el **depósito** (HU-11-06 RN-2 / AT-11-06-01): la
     5	 * dirección se muestra en texto con checksum EIP-55 y se codifica en el QR (ver
     6	 * `eip681.ts`). La validación de la dirección **destino de un retiro** (RN-5) y la del
     7	 * address extraído de un QR escaneado (RN-9) quedan fuera de esta corrida —su backend, la
     8	 * épica 08, no está implementado—, pero comparten exactamente esta semántica.
     9	 *
    10	 * El backend es siempre el **autoritativo**: este módulo sólo adelanta el diagnóstico en el
    11	 * cliente, con la **misma semántica** que la implementación del backend
    12	 * (`src/wallet/hd.ts`, HU-06-02 RN-4), para que cliente y servidor no discrepen sobre qué
    13	 * direcciones son válidas.
    14	 *
    15	 * Módulo TypeScript puro: sin React Native, sin `node:crypto` ni ninguna API de Node.
    16	 * El Keccak-256 viene de `@noble/hashes` (JS puro, funciona en Hermes/React Native).
    17	 */
    18	
    19	import { keccak_256 } from '@noble/hashes/sha3';
    20	import { utf8ToBytes } from '@noble/hashes/utils';
    21	
    22	/** `0x` + 40 dígitos hexadecimales, en cualquier caja (forma sintáctica de RN-2/RN-5). */
    23	const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;
    24	
    25	/**
    26	 * `true` si `value` tiene la **forma** de una dirección Ethereum: `0x` + 40 hex.
    27	 *
    28	 * NO mira el checksum EIP-55: separa el error de formato (largo/prefijo/caracteres) del
    29	 * error de checksum, para que la UI pueda dar mensajes distintos mientras el usuario
    30	 * todavía está tipeando el destino (RN-5, feedback temprano).
    31	 */
    32	export function isAddressLike(value: string): boolean {
    33	  return typeof value === 'string' && ADDRESS_RE.test(value);
    34	}
    35	
    36	/**
    37	 * Devuelve la dirección con checksum EIP-55.
    38	 *
    39	 * Acepta la entrada con o sin prefijo `0x` y en cualquier caja (por ejemplo la forma
    40	 * enteramente en minúsculas que puede devolver un explorer o un QR ajeno). El algoritmo es
    41	 * el del EIP-55: `Keccak-256` sobre la cadena ASCII del hexadecimal en minúsculas (sin
    42	 * `0x`), y se pasa a mayúscula el dígito `i` si el nibble `i` del hash es `>= 8`.
    43	 *
    44	 * Lanza si la entrada no es `0x` + 40 hex: no hay "mejor esfuerzo" posible sobre una
    45	 * dirección de otro largo, y silenciar el caso podría terminar generando un QR hacia una
    46	 * dirección que no existe (RN-2).
    47	 */
    48	export function toChecksumAddress(value: string): string {
    49	  if (typeof value !== 'string') {
    50	    throw new Error('dirección inválida: se esperaba una cadena de texto');
    51	  }
    52	  const raw = value.startsWith('0x') || value.startsWith('0X') ? value.slice(2) : value;
    53	  if (!/^[0-9a-fA-F]{40}$/.test(raw)) {
    54	    throw new Error('dirección inválida: se esperan 40 dígitos hexadecimales (20 bytes)');
    55	  }
    56	  const lower = raw.toLowerCase();
    57	
    58	  const hash = keccak_256(utf8ToBytes(lower));
    59	  let out = '0x';
    60	  for (let i = 0; i < lower.length; i++) {
    61	    const ch = lower[i]!;
    62	    // nibble i del hash: byte i>>1, mitad alta si i es par.
    63	    const nibble = i % 2 === 0 ? hash[i >> 1]! >> 4 : hash[i >> 1]! & 0x0f;
    64	    out += nibble >= 8 ? ch.toUpperCase() : ch;
    65	  }
    66	  return out;
    67	}
    68	
    69	/**
    70	 * `true` si `value` es `0x` + 40 hex **y** su checksum EIP-55 verifica (RN-5).
    71	 *
    72	 * Decisión deliberada, idéntica a la del backend (`src/wallet/hd.ts`): una dirección
    73	 * **enteramente en minúsculas** o **enteramente en mayúsculas** devuelve `false`, porque no
    74	 * transporta un checksum EIP-55 verificable (el EIP las considera "sin checksum"; que
    75	 * coincidieran con la forma canónica sería casualidad). Aceptarlas acá haría que el cliente
    76	 * diera por buena una dirección que el backend rechaza con `INVALID_ADDRESS` (422).
    77	 *
    78	 * Único caso en que la regla anterior no aplica: direcciones **sin ningún dígito alfabético**
    79	 * (`a`-`f`), donde minúsculas y mayúsculas son la misma cadena y el checksum sí es
    80	 * verificable sin ambigüedad; ahí se compara contra la forma canónica.
    81	 */
    82	export function isValidChecksumAddress(value: string): boolean {
    83	  if (!isAddressLike(value)) return false;
    84	  const body = value.slice(2);
    85	  const hasCase = body.toLowerCase() !== body.toUpperCase();
    86	  if (hasCase && (body === body.toLowerCase() || body === body.toUpperCase())) return false;
    87	  return toChecksumAddress(body) === value;
    88	}

