  1	/**
  2	 * Enlace de React con `SessionStore` (HU-11-01).
  3	 *
  4	 * Provee el estado de sesión, el `ApiClient` ya configurado con el token vigente y el
  5	 * manejo de `UNAUTHENTICATED` (RN-5), y el canal WebSocket privado cuando hay una URL
  6	 * configurada (RN-12).
  7	 */
  8	import {
  9	  createContext,
 10	  useContext,
 11	  useEffect,
 12	  useMemo,
 13	  useRef,
 14	  useSyncExternalStore,
 15	  type ReactNode,
 16	} from 'react';
 17	import { ApiClient, type FetchLike } from '../api/client';
 18	import { API_BASE_URL, WS_URL } from '../config';
 19	import { resolveAppState, type AppStateLike } from '../ui/appState';
 20	import { PrivateChannel } from '../ws/privateChannel';
 21	import { SessionStore, type SessionState } from './sessionStore';
 22	
 23	export interface SessionContextValue extends SessionState {
 24	  api: ApiClient;
 25	  store: SessionStore;
 26	  signIn(token: string): Promise<void>;
 27	  signOut(): Promise<void>;
 28	  dismissNotice(): void;
 29	}
 30	
 31	const SessionContext = createContext<SessionContextValue | null>(null);
 32	
 33	export interface SessionProviderProps {
 34	  children: ReactNode;
 35	  /** Sobrescribe el prefijo de la API (tests / configuración explícita). */
 36	  baseUrl?: string;
 37	  /** Sobrescribe la implementación de `fetch` (tests). */
 38	  fetchImpl?: FetchLike;
 39	  /** Store inyectable (tests); por defecto se crea uno nuevo. */
 40	  store?: SessionStore;
 41	  /** URL del canal privado; vacía = no se conecta (ver `src/config.ts`). */
 42	  wsUrl?: string;
 43	  /** Fuente del ciclo de vida; por defecto el `AppState` de React Native (tests: doble). */
 44	  appState?: AppStateLike;
 45	}
 46	
 47	export function SessionProvider({
 48	  children,
 49	  baseUrl,
 50	  fetchImpl,
 51	  store: injectedStore,
 52	  wsUrl,
 53	  appState,
 54	}: SessionProviderProps) {
 55	  const storeRef = useRef<SessionStore | null>(injectedStore ?? null);
 56	  if (storeRef.current === null) storeRef.current = new SessionStore();
 57	  const store = storeRef.current;
 58	
 59	  const state = useSyncExternalStore(
 60	    (listener) => store.subscribe(listener),
 61	    () => store.getState(),
 62	    () => store.getState(),
 63	  );
 64	
 65	  const api = useMemo(
 66	    () =>
 67	      new ApiClient({
 68	        baseUrl: baseUrl ?? API_BASE_URL,
 69	        ...(fetchImpl !== undefined ? { fetchImpl } : {}),
 70	        getToken: store.getToken,
 71	        // RN-5 / RG-8: el manejo es singleton dentro del store.
 72	        onUnauthenticated: (tokenUsed) => {
 73	          void store.handleUnauthenticated(tokenUsed);
 74	        },
 75	      }),
 76	    [baseUrl, fetchImpl, store],
 77	  );
 78	
 79	  // RN-4: restauración de sesión al abrir la app. Corre una sola vez por montaje.
 80	  useEffect(() => {
 81	    void store.restore();
 82	  }, [store]);
 83	
 84	  // RN-12 + RG-5: canal privado con el mismo token del almacén seguro; se suspende en
 85	  // background y se reconecta (con snapshot fresco) al volver a foreground. Sólo se activa
 86	  // si hay una URL de WebSocket configurada: el backend de esta corrida no expone los
 87	  // canales de la épica 09 (HU-09-03/HU-09-04).
 88	  const resolvedWsUrl = wsUrl ?? WS_URL;
 89	  useEffect(() => {
 90	    if (resolvedWsUrl === '' || state.status !== 'authenticated') return;
 91	    const channel = new PrivateChannel({
 92	      url: resolvedWsUrl,
 93	      getToken: store.getToken,
 94	      onUnauthenticated: (tokenUsed) => {
 95	        void store.handleUnauthenticated(tokenUsed);
 96	      },
 97	      channels: ['balances'],
 98	    });
 99	    channel.start();
100	    const subscription = resolveAppState(appState).addEventListener('change', (next) => {
101	      if (next === 'active' || next === 'inactive' || next === 'background') {
102	        channel.handleAppStateChange(next);
103	      }
104	    });
105	    return () => {
106	      subscription.remove();
107	      channel.stop();
108	    };
109	  }, [appState, resolvedWsUrl, state.status, store]);
110	
111	  const value = useMemo<SessionContextValue>(
112	    () => ({
113	      ...state,
114	      api,
115	      store,
116	      signIn: (token: string) => store.signIn(token),
117	      signOut: () => store.signOut(),
118	      dismissNotice: () => store.dismissNotice(),
119	    }),
120	    [state, api, store],
121	  );
122	
123	  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
124	}
125	
126	export function useSession(): SessionContextValue {
127	  const value = useContext(SessionContext);
128	  if (!value) throw new Error('useSession requiere un <SessionProvider> ancestro');
129	  return value;
130	}
131	/**
132	 * Estado de sesión del cliente mobile (HU-11-01).
133	 *
134	 * Se implementa como un store observable sin dependencias de React: la lógica de RN-4,
135	 * RN-5, RN-6, RN-10 y RN-11 —incluida la garantía de **logout singleton** de RG-8— se
136	 * puede ejercitar y verificar sin montar la UI.
137	 *
138	 * Máquina de estados:
139	 *
140	 *   restoring ──(hay token en el almacén cifrado)──► authenticated
141	 *       │                                                 │
142	 *       └─(no hay token, o el almacén falla — RN-11)──┐    │ UNAUTHENTICATED (RN-5)
143	 *                                                     ▼    │ logout del usuario (RN-6)
144	 *                                                  anonymous ◄─┘
145	 *
146	 * La restauración es **optimista** (RN-10): si hay token se entra directo a la vista
147	 * autenticada, **sin** llamada de validación previa. La expiración se detecta de forma
148	 * reactiva, cuando la primera petición autenticada (REST o handshake WebSocket) recibe
149	 * `UNAUTHENTICATED`.
150	 */
151	import { SESSION_EXPIRED_MESSAGE } from '../api/errors';
152	import { deleteToken, readToken, writeToken } from './secureStorage';
153	
154	export type SessionStatus = 'restoring' | 'anonymous' | 'authenticated';
155	
156	export interface SessionState {
157	  status: SessionStatus;
158	  /** Token en memoria. Nunca se renderiza ni se loguea (RN-7). */
159	  token: string | null;
160	  /** Aviso a mostrar en la pantalla de login (p. ej. sesión expirada, RN-5). */
161	  notice: string | null;
162	}
163	
164	type Listener = () => void;
165	
166	export class SessionStore {
167	  private state: SessionState = { status: 'restoring', token: null, notice: null };
168	  private readonly listeners = new Set<Listener>();
169	  /**
170	   * Flujo de logout en curso (RG-8). Mientras haya uno, las activaciones adicionales son
171	   * **no-ops** y devuelven la misma promesa: un único borrado del token, una única
172	   * limpieza de estado y una única transición a `anonymous` (y por lo tanto una única
173	   * navegación al login).
174	   */
175	  private logoutInFlight: Promise<void> | null = null;
176	
177	  getState(): SessionState {
178	    return this.state;
179	  }
180	
181	  subscribe(listener: Listener): () => void {
182	    this.listeners.add(listener);
183	    return () => {
184	      this.listeners.delete(listener);
185	    };
186	  }
187	
188	  private setState(next: Partial<SessionState>): void {
189	    this.state = { ...this.state, ...next };
190	    for (const listener of this.listeners) listener();
191	  }
192	
193	  /** Token vigente, para el header `Authorization` y el handshake del WebSocket (RN-5/RN-12). */
194	  getToken = (): string | null => this.state.token;
195	
196	  /**
197	   * Restauración de sesión al abrir la app (RN-4 + RN-10). Nunca lanza: un fallo del
198	   * almacén seguro se trata como "sin token" y termina en la pantalla de login (RN-11).
199	   */
200	  async restore(): Promise<void> {
201	    const token = await readToken();
202	    if (token === null) {
203	      // AT-11-01-03 / AT-11-01-13: sin token (o con el almacén inaccesible) se muestra el
204	      // login y **no** se llama a ningún endpoint autenticado.
205	      this.setState({ status: 'anonymous', token: null });
206	      return;
207	    }
208	    // AT-11-01-02: se entra directo a la vista autenticada, sin validar contra el backend.
209	    this.setState({ status: 'authenticated', token, notice: null });
210	  }
211	
212	  /**
213	   * Establece la sesión tras un login exitoso (RN-2 / AT-11-01-01).
214	   *
215	   * Persiste **primero** en el almacén cifrado y recién después expone la sesión, para que
216	   * no exista un estado observable "autenticado pero sin persistir".
217	   */
218	  async signIn(token: string): Promise<void> {
219	    await writeToken(token);
220	    // Una sesión nueva deja atrás cualquier logout previo: el guard de RG-8 protege un
221	    // único flujo de cierre, no impide volver a cerrar la sesión siguiente.
222	    this.logoutInFlight = null;
223	    this.setState({ status: 'authenticated', token, notice: null });
224	  }
225	
226	  /** Logout explícito del usuario (RN-6). */
227	  async signOut(): Promise<void> {
228	    await this.runLogout(null);
229	  }
230	
231	  /**
232	   * `UNAUTHENTICATED` (401) recibido en una petición autenticada o en el canal privado
233	   * (RN-5 / RN-12): borra el token persistido, limpia el estado y vuelve al login.
234	   *
235	   * Es **singleton** (RG-8 / AT-11-01-14): varios 401 concurrentes producen un único
236	   * borrado y una única navegación.
237	   *
238	   * @param tokenUsed token con el que se hizo la petición que recibió el 401. Un 401 de
239	   * una sesión ya reemplazada (login nuevo mientras la petición vieja viajaba) se ignora.
240	   */
241	  handleUnauthenticated(tokenUsed: string | null = null): Promise<void> {
242	    if (this.logoutInFlight) return this.logoutInFlight;
243	    if (this.state.status !== 'authenticated') return Promise.resolve();
244	    if (tokenUsed !== null && tokenUsed !== this.state.token) return Promise.resolve();
245	    return this.runLogout(SESSION_EXPIRED_MESSAGE);
246	  }
247	
248	  private runLogout(notice: string | null): Promise<void> {
249	    if (this.logoutInFlight) return this.logoutInFlight;
250	    // La limpieza de memoria y la transición a `anonymous` son **síncronas**: cualquier
251	    // otro 401 que llegue mientras el borrado del almacén está en vuelo ya encuentra la
252	    // sesión cerrada, además del guard de `logoutInFlight`.
253	    this.setState({ status: 'anonymous', token: null, notice });
254	    const pending: Promise<void> = deleteToken().finally(() => {
255	      // Sólo se libera el guard si sigue siendo *este* logout el vigente: un `signIn`
256	      // posterior ya lo habrá reemplazado.
257	      if (this.logoutInFlight === pending) this.logoutInFlight = null;
258	    });
259	    this.logoutInFlight = pending;
260	    return pending;
261	  }
262	
263	  /** Descarta el aviso pendiente (se consume al mostrarlo en el login). */
264	  dismissNotice(): void {
265	    if (this.state.notice !== null) this.setState({ notice: null });
266	  }
267	}
268	/**
269	 * Persistencia del token de sesión en el almacenamiento **cifrado** del sistema operativo
270	 * (Keychain en iOS / Keystore en Android) vía Expo SecureStore.
271	 *
272	 * HU-11-01 RN-2: el token se persiste **únicamente** acá. Está **prohibido** guardarlo en
273	 * almacenamiento no cifrado en claro (p. ej. `AsyncStorage`) o en logs; por eso este módulo
274	 * es el **único** punto del cliente que escribe el token, y no importa ningún otro almacén.
275	 *
276	 * HU-11-01 RN-11: si la lectura falla (p. ej. *Keychain item inaccessible* en estado
277	 * *Before First Unlock* tras un reinicio, o el almacén no disponible), el caso se trata
278	 * **como si no hubiera token persistido**. El detalle del error interno no se propaga a la
279	 * UI ni se loguea con datos sensibles (RN-7).
280	 */
281	import * as SecureStore from 'expo-secure-store';
282	
283	/**
284	 * Clave del token en el almacén seguro. SecureStore admite `[A-Za-z0-9._-]`.
285	 *
286	 * Se guarda **sólo el token**: la restauración de sesión de RN-10 es optimista y no
287	 * inspecciona la expiración localmente (la detecta de forma reactiva ante el primer
288	 * `UNAUTHENTICATED`), así que persistir `expiresAt` no cambiaría ningún comportamiento y
289	 * sólo agrandaría la superficie de datos guardados.
290	 */
291	export const TOKEN_KEY = 'cex.mobile.session.token';
292	
293	/** Lee el token persistido. Nunca lanza: un fallo del almacén equivale a "no hay token". */
294	export async function readToken(): Promise<string | null> {
295	  try {
296	    const value = await SecureStore.getItemAsync(TOKEN_KEY);
297	    return typeof value === 'string' && value !== '' ? value : null;
298	  } catch {
299	    // RN-11: se trata como "sin token". No se registra el error (podría incluir la clave o
300	    // el valor del almacén según la plataforma) ni se muestra su detalle en la UI.
301	    return null;
302	  }
303	}
304	
305	/**
306	 * Persiste el token en el almacén cifrado.
307	 *
308	 * Devuelve `true` si quedó persistido. Si el almacén no está disponible, **no** hay
309	 * fallback a almacenamiento en claro (RN-2): la sesión sigue viva en memoria hasta que se
310	 * cierre la app, y la próxima apertura pedirá credenciales.
311	 */
312	export async function writeToken(token: string): Promise<boolean> {
313	  try {
314	    await SecureStore.setItemAsync(TOKEN_KEY, token);
315	    return true;
316	  } catch {
317	    return false;
318	  }
319	}
320	
321	/** Borra el token del almacén cifrado (RN-5 / RN-6). Nunca lanza. */
322	export async function deleteToken(): Promise<void> {
323	  try {
324	    await SecureStore.deleteItemAsync(TOKEN_KEY);
325	  } catch {
326	    /* si el almacén no está disponible no hay nada persistido que borrar */
327	  }
328	}

  1	/**
  2	 * Cliente HTTP de la API del exchange (contrato de la épica 09).
  3	 *
  4	 * - Ruta base `/api/v1` (HU-09-01 RN-1), configurable por entorno (`src/config.ts`).
  5	 * - Autenticación por header `Authorization: Bearer <token>` (HU-09-02 RN-1 / HU-11-01 RN-5).
  6	 *   El token viaja **sólo** en el header: nunca en la URL, ni en el cuerpo, ni en un log
  7	 *   (HU-11-01 RN-7).
  8	 * - Toda respuesta de error se traduce a `ApiError` con el `code` del catálogo; cualquier
  9	 *   otra falla (red, respuesta ilegible) a `NetworkError` (HU-11-01 RN-9).
 10	 */
 11	import { ApiError, NetworkError } from './errors';
 12	
 13	export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;
 14	
 15	export interface ApiClientOptions {
 16	  /** Prefijo de la API. */
 17	  baseUrl: string;
 18	  /** Implementación de `fetch` (inyectable para tests). */
 19	  fetchImpl?: FetchLike;
 20	  /** Token Bearer vigente, o `null` si no hay sesión. */
 21	  getToken?: () => string | null;
 22	  /**
 23	   * Se invoca cuando una llamada **protegida** responde `UNAUTHENTICATED` (401).
 24	   *
 25	   * Recibe el token con el que se hizo esa petición: permite que el manejo de sesión
 26	   * ignore un 401 tardío de una sesión ya reemplazada, y que el flujo de logout sea
 27	   * singleton (HU-11-01 RN-5, RG-8).
 28	   */
 29	  onUnauthenticated?: (tokenUsed: string | null) => void;
 30	}
 31	
 32	export interface RequestOptions {
 33	  method?: 'GET' | 'POST' | 'DELETE';
 34	  body?: unknown;
 35	  /** Adjunta el header `Authorization` si hay token. */
 36	  auth?: boolean;
 37	  /**
 38	   * Si es `false`, un `UNAUTHENTICATED` no dispara el manejo global de sesión. Lo usa el
 39	   * login, que es un endpoint **público**: un 401 ahí es credencial rechazada, no una
 40	   * sesión que expiró.
 41	   */
 42	  handleUnauthenticated?: boolean;
 43	  /** Query params ya en su forma final (se codifican acá). */
 44	  query?: Record<string, string>;
 45	}
 46	
 47	function joinUrl(baseUrl: string, path: string): string {
 48	  const base = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
 49	  const suffix = path.startsWith('/') ? path : `/${path}`;
 50	  return `${base}${suffix}`;
 51	}
 52	
 53	/** Extrae `{ code, details }` del envelope uniforme; `null` si el cuerpo no lo respeta. */
 54	function readErrorEnvelope(
 55	  payload: unknown,
 56	): { code: string; details?: Record<string, unknown> } | null {
 57	  if (typeof payload !== 'object' || payload === null) return null;
 58	  const error = (payload as Record<string, unknown>).error;
 59	  if (typeof error !== 'object' || error === null) return null;
 60	  const { code, details } = error as Record<string, unknown>;
 61	  if (typeof code !== 'string' || code === '') return null;
 62	  return {
 63	    code,
 64	    details:
 65	      typeof details === 'object' && details !== null && !Array.isArray(details)
 66	        ? (details as Record<string, unknown>)
 67	        : undefined,
 68	  };
 69	}
 70	
 71	export class ApiClient {
 72	  private readonly baseUrl: string;
 73	  private readonly fetchImpl: FetchLike;
 74	  private readonly getToken: () => string | null;
 75	  private readonly onUnauthenticated: ((tokenUsed: string | null) => void) | undefined;
 76	
 77	  constructor(options: ApiClientOptions) {
 78	    this.baseUrl = options.baseUrl;
 79	    this.fetchImpl =
 80	      options.fetchImpl ??
 81	      ((input, init) => {
 82	        if (typeof globalThis.fetch !== 'function') {
 83	          return Promise.reject(new NetworkError());
 84	        }
 85	        return globalThis.fetch(input, init);
 86	      });
 87	    this.getToken = options.getToken ?? (() => null);
 88	    this.onUnauthenticated = options.onUnauthenticated;
 89	  }
 90	
 91	  async request<T>(path: string, options: RequestOptions = {}): Promise<T> {
 92	    const { method = 'GET', body, auth = false, handleUnauthenticated = true, query } = options;
 93	    const headers: Record<string, string> = { accept: 'application/json' };
 94	    if (body !== undefined) headers['content-type'] = 'application/json';
 95	
 96	    let tokenUsed: string | null = null;
 97	    if (auth) {
 98	      tokenUsed = this.getToken();
 99	      if (tokenUsed) headers.authorization = `Bearer ${tokenUsed}`;
100	    }
101	
102	    let url = joinUrl(this.baseUrl, path);
103	    if (query) {
104	      const search = Object.entries(query)
105	        .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
106	        .join('&');
107	      if (search !== '') url += `?${search}`;
108	    }
109	
110	    let response: Response;
111	    try {
112	      response = await this.fetchImpl(url, {
113	        method,
114	        headers,
115	        ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
116	      });
117	    } catch {
118	      // Fallo de red: no se filtra el detalle del error subyacente (RN-9).
119	      throw new NetworkError();
120	    }
121	
122	    const raw = await response.text().catch(() => '');
123	    let payload: unknown = undefined;
124	    if (raw !== '') {
125	      try {
126	        payload = JSON.parse(raw);
127	      } catch {
128	        payload = undefined;
129	      }
130	    }
131	
132	    if (!response.ok) {
133	      const envelope = readErrorEnvelope(payload);
134	      // Una respuesta de error sin envelope del catálogo no es interpretable por `code`
135	      // (RG-3): se trata como falla de conexión.
136	      if (!envelope) throw new NetworkError();
137	      if (envelope.code === 'UNAUTHENTICATED' && handleUnauthenticated) {
138	        this.onUnauthenticated?.(tokenUsed);
139	      }
140	      throw new ApiError(envelope.code, response.status, envelope.details);
141	    }
142	
143	    return payload as T;
144	  }
145	}
146	/**
147	 * Catálogo de errores de la API y derivación de los mensajes que ve el usuario.
148	 *
149	 * Fuente de verdad: `spec/00-fundaciones/modelo-de-errores.md` y
150	 * `spec/09-api-http-websocket/HU-09-05-modelo-de-errores-api.md`.
151	 *
152	 * Regla central (épica 11 RG-3): **todo error se interpreta por su `code`** estable del
153	 * catálogo, nunca por el `message` del servidor. El `message` del envelope está orientado a
154	 * diagnóstico y su literal no es estable: no se muestra en la UI, para no acoplarse a él ni
155	 * filtrar detalle del error.
