216	/**
217	 * Error de dominio devuelto por la API: `{ error: { code, message, details } }`.
218	 *
219	 * Deliberadamente **no** conserva el `message` del servidor: la UI deriva su texto del
220	 * `code` (RG-3) y así ningún detalle del error del backend puede terminar en pantalla.
221	 */
222	export class ApiError extends Error {
223	  readonly code: ErrorCode | string;
224	  readonly httpStatus: number;
225	  readonly details: Record<string, unknown> | undefined;
226	
227	  constructor(code: ErrorCode | string, httpStatus: number, details?: Record<string, unknown>) {
228	    super(`ApiError(${code})`);
229	    this.name = 'ApiError';
230	    this.code = code;
231	    this.httpStatus = httpStatus;
232	    this.details = details;
233	  }
234	
235	  /** `details.issues` normalizado, o `[]` si el error no trae issues utilizables. */
236	  get issues(): ValidationIssue[] {
237	    const raw = this.details?.issues;
238	    if (!Array.isArray(raw)) return [];
239	    const issues: ValidationIssue[] = [];
240	    for (const item of raw) {
241	      if (typeof item === 'string') {
242	        issues.push({ field: '', message: item });
243	        continue;
244	      }
245	      if (typeof item !== 'object' || item === null) continue;
246	      const record = item as Record<string, unknown>;
247	      const field = record.field ?? record.path ?? record.name ?? '';
248	      const message = record.message ?? record.msg ?? '';
249	      issues.push({
250	        field: typeof field === 'string' ? field : String(field),
251	        message: typeof message === 'string' ? message : '',
252	      });
253	    }
254	    return issues;
255	  }
