257	  /**
258	   * `details.retryAfterSeconds` de `RATE_LIMITED`. Es un **conteo** y viaja como entero
259	   * JSON, no como string (modelo de errores §3.5, nota de tipos). Se tolera además un
260	   * string de dígitos por robustez. `null` si no hay un entero no negativo utilizable.
261	   */
262	  get retryAfterSeconds(): number | null {
263	    const raw = this.details?.retryAfterSeconds;
264	    if (typeof raw === 'number') {
265	      return Number.isInteger(raw) && raw >= 0 ? raw : null;
266	    }
267	    if (typeof raw === 'string' && /^(0|[1-9][0-9]*)$/.test(raw)) {
268	      const parsed = Number(raw);
269	      return Number.isSafeInteger(parsed) ? parsed : null;
270	    }
271	    return null;
272	  }
273	}
