 14	  ActivityIndicator,
 15	  KeyboardAvoidingView,
 16	  Platform,
 17	  Pressable,
 18	  ScrollView,
 19	  StyleSheet,
 20	  Text,
 21	  TextInput,
 22	  View,
 23	} from 'react-native';
 24	import { login } from '../api/auth';
 25	import {
 26	  ApiError,
 27	  CONNECTION_ERROR_MESSAGE,
 28	  INVALID_CREDENTIALS_MESSAGE,
 29	  messageForError,
 30	} from '../api/errors';
 31	import { useSession } from '../session/SessionProvider';
 32	import { colors, radius, spacing } from '../ui/theme';
 33	
 34	/**
 35	 * Validación de formato de email como **feedback temprano** (RN-8). No sustituye la
 36	 * autorización del backend ni habilita ningún bypass local: sólo evita un viaje de red
 37	 * cuando el dato es obviamente inválido.
 38	 */
 39	export function isEmailShaped(value: string): boolean {
 40	  const trimmed = value.trim();
 41	  if (trimmed === '' || /\s/.test(trimmed)) return false;
 42	  return /^[^@]+@[^@.]+(\.[^@.]+)+$/.test(trimmed);
 43	}
 44	
 45	export interface LocalValidation {
 46	  email: string | null;
 47	  password: string | null;
 48	}
 49	
 50	/** Errores de validación local del formulario (RN-8 / AT-11-01-07). */
 51	export function validateCredentials(email: string, password: string): LocalValidation {
 52	  const emailError =
 53	    email.trim() === ''
 54	      ? 'Ingresá tu email'
 55	      : isEmailShaped(email)
 56	        ? null
 57	        : 'El email no tiene un formato válido';
 58	  const passwordError = password === '' ? 'Ingresá tu contraseña' : null;
 59	  return { email: emailError, password: passwordError };
 60	}
 61	
 62	export function LoginScreen() {
 63	  const session = useSession();
 64	  const { api, signIn, notice, dismissNotice } = session;
 65	
 66	  const [email, setEmail] = useState('');
 67	  const [password, setPassword] = useState('');
 68	  const [submitting, setSubmitting] = useState(false);
 69	  const [localErrors, setLocalErrors] = useState<LocalValidation>({ email: null, password: null });
 70	  const [fieldErrors, setFieldErrors] = useState<LocalValidation>({ email: null, password: null });
 71	  const [formError, setFormError] = useState<string | null>(null);
 72	  const [retryAfterSeconds, setRetryAfterSeconds] = useState<number | null>(null);
 73	  // Evita un segundo request si el press llega antes de que React re-renderice con
 74	  // `submitting = true` (anti doble submit, paridad con HU-10-01 RN-2).
 75	  const inFlight = useRef(false);
 76	  const mounted = useRef(true);
 77	  useEffect(() => {
 78	    mounted.current = true;
 79	    return () => {
 80	      mounted.current = false;
 81	    };
 82	  }, []);
 83	
 84	  // RATE_LIMITED (429): se informa la espera de `details.retryAfterSeconds` y se rehabilita
 85	  // el botón al agotarse (paridad con HU-10-01 RN-6).
 86	  useEffect(() => {
 87	    if (retryAfterSeconds === null) return;
 88	    if (retryAfterSeconds <= 0) {
 89	      setRetryAfterSeconds(null);
 90	      setFormError(null);
 91	      return;
 92	    }
 93	    const timer = setTimeout(() => {
 94	      setRetryAfterSeconds((current) => (current === null ? null : current - 1));
 95	    }, 1000);
 96	    return () => clearTimeout(timer);
 97	  }, [retryAfterSeconds]);
 98	
 99	  const rateLimited = retryAfterSeconds !== null && retryAfterSeconds > 0;
100	  const disabled = submitting || rateLimited;
101	
102	  const clearErrors = useCallback(() => {
103	    setFormError(null);
104	    setFieldErrors({ email: null, password: null });
105	  }, []);
106	
107	  const onSubmit = useCallback(async () => {
108	    if (inFlight.current || disabled) return;
109	
110	    // RN-8 / AT-11-01-07: la validación local **bloquea el envío**; no se llama a la API
111	    // hasta corregir los campos.
112	    const validation = validateCredentials(email, password);
113	    setLocalErrors(validation);
114	    if (validation.email !== null || validation.password !== null) {
115	      setFormError(null);
116	      return;
117	    }
118	
119	    inFlight.current = true;
120	    setSubmitting(true);
121	    clearErrors();
122	    if (notice !== null) dismissNotice();
123	
124	    try {
125	      const response = await login(api, { email: email.trim(), password });
126	      // RN-2 / AT-11-01-01: el token se persiste en el almacén cifrado y recién ahí la app
127	      // pasa a la vista autenticada. La password no se guarda en ningún medio.
128	      await signIn(response.token);
129	      if (mounted.current) setPassword('');
130	    } catch (error) {
131	      if (!mounted.current) return;
132	      if (error instanceof ApiError) {
133	        if (error.code === 'INVALID_CREDENTIALS' || error.code === 'UNAUTHENTICATED') {
134	          // RN-3 / AT-11-01-04: mensaje genérico que no revela si el email existe. Sobre un
135	          // endpoint público, `UNAUTHENTICATED` sólo puede significar credencial rechazada:
136	          // avisar de "sesión expirada" a quien nunca tuvo sesión sería engañoso.
137	          setFormError(INVALID_CREDENTIALS_MESSAGE);
138	          setPassword('');
139	        } else if (error.code === 'VALIDATION_ERROR') {
140	          const issues = error.issues;
141	          const byField: LocalValidation = { email: null, password: null };
142	          for (const issue of issues) {
143	            const field = issue.field.toLowerCase();
144	            const text = issue.message.slice(0, 200);
145	            if (field.includes('email')) byField.email = text;
146	            else if (field.includes('password')) byField.password = text;
147	          }
148	          setFieldErrors(byField);
149	          setFormError(
150	            byField.email === null && byField.password === null ? messageForError(error) : null,
151	          );
152	        } else if (error.code === 'RATE_LIMITED') {
153	          const seconds = error.retryAfterSeconds;
154	          setFormError(
155	            seconds === null
156	              ? messageForError(error)
157	              : `Demasiados intentos. Esperá ${seconds} segundos antes de reintentar`,
158	          );
159	          if (seconds !== null && seconds > 0) setRetryAfterSeconds(seconds);
160	        } else {
161	          setFormError(messageForError(error));
162	        }
163	      } else {
164	        // RN-9 / AT-11-01-09: fallo de red, distinguible de `INVALID_CREDENTIALS`. No se
165	        // persiste token, se conserva el email y se puede reintentar.
166	        setFormError(CONNECTION_ERROR_MESSAGE);
167	      }
168	    } finally {
169	      inFlight.current = false;
170	      if (mounted.current) setSubmitting(false);
171	    }
172	  }, [api, clearErrors, disabled, dismissNotice, email, notice, password, signIn]);
173	
174	  const buttonLabel = useMemo(() => {
175	    if (submitting) return 'Ingresando…';
176	    if (rateLimited) return `Esperá ${retryAfterSeconds}s`;
177	    return 'Ingresar';
178	  }, [rateLimited, retryAfterSeconds, submitting]);
179	
180	  return (
181	    <KeyboardAvoidingView
182	      style={styles.flex}
183	      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
184	    >
185	      <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
186	        <Text style={styles.title}>Exchange</Text>
187	        <Text style={styles.subtitle}>Ingresá para operar</Text>
188	
189	        {notice !== null ? (
190	          <Text style={styles.notice} testID="login-notice">
191	            {notice}
192	          </Text>
193	        ) : null}
194	
195	        <Text style={styles.label} nativeID="login-email-label">
196	          Email
197	        </Text>
198	        <TextInput
199	          testID="login-email"
200	          accessibilityLabel="Email"
201	          accessibilityLabelledBy="login-email-label"
202	          style={styles.input}
203	          value={email}
204	          onChangeText={(value) => {
205	            setEmail(value);
206	            setLocalErrors((current) => ({ ...current, email: null }));
207	            setFieldErrors((current) => ({ ...current, email: null }));
208	          }}
209	          autoCapitalize="none"
210	          autoCorrect={false}
211	          autoComplete="email"
212	          keyboardType="email-address"
213	          inputMode="email"
214	          placeholder="tu@email.com"
215	          placeholderTextColor={colors.textMuted}
216	          editable={!disabled}
217	        />
218	        {localErrors.email !== null ? (
219	          <Text style={styles.fieldError} testID="login-email-error">
220	            {localErrors.email}
221	          </Text>
222	        ) : null}
223	        {fieldErrors.email !== null ? (
224	          <Text style={styles.fieldError} testID="login-email-issue">
225	            {fieldErrors.email}
226	          </Text>
227	        ) : null}
228	
229	        <Text style={styles.label} nativeID="login-password-label">
230	          Contraseña
231	        </Text>
232	        <TextInput
233	          testID="login-password"
234	          accessibilityLabel="Contraseña"
235	          accessibilityLabelledBy="login-password-label"
236	          style={styles.input}
237	          value={password}
238	          onChangeText={(value) => {
239	            setPassword(value);
240	            setLocalErrors((current) => ({ ...current, password: null }));
241	            setFieldErrors((current) => ({ ...current, password: null }));
242	          }}
243	          // La password nunca se muestra en claro ni se copia al portapapeles (RN-7).
244	          secureTextEntry
245	          autoCapitalize="none"
246	          autoCorrect={false}
247	          autoComplete="current-password"
248	          placeholder="••••••••"
249	          placeholderTextColor={colors.textMuted}
250	          editable={!disabled}
251	          onSubmitEditing={() => {
252	            void onSubmit();
253	          }}
254	        />
255	        {localErrors.password !== null ? (
256	          <Text style={styles.fieldError} testID="login-password-error">
257	            {localErrors.password}
258	          </Text>
259	        ) : null}
260	        {fieldErrors.password !== null ? (
261	          <Text style={styles.fieldError} testID="login-password-issue">
262	            {fieldErrors.password}
263	          </Text>
264	        ) : null}
265	
266	        {formError !== null ? (
267	          <Text style={styles.formError} testID="login-error">
268	            {formError}
269	          </Text>
270	        ) : null}
271	
272	        <Pressable
273	          testID="login-submit"
274	          accessibilityRole="button"
275	          accessibilityState={{ disabled, busy: submitting }}
276	          style={({ pressed }) => [
277	            styles.button,
278	            disabled && styles.buttonDisabled,
279	            pressed && !disabled && styles.buttonPressed,
280	          ]}
281	          disabled={disabled}
282	          onPress={() => {
283	            void onSubmit();
284	          }}
285	        >
286	          {submitting ? <ActivityIndicator color={colors.accentText} testID="login-spinner" /> : null}
287	          <Text style={styles.buttonText}>{buttonLabel}</Text>
288	        </Pressable>
289	      </ScrollView>
290	    </KeyboardAvoidingView>
291	  );
292	}
293	
294	const styles = StyleSheet.create({
295	  flex: { flex: 1, backgroundColor: colors.background },
296	  container: { padding: spacing.lg, paddingTop: spacing.xl * 2, gap: spacing.sm },
297	  title: { color: colors.text, fontSize: 30, fontWeight: '700' },
298	  subtitle: { color: colors.textMuted, fontSize: 15, marginBottom: spacing.lg },
299	  label: { color: colors.textMuted, fontSize: 13, marginTop: spacing.md },
300	  input: {
301	    backgroundColor: colors.surface,
302	    borderColor: colors.border,
303	    borderWidth: 1,
304	    borderRadius: radius.md,
305	    color: colors.text,
306	    paddingHorizontal: spacing.md,
307	    paddingVertical: spacing.sm + 4,
308	    fontSize: 16,
309	  },
310	  fieldError: { color: colors.danger, fontSize: 13 },
311	  formError: { color: colors.danger, fontSize: 14, marginTop: spacing.md },
312	  notice: {
313	    color: colors.text,
314	    backgroundColor: colors.surfaceAlt,
315	    borderRadius: radius.sm,
316	    padding: spacing.sm,
317	    fontSize: 14,
318	  },
319	  button: {
320	    marginTop: spacing.lg,
321	    backgroundColor: colors.accent,
322	    borderRadius: radius.md,
323	    paddingVertical: spacing.md,
324	    alignItems: 'center',
325	    justifyContent: 'center',
326	    flexDirection: 'row',
327	    gap: spacing.sm,
328	  },
329	  buttonPressed: { opacity: 0.85 },
330	  buttonDisabled: { backgroundColor: colors.disabled },
331	  buttonText: { color: colors.accentText, fontSize: 16, fontWeight: '600' },
332	});

