  1	/**
  2	 * Navegación del cliente mobile.
  3	 *
  4	 * El alcance de esta corrida son dos destinos —login y depósito—, así que la navegación se
  5	 * **deriva del estado de sesión** en vez de mantener un stack propio: `authenticated` ⇒
  6	 * vista autenticada, `anonymous` ⇒ login (HU-11-01 RN-4/RN-5/RN-6).
  7	 *
  8	 * Que el destino sea función del estado hace que la navegación al login sea **una sola** por
  9	 * cierre de sesión aunque lleguen varios `UNAUTHENTICATED` concurrentes (RG-8 /
 10	 * AT-11-01-14): el store colapsa los 401 en una única transición y el router en una única
 11	 * navegación. `onNavigate` expone cada cambio de destino para poder verificarlo.
 12	 */
 13	import { useEffect, useRef } from 'react';
 14	import { ActivityIndicator, StyleSheet, View } from 'react-native';
 15	import { useSession } from '../session/SessionProvider';
 16	import { DepositScreen } from '../screens/DepositScreen';
 17	import { LoginScreen } from '../screens/LoginScreen';
 18	import { colors } from '../ui/theme';
 19	
 20	export type RouteName = 'splash' | 'login' | 'deposit';
 21	
 22	export interface RouterProps {
 23	  /** Se invoca en cada cambio de destino (incluido el inicial). */
 24	  onNavigate?: (route: RouteName) => void;
 25	}
 26	
 27	export function routeForStatus(status: 'restoring' | 'anonymous' | 'authenticated'): RouteName {
 28	  if (status === 'restoring') return 'splash';
 29	  return status === 'authenticated' ? 'deposit' : 'login';
 30	}
 31	
 32	export function Router({ onNavigate }: RouterProps) {
 33	  const { status } = useSession();
 34	  const route = routeForStatus(status);
 35	  const previous = useRef<RouteName | null>(null);
 36	
 37	  useEffect(() => {
 38	    if (previous.current === route) return;
 39	    previous.current = route;
 40	    onNavigate?.(route);
 41	  }, [route, onNavigate]);
 42	
 43	  if (route === 'splash') {
 44	    // Restauración de sesión en curso (RN-4). Es una pantalla de espera, no un destino:
 45	    // no se llama a ningún endpoint autenticado hasta resolver si hay token (AT-11-01-03).
 46	    return (
 47	      <View style={styles.splash} testID="splash">
 48	        <ActivityIndicator color={colors.accent} />
 49	      </View>
 50	    );
 51	  }
 52	
 53	  return route === 'deposit' ? <DepositScreen /> : <LoginScreen />;
 54	}
 55	
 56	const styles = StyleSheet.create({
 57	  splash: {
 58	    flex: 1,
 59	    alignItems: 'center',
 60	    justifyContent: 'center',
 61	    backgroundColor: colors.background,
 62	  },
 63	});
 64	/**
 65	 * Raíz de la app mobile (épica 11).
 66	 *
 67	 * Alcance de esta corrida: `HU-11-01` (login y persistencia segura del token) y la pantalla
 68	 * de depósito de `HU-11-06` (dirección + QR). No hay más pantallas: el backend de las
 69	 * épicas 02–08 no está implementado.
 70	 */
 71	import { StatusBar } from 'expo-status-bar';
 72	import { StyleSheet } from 'react-native';
 73	import {
 74	  SafeAreaProvider,
 75	  SafeAreaView,
 76	  initialWindowMetrics,
 77	} from 'react-native-safe-area-context';
 78	import { Router, type RouteName } from './navigation/Router';
 79	import { SessionProvider, useSession, type SessionProviderProps } from './session/SessionProvider';
 80	import { PrivacyOverlay } from './ui/PrivacyOverlay';
 81	import type { AppStateLike } from './ui/appState';
 82	import { colors } from './ui/theme';
 83	
 84	export interface AppProps extends Omit<SessionProviderProps, 'children'> {
 85	  /** Observador de navegación (tests). */
 86	  onNavigate?: (route: RouteName) => void;
 87	}
 88	
 89	interface ShellProps {
 90	  onNavigate?: (route: RouteName) => void;
 91	  appState?: AppStateLike;
 92	}
 93	
 94	function Shell({ onNavigate, appState }: ShellProps) {
 95	  const { status } = useSession();
 96	  return (
 97	    // RG-9: el overlay de privacidad sólo tapa pantallas **autenticadas**; en el login no
 98	    // hay datos de cuenta que proteger del screenshot del app switcher.
 99	    <PrivacyOverlay
100	      enabled={status === 'authenticated'}
101	      {...(appState !== undefined ? { appState } : {})}
102	    >
103	      <SafeAreaView style={styles.safe} edges={['top', 'bottom']}>
104	        <StatusBar style="light" />
105	        <Router {...(onNavigate !== undefined ? { onNavigate } : {})} />
106	      </SafeAreaView>
107	    </PrivacyOverlay>
108	  );
109	}
110	
111	export function App(props: AppProps = {}) {
112	  const { onNavigate, ...sessionProps } = props;
113	  const { appState } = props;
114	  return (
115	    // `initialWindowMetrics` evita el primer frame en blanco mientras el proveedor mide.
116	    <SafeAreaProvider initialMetrics={initialWindowMetrics}>
117	      <SessionProvider {...sessionProps}>
118	        <Shell
119	          {...(onNavigate !== undefined ? { onNavigate } : {})}
120	          {...(appState !== undefined ? { appState } : {})}
121	        />
122	      </SessionProvider>
123	    </SafeAreaProvider>
124	  );
125	}
126	
127	const styles = StyleSheet.create({
128	  safe: { flex: 1, backgroundColor: colors.background },
129	});
130	/**
131	 * Configuración del cliente mobile.
132	 *
133	 * Todo lo configurable llega por variables de entorno `EXPO_PUBLIC_*`, que Expo inyecta en
134	 * el bundle en tiempo de build (leídas de `mobile/.env`). No hay secretos acá: el cliente
135	 * mobile es un consumidor de la API (épica 11, RG-1) y **nunca** maneja seed, mnemonic ni
136	 * claves privadas (HU-11-06 RN-12).
137	 */
138	
139	/** Red única del proyecto (spec/00-fundaciones/activos-y-par-de-trading.md §1). */
140	export const CHAIN_ID = '11155111';
141	export const NETWORK_NAME = 'sepolia';
142	export const NETWORK_LABEL = 'Sepolia';
143	
144	/** Confirmaciones requeridas para acreditar un depósito (HU-11-06 RN-3). Informativo acá. */
145	export const CONFIRMACIONES_REQUERIDAS = 12;
146	
147	/**
148	 * Normaliza un valor de entorno: `undefined` si está ausente o vacío.
149	 *
150	 * Las variables `EXPO_PUBLIC_*` las **inlinea el bundler** reemplazando textualmente la
151	 * expresión `process.env.EXPO_PUBLIC_ALGO`: por eso cada una se lee con su nombre escrito
152	 * completo y no por índice dinámico (un `process.env[nombre]` no se reemplazaría y quedaría
153	 * `undefined` en el dispositivo).
154	 */
155	function clean(value: string | undefined): string | undefined {
156	  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
157	}
158	
159	/**
160	 * Prefijo de la API REST (épica 09: "todos los recursos cuelgan de `/api/v1`").
161	 *
162	 * En un dispositivo o emulador `localhost` es el propio teléfono, no la máquina que corre
163	 * el backend: en ese caso hay que apuntar `EXPO_PUBLIC_API_BASE_URL` a la IP de LAN de la
164	 * máquina (ver README).
165	 */
166	export const API_BASE_URL =
167	  clean(process.env.EXPO_PUBLIC_API_BASE_URL) ?? 'http://localhost:3000/api/v1';
168	
169	/**
170	 * URL del WebSocket (RG-API-11: `ws(s)://<host>/api/v1/ws`, misma base que el REST).
171	 *
172	 * Vacía por defecto **a propósito**: el backend de esta corrida no implementa los canales
173	 * WebSocket (HU-09-03 / HU-09-04), así que la app no intenta conectarse. El canal privado
174	 * existe como módulo (`src/ws/privateChannel.ts`) porque HU-11-01 RN-12 / AT-11-01-12 son
175	 * parte del alcance, y se verifica con un WebSocket falso (README de la épica 11, RG-11).
176	 */
177	export const WS_URL = clean(process.env.EXPO_PUBLIC_WS_URL) ?? '';
178	
179	/** Deriva la URL del WebSocket a partir del prefijo REST, si no se configuró explícitamente. */
180	export function defaultWsUrlFrom(apiBaseUrl: string): string {
181	  try {
182	    const url = new URL(apiBaseUrl);
183	    url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
184	    url.pathname = `${url.pathname.replace(/\/$/, '')}/ws`;
185	    url.search = '';
186	    url.hash = '';
187	    return url.toString();
188	  } catch {
189	    return '';
190	  }
191	}
192	/**
193	 * Acceso al ciclo de vida de la app (`AppState` de React Native), inyectable.
194	 *
195	 * Lo consumen el overlay de privacidad (RG-9) y la suspensión/reanudación del canal
196	 * WebSocket privado (RG-5). Se abstrae para poder dirigir el ciclo de vida desde los tests
197	 * sin depender del SO (RG-11).
198	 */
199	import { AppState, type AppStateStatus } from 'react-native';
200	
201	export type { AppStateStatus };
202	
203	export interface AppStateSubscriptionLike {
204	  remove(): void;
205	}
206	
207	export interface AppStateLike {
208	  currentState: AppStateStatus | null;
209	  addEventListener(
210	    type: 'change',
211	    handler: (state: AppStateStatus) => void,
212	  ): AppStateSubscriptionLike;
213	}
214	
215	/** `AppState` de React Native, o el doble inyectado. */
216	export function resolveAppState(injected?: AppStateLike): AppStateLike {
217	  return injected ?? (AppState as unknown as AppStateLike);
218	}
219	
220	/**
221	 * Estado actual normalizado. `AppState.currentState` puede ser `null` (todavía sin
222	 * determinar) o, en entornos de test sin módulo nativo, un valor que no es un estado
223	 * válido: en ambos casos se asume `active`, que es el estado que **no** oculta nada.
224	 */
225	export function currentAppState(appState: AppStateLike): AppStateStatus {
226	  const value = appState.currentState;
227	  return value === 'active' || value === 'inactive' || value === 'background'
228	    ? value
229	    : 'active';
230	}
231	/**
232	 * Overlay de privacidad en background (épica 11, RG-9).
233	 *
234	 * Al recibir `AppState = inactive`/`background` se superpone una capa **opaca** sobre toda
235	 * la pantalla **antes** de que el SO capture el screenshot para el app switcher, para no
236	 * exponer datos de la cuenta (dirección de depósito, balances, historial). Al volver a
237	 * `active` se retira.
238	 *
239	 * Aplica a las pantallas **autenticadas** y no interfiere con el ciclo de vida de las
240	 * suscripciones WebSocket (RG-5), que vive en `SessionProvider`.
241	 */
242	import { useEffect, useState, type ReactNode } from 'react';
243	import { StyleSheet, Text, View } from 'react-native';
244	import { currentAppState, resolveAppState, type AppStateLike, type AppStateStatus } from './appState';
245	import { colors, spacing } from './theme';
246	
247	export interface PrivacyOverlayProps {
248	  children: ReactNode;
249	  /** Si es `false` no se tapa nada (pantallas no autenticadas: no hay datos que proteger). */
250	  enabled?: boolean;
251	  /** Fuente del ciclo de vida; por defecto el `AppState` de React Native (tests: doble). */
252	  appState?: AppStateLike;
253	}
254	
