214	          >
215	            <Text style={styles.secondaryButtonText}>Reintentar</Text>
216	          </Pressable>
217	        </View>
218	      ) : null}
219	
220	      {!loading && data !== null ? (
221	        <View style={styles.card}>
222	          {qrValue !== null ? (
223	            <View style={styles.qrFrame} testID="deposit-qr-frame">
224	              <QRCode value={qrValue} size={200} backgroundColor="#ffffff" color="#000000" />
225	            </View>
226	          ) : (
227	            <Text style={styles.warning} testID="deposit-qr-unavailable">
228	              {qrUnavailable}
229	            </Text>
230	          )}
231	
232	          <Text style={styles.cardLabel}>Tu dirección de depósito</Text>
233	          <Text style={styles.address} testID="deposit-address" selectable>
234	            {data.address}
235	          </Text>
236	          {!isValidChecksumAddress(data.address) ? (
237	            <Text style={styles.warning} testID="deposit-address-checksum-warning">
238	              La dirección devuelta por la API no verifica el checksum EIP-55.
239	            </Text>
240	          ) : null}
241	
242	          <Pressable
243	            testID="deposit-copy"
244	            accessibilityRole="button"
245	            style={styles.primaryButton}
246	            onPress={() => {
247	              void onCopy();
248	            }}
249	          >
250	            <Text style={styles.primaryButtonText}>
251	              {copied ? 'Dirección copiada' : 'Copiar dirección'}
252	            </Text>
253	          </Pressable>
254	
255	          <Text style={styles.note} testID="deposit-note">
256	            Una única dirección recibe ETH y USDC-mock en {NETWORK_LABEL}: lo que distingue al
257	            activo es el tipo de transacción on-chain, no la dirección. Enviá fondos sólo por
258	            la red {NETWORK_LABEL} (chainId {CHAIN_ID}).
259	          </Text>
260	        </View>
261	      ) : null}
262	    </ScrollView>
263	  );
264	}
