  1	/**
  2	 * Pantalla de depósito mobile (HU-11-06, Escenarios 1 y 26 — AT-11-06-01 / AT-11-06-26).
  3	 *
  4	 * Muestra la dirección de depósito de la cuenta con su **QR** y la acción de **copiar**,
  5	 * aclarando la red (**Sepolia**, `chainId = 11155111`) y el activo.
  6	 *
  7	 * Alcance de esta corrida: **sólo** la presentación de la dirección. El seguimiento de
  8	 * depósitos (RN-3) y los retiros quedan fuera porque su backend (épicas 07 y 08) no está
  9	 * implementado.
 10	 *
 11	 * Reglas aplicadas:
 12	 *  - RN-1: la dirección **viene de la API** (`GET /api/v1/deposit-address?asset=`); el
 13	 *    cliente no la deriva ni accede a la seed.
 14	 *  - RN-2: address en texto con checksum EIP-55 **siempre**, QR en formato EIP-681, y una
 15	 *    **única** dirección recibe ETH y USDC-mock.
 16	 *  - RN-11: ante `UNAUTHENTICATED` se limpia la sesión y se vuelve al login (lo hace el
 17	 *    `ApiClient` vía `SessionStore`, flujo singleton RG-8).
 18	 *  - RN-12: nunca se muestra ni se pide mnemonic, seed ni claves privadas.
 19	 */
 20	import { useCallback, useEffect, useState } from 'react';
 21	import {
 22	  ActivityIndicator,
 23	  Pressable,
 24	  RefreshControl,
 25	  ScrollView,
 26	  StyleSheet,
 27	  Text,
 28	  View,
 29	} from 'react-native';
 30	import * as Clipboard from 'expo-clipboard';
 31	import QRCode from 'react-native-qrcode-svg';
 32	import { getProfile, type Profile } from '../api/auth';
 33	import { getDepositAddress, type DepositAddress } from '../api/deposits';
 34	import { ApiError, messageForError } from '../api/errors';
 35	import { isValidChecksumAddress } from '../chain/address';
 36	import { buildDepositUri, MissingTokenAddressError, type DepositAsset } from '../chain/eip681';
 37	import { CHAIN_ID, NETWORK_LABEL } from '../config';
 38	import { useSession } from '../session/SessionProvider';
 39	import { colors, radius, spacing } from '../ui/theme';
 40	
 41	const ASSETS: readonly DepositAsset[] = ['ETH', 'USDC'];
 42	
 43	const ASSET_LABEL: Record<DepositAsset, string> = {
 44	  ETH: 'ETH (nativo)',
 45	  USDC: 'USDC-mock (ERC-20)',
 46	};
 47	
 48	export function DepositScreen() {
 49	  const { api, signOut } = useSession();
 50	  const [asset, setAsset] = useState<DepositAsset>('ETH');
 51	  const [data, setData] = useState<DepositAddress | null>(null);
 52	  const [profile, setProfile] = useState<Profile | null>(null);
 53	  const [loading, setLoading] = useState(true);
 54	  const [refreshing, setRefreshing] = useState(false);
 55	  const [error, setError] = useState<string | null>(null);
 56	  const [copied, setCopied] = useState(false);
 57	
 58	  const load = useCallback(
 59	    async (target: DepositAsset) => {
 60	      setError(null);
 61	      try {
 62	        const response = await getDepositAddress(api, target);
 63	        setData(response);
 64	      } catch (err) {
 65	        setData(null);
 66	        // Un `UNAUTHENTICATED` ya disparó el cierre de sesión en el `ApiClient` (RN-11 /
 67	        // RG-8): la app está navegando al login, así que no se muestra ningún error acá.
 68	        const expirada = err instanceof ApiError && err.code === 'UNAUTHENTICATED';
 69	        setError(expirada ? null : messageForError(err));
 70	      }
 71	    },
 72	    [api],
 73	  );
 74	
 75	  useEffect(() => {
 76	    let cancelled = false;
 77	    setLoading(true);
 78	    void load(asset).finally(() => {
 79	      if (!cancelled) setLoading(false);
 80	    });
 81	    return () => {
 82	      cancelled = true;
 83	    };
 84	  }, [asset, load]);
 85	
 86	  // El email de la cuenta identifica la sesión abierta. Es la primera petición autenticada
 87	  // del arranque en frío junto con la dirección: si el token restaurado estaba expirado,
 88	  // acá se detecta de forma reactiva (RN-10 de HU-11-01).
 89	  useEffect(() => {
 90	    let cancelled = false;
 91	    getProfile(api).then(
 92	      (loaded) => {
 93	        if (!cancelled) setProfile(loaded);
 94	      },
 95	      () => {
 96	        /* el perfil es informativo: su fallo no bloquea la pantalla de depósito */
 97	      },
 98	    );
 99	    return () => {
100	      cancelled = true;
101	    };
102	  }, [api]);
103	
104	  const onRefresh = useCallback(() => {
105	    setRefreshing(true);
106	    void load(asset).finally(() => setRefreshing(false));
107	  }, [asset, load]);
108	
109	  const onCopy = useCallback(async () => {
110	    if (data === null) return;
111	    await Clipboard.setStringAsync(data.address);
112	    setCopied(true);
113	  }, [data]);
114	
115	  useEffect(() => {
116	    if (!copied) return;
117	    const timer = setTimeout(() => setCopied(false), 2500);
118	    return () => clearTimeout(timer);
119	  }, [copied]);
120	
121	  // RN-2: el QR es un URI EIP-681. Si faltara el `tokenAddress` de USDC no se inventa uno:
122	  // se degrada a mostrar sólo el address en texto, que es el respaldo que RN-2 exige.
123	  let qrValue: string | null = null;
124	  let qrUnavailable: string | null = null;
125	  if (data !== null) {
126	    try {
127	      qrValue = buildDepositUri({
128	        asset,
129	        depositAddress: data.address,
130	        ...(data.tokenAddress !== undefined ? { tokenAddress: data.tokenAddress } : {}),
131	      });
132	    } catch (err) {
133	      qrValue = null;
134	      qrUnavailable =
135	        err instanceof MissingTokenAddressError
136	          ? 'No se pudo generar el QR: la API no devolvió la dirección del contrato USDC-mock. Usá la dirección en texto.'
137	          : 'No se pudo generar el QR para esta dirección. Usá la dirección en texto.';
138	    }
139	  }
140	
141	  return (
142	    <ScrollView
143	      style={styles.flex}
144	      contentContainerStyle={styles.container}
145	      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={colors.textMuted} />}
146	    >
147	      <View style={styles.header}>
148	        <View style={styles.headerText}>
149	          <Text style={styles.title}>Depositar</Text>
150	          {profile !== null ? (
151	            <Text style={styles.subtitle} testID="session-email">
152	              {profile.email}
153	            </Text>
154	          ) : null}
155	        </View>
156	        <Pressable
157	          testID="logout"
158	          accessibilityRole="button"
159	          onPress={() => {
160	            void signOut();
161	          }}
162	          style={styles.logout}
163	        >
164	          <Text style={styles.logoutText}>Cerrar sesión</Text>
165	        </Pressable>
166	      </View>
167	
168	      <View style={styles.assetRow}>
169	        {ASSETS.map((candidate) => {
170	          const active = candidate === asset;
171	          return (
172	            <Pressable
173	              key={candidate}
174	              testID={`deposit-asset-${candidate}`}
175	              accessibilityRole="button"
176	              accessibilityState={{ selected: active }}
177	              style={[styles.assetButton, active && styles.assetButtonActive]}
178	              onPress={() => setAsset(candidate)}
179	            >
180	              <Text style={[styles.assetText, active && styles.assetTextActive]}>{candidate}</Text>
181	            </Pressable>
182	          );
183	        })}
184	      </View>
185	
186	      <View style={styles.networkBanner}>
187	        <Text style={styles.networkText} testID="deposit-network">
188	          Red: {NETWORK_LABEL} (chainId {CHAIN_ID})
189	        </Text>
190	        <Text style={styles.networkSub} testID="deposit-asset-label">
191	          Activo: {ASSET_LABEL[asset]}
192	        </Text>
193	      </View>
194	
195	      {loading ? (
196	        <View style={styles.center}>
197	          <ActivityIndicator color={colors.accent} testID="deposit-loading" />
198	        </View>
199	      ) : null}
200	
201	      {!loading && error !== null ? (
202	        <View style={styles.card}>
203	          <Text style={styles.error} testID="deposit-error">
204	            {error}
205	          </Text>
206	          <Pressable
207	            testID="deposit-retry"
208	            accessibilityRole="button"
209	            style={styles.secondaryButton}
210	            onPress={() => {
211	              setLoading(true);
212	              void load(asset).finally(() => setLoading(false));
213	            }}
214	          >
215	            <Text style={styles.secondaryButtonText}>Reintentar</Text>
216	          </Pressable>
217	        </View>
218	      ) : null}
219	
220	      {!loading && data !== null ? (
221	        <View style={styles.card}>
222	          {qrValue !== null ? (
223	            <View style={styles.qrFrame} testID="deposit-qr-frame">
224	              <QRCode value={qrValue} size={200} backgroundColor="#ffffff" color="#000000" />
225	            </View>
226	          ) : (
227	            <Text style={styles.warning} testID="deposit-qr-unavailable">
228	              {qrUnavailable}
229	            </Text>
230	          )}
231	
232	          <Text style={styles.cardLabel}>Tu dirección de depósito</Text>
233	          <Text style={styles.address} testID="deposit-address" selectable>
234	            {data.address}
235	          </Text>
236	          {!isValidChecksumAddress(data.address) ? (
237	            <Text style={styles.warning} testID="deposit-address-checksum-warning">
238	              La dirección devuelta por la API no verifica el checksum EIP-55.
239	            </Text>
240	          ) : null}
241	
242	          <Pressable
243	            testID="deposit-copy"
244	            accessibilityRole="button"
245	            style={styles.primaryButton}
246	            onPress={() => {
247	              void onCopy();
248	            }}
249	          >
250	            <Text style={styles.primaryButtonText}>
251	              {copied ? 'Dirección copiada' : 'Copiar dirección'}
252	            </Text>
253	          </Pressable>
254	
255	          <Text style={styles.note} testID="deposit-note">
256	            Una única dirección recibe ETH y USDC-mock en {NETWORK_LABEL}: lo que distingue al
257	            activo es el tipo de transacción on-chain, no la dirección. Enviá fondos sólo por
258	            la red {NETWORK_LABEL} (chainId {CHAIN_ID}).
259	          </Text>
260	        </View>
261	      ) : null}
262	    </ScrollView>
263	  );
264	}
265	
