270	  headerText: { flex: 1 },
271	  title: { color: colors.text, fontSize: 26, fontWeight: '700' },
272	  subtitle: { color: colors.textMuted, fontSize: 13 },
273	  logout: {
274	    borderColor: colors.border,
275	    borderWidth: 1,
276	    borderRadius: radius.sm,
277	    paddingHorizontal: spacing.sm,
278	    paddingVertical: spacing.xs + 2,
279	  },
280	  logoutText: { color: colors.textMuted, fontSize: 13 },
281	  assetRow: { flexDirection: 'row', gap: spacing.sm },
282	  assetButton: {
283	    flex: 1,
284	    alignItems: 'center',
285	    paddingVertical: spacing.sm + 2,
286	    borderRadius: radius.md,
287	    borderWidth: 1,
288	    borderColor: colors.border,
289	    backgroundColor: colors.surface,
290	  },
291	  assetButtonActive: { backgroundColor: colors.accent, borderColor: colors.accent },
292	  assetText: { color: colors.textMuted, fontSize: 15, fontWeight: '600' },
293	  assetTextActive: { color: colors.accentText },
294	  networkBanner: {
