300	  networkSub: { color: colors.textMuted, fontSize: 13, marginTop: 2 },
301	  center: { paddingVertical: spacing.xl, alignItems: 'center' },
302	  card: {
303	    backgroundColor: colors.surface,
304	    borderRadius: radius.lg,
305	    borderWidth: 1,
306	    borderColor: colors.border,
307	    padding: spacing.md,
308	    gap: spacing.sm,
309	    alignItems: 'center',
310	  },
311	  qrFrame: {
312	    backgroundColor: '#ffffff',
313	    padding: spacing.md,
314	    borderRadius: radius.md,
315	  },
316	  cardLabel: { color: colors.textMuted, fontSize: 13, marginTop: spacing.sm },
