  1	/**
  2	 * Cliente del **canal WebSocket privado** del usuario (HU-09-04) con el ciclo de vida y la
  3	 * reconexión que exige el cliente mobile (épica 11: RG-5, RG-10, RG-11; HU-11-01 RN-12).
  4	 *
  5	 * Decisiones que fija la spec y que este módulo implementa al pie de la letra:
  6	 *
  7	 * - **Handshake (HU-09-04 RN-1):** apenas abre el socket, el **primer** mensaje es
  8	 *   `{"type":"auth","token":"<token>"}`. El token **nunca** viaja en la URL/query (RN-1 lo
  9	 *   prohíbe explícitamente para no exponerlo en logs) ni se loggea (HU-11-01 RN-7 /
 10	 *   AT-11-01-11): en este archivo no hay una sola llamada a `console.*`.
 11	 * - **Suscripción (HU-09-04 RN-2):** tras `{"type":"authenticated"}` se envía un
 12	 *   `{"type":"subscribe","channel":...}` por cada canal configurado.
 13	 * - **`UNAUTHENTICATED` (HU-11-01 RN-12 / AT-11-01-12):** llegue en el handshake o en un
 14	 *   mensaje del canal ya autenticado, se avisa **una sola vez por intento** vía
 15	 *   `onUnauthenticated(tokenUsed)`, se cierra el socket y **no** se reintenta: el servidor ya
 16	 *   rechazó ese token, así que reintentar sería un bucle. El manejo de sesión (logout
 17	 *   singleton, RG-8) vive fuera de este módulo; acá sólo se notifica con el token usado para
 18	 *   que un 401 tardío de una sesión ya reemplazada pueda descartarse.
 19	 * - **Backoff (RG-10):** 1 s inicial, factor 2×, tope 30 s, jitter ±500 ms, reintentos
 20	 *   indefinidos mientras la pantalla esté en foreground. El contador se resetea tras una
 21	 *   conexión exitosa (`authenticated`).
 22	 * - **Ciclo de vida (RG-5):** en `background`/`inactive` se cierra el socket y se cancelan los
 23	 *   timers (estado `suspended`); al volver a `active` se reconecta de inmediato, y como la
 24	 *   reconexión implica un nuevo `auth` + nuevos `subscribe`, el servidor manda un **snapshot
 25	 *   fresco** antes de los deltas (RG-API-7), o sea que la re-sincronización es la propia
 26	 *   re-suscripción.
 27	 * - **Testabilidad (RG-11):** el WebSocket, los timers y la fuente del jitter son
 28	 *   inyectables, de modo que los tests no dependen del tiempo real ni de un socket real.
 29	 *
 30	 * El módulo es autónomo: no importa React ni `react-native`. El ciclo de vida entra por
 31	 * `handleAppStateChange`, que la capa de UI alimenta con el `AppState` de React Native.
 32	 */
 33	
 34	export type ConnectionStatus = 'idle' | 'connecting' | 'live' | 'reconnecting' | 'suspended';
 35	
 36	/** Parámetros de reconexión del contrato de evaluación (RG-10). */
 37	export const BACKOFF_INITIAL_MS = 1000;
 38	export const BACKOFF_FACTOR = 2;
 39	export const BACKOFF_MAX_MS = 30000;
 40	export const BACKOFF_JITTER_MS = 500;
 41	
 42	/** Canales privados del contrato (HU-09-04 RN-2). */
 43	export type PrivateChannelName = 'orders' | 'balances' | 'withdrawals';
 44	
 45	/** Evento de mensaje mínimo que consumimos del socket. */
 46	export interface WebSocketMessageEventLike {
 47	  data: unknown;
 48	}
 49	
 50	/** Instancia mínima de socket que necesita este cliente. */
 51	export interface WebSocketInstanceLike {
 52	  send(data: string): void;
 53	  close(code?: number, reason?: string): void;
 54	  onopen: ((event?: unknown) => void) | null;
 55	  onmessage: ((event: WebSocketMessageEventLike) => void) | null;
 56	  onerror: ((event?: unknown) => void) | null;
 57	  onclose: ((event?: unknown) => void) | null;
 58	}
 59	
 60	/**
 61	 * Constructor de WebSocket (el global del runtime, o un doble en los tests — RG-11).
 62	 * Recibe **sólo** la url: el token va en el primer mensaje, nunca en la url (HU-09-04 RN-1).
 63	 */
 64	export type WebSocketLike = new (url: string) => WebSocketInstanceLike;
 65	
 66	export interface PrivateChannelOptions {
 67	  /** URL del WS (`ws://host/api/v1/ws`, RG-API-11). */
 68	  url: string;
 69	  /** Token vigente del almacenamiento seguro; `null` si no hay sesión. */
 70	  getToken: () => string | null;
 71	  /**
 72	   * Se invoca cuando el canal recibe `UNAUTHENTICATED` (handshake o mensaje del canal).
 73	   * Recibe el token con el que se autenticó ese intento, para que el manejo de sesión
 74	   * pueda ignorar un 401 tardío de una sesión ya reemplazada (RN-12 + RG-8).
 75	   */
 76	  onUnauthenticated: (tokenUsed: string | null) => void;
 77	  /** Canales privados a los que suscribirse al autenticar. */
 78	  channels?: PrivateChannelName[];
 79	  /** Mensajes ya parseados del servidor (snapshot/deltas). */
 80	  onMessage?: (message: unknown) => void;
 81	  onStatusChange?: (status: ConnectionStatus) => void;
 82	  /** Inyectables para tests (RG-11). */
 83	  webSocketImpl?: WebSocketLike;
 84	  setTimeoutImpl?: typeof setTimeout;
 85	  clearTimeoutImpl?: typeof clearTimeout;
 86	  random?: () => number;
 87	}
 88	
 89	type TimerHandle = ReturnType<typeof setTimeout>;
 90	
 91	/** Lee `error.code` del envelope uniforme de la épica 09 (RG-3); `null` si no lo respeta. */
 92	function readErrorCode(message: unknown): string | null {
 93	  if (typeof message !== 'object' || message === null) return null;
 94	  const error = (message as Record<string, unknown>).error;
 95	  if (typeof error !== 'object' || error === null) return null;
 96	  const code = (error as Record<string, unknown>).code;
 97	  return typeof code === 'string' && code !== '' ? code : null;
 98	}
 99	
100	/** Lee `type` de un mensaje del protocolo WS; `null` si no lo trae. */
101	function readMessageType(message: unknown): string | null {
102	  if (typeof message !== 'object' || message === null) return null;
103	  const type = (message as Record<string, unknown>).type;
104	  return typeof type === 'string' && type !== '' ? type : null;
105	}
106	
107	export class PrivateChannel {
108	  private readonly url: string;
109	  private readonly getToken: () => string | null;
110	  private readonly onUnauthenticated: (tokenUsed: string | null) => void;
111	  private readonly channels: PrivateChannelName[];
112	  private readonly onMessage: ((message: unknown) => void) | undefined;
113	  private readonly onStatusChange: ((status: ConnectionStatus) => void) | undefined;
114	  private readonly webSocketImpl: WebSocketLike | undefined;
115	  private readonly setTimeoutImpl: typeof setTimeout;
116	  private readonly clearTimeoutImpl: typeof clearTimeout;
117	  private readonly random: () => number;
118	
119	  private socket: WebSocketInstanceLike | null = null;
120	  private retryTimer: TimerHandle | null = null;
121	  private currentStatus: ConnectionStatus = 'idle';
122	  /** Cantidad de reintentos ya agendados desde la última conexión exitosa (RG-10). */
123	  private retryCount = 0;
124	  /** `start()` pedido y todavía no revertido por `stop()`. */
125	  private started = false;
126	  /** La app está en background/inactive: no se reintenta hasta volver a foreground (RG-5). */
127	  private suspended = false;
128	  /** El servidor rechazó el token: la sesión terminó, no se reintenta (RN-12). */
129	  private sessionEnded = false;
130	  /** Token del intento en curso, para reportarlo con el `UNAUTHENTICATED`. */
131	  private tokenUsed: string | null = null;
132	  /** Evita notificar dos veces el mismo `UNAUTHENTICATED` (p. ej. mensaje + cierre). */
133	  private unauthenticatedNotified = false;
134	
135	  constructor(options: PrivateChannelOptions) {
136	    this.url = options.url;
137	    this.getToken = options.getToken;
138	    this.onUnauthenticated = options.onUnauthenticated;
139	    this.channels = options.channels ?? [];
140	    this.onMessage = options.onMessage;
141	    this.onStatusChange = options.onStatusChange;
142	    this.webSocketImpl = options.webSocketImpl;
143	    this.setTimeoutImpl = options.setTimeoutImpl ?? setTimeout;
144	    this.clearTimeoutImpl = options.clearTimeoutImpl ?? clearTimeout;
145	    this.random = options.random ?? Math.random;
146	  }
147	
148	  get status(): ConnectionStatus {
149	    return this.currentStatus;
150	  }
151	
152	  /** Conecta (o reconecta). Idempotente: llamarlo dos veces no abre dos sockets. */
153	  start(): void {
154	    // Un `start()` explícito es intención fresca del usuario (típicamente tras un login
155	    // nuevo): limpia el "sesión terminada" y el backoff acumulado.
156	    this.started = true;
157	    this.suspended = false;
158	    this.sessionEnded = false;
159	    if (this.socket !== null || this.retryTimer !== null) return;
160	    this.retryCount = 0;
161	    this.connect();
162	  }
163	
164	  /** Cierra el socket y cancela reintentos pendientes. */
165	  stop(): void {
166	    this.started = false;
167	    this.suspended = false;
168	    this.cancelRetry();
169	    this.closeSocket();
170	    this.retryCount = 0;
171	    this.setStatus('idle');
172	  }
173	
174	  /** Ciclo de vida (RG-5): background suspende, foreground reconecta y re-sincroniza. */
175	  handleAppStateChange(state: 'active' | 'inactive' | 'background'): void {
176	    if (state === 'background' || state === 'inactive') {
177	      if (this.suspended) return;
178	      this.suspended = true;
179	      // Suspender **no** es un fallo de autenticación: se cancelan timers y se cierra el
180	      // socket sin tocar `onUnauthenticated` (RG-5, AT-11-01-10).
181	      this.cancelRetry();
182	      this.closeSocket();
183	      if (this.started) this.setStatus('suspended');
184	      return;
185	    }
186	    if (!this.suspended) return;
187	    this.suspended = false;
188	    if (!this.started || this.sessionEnded) return;
189	    // Foreground: se reconecta **de inmediato** (delay 0) y el nuevo handshake + los nuevos
190	    // `subscribe` traen un snapshot fresco antes de los deltas (RG-5 + RG-API-7).
191	    this.cancelRetry();
192	    this.retryCount = 0;
193	    this.connect();
194	  }
195	
196	  /**
197	   * Delay del próximo reintento (RG-10): `1000 · 2^n` topeado en 30000, más jitter uniforme
198	   * en ±500 ms, nunca negativo. Consume una muestra de `random`, igual que el agendado real.
199	   */
200	  nextDelayMs(): number {
201	    const base = Math.min(
202	      BACKOFF_INITIAL_MS * Math.pow(BACKOFF_FACTOR, this.retryCount),
203	      BACKOFF_MAX_MS,
204	    );
205	    const jitter = (this.random() * 2 - 1) * BACKOFF_JITTER_MS;
206	    return Math.max(0, base + jitter);
207	  }
208	
209	  // --- internos -------------------------------------------------------------------------
210	
211	  private connect(): void {
212	    const token = this.getToken();
213	    // Sin sesión no hay canal privado que abrir (HU-09-04 RN-1: exige token).
214	    if (token === null || token === '') {
215	      this.setStatus('idle');
216	      return;
217	    }
218	    const WebSocketImpl = this.webSocketImpl ?? (globalThis as { WebSocket?: WebSocketLike }).WebSocket;
219	    if (WebSocketImpl === undefined) {
220	      this.setStatus('idle');
221	      return;
222	    }
223	
224	    this.tokenUsed = token;
225	    this.unauthenticatedNotified = false;
226	    this.setStatus('connecting');
227	
228	    // La url no lleva el token en ningún parámetro (HU-09-04 RN-1).
229	    const socket = new WebSocketImpl(this.url);
230	    this.socket = socket;
231	
232	    socket.onopen = (): void => {
233	      if (this.socket !== socket) return;
234	      // Primer mensaje del handshake, antes de cualquier `subscribe` (HU-09-04 RN-1).
235	      this.send(socket, { type: 'auth', token });
236	    };
237	    socket.onmessage = (event: WebSocketMessageEventLike): void => {
238	      if (this.socket !== socket) return;
239	      this.handleMessage(socket, event);
240	    };
241	    socket.onerror = (): void => {
242	      this.handleDisconnect(socket);
243	    };
244	    socket.onclose = (): void => {
245	      this.handleDisconnect(socket);
246	    };
247	  }
248	
249	  private handleMessage(socket: WebSocketInstanceLike, event: WebSocketMessageEventLike): void {
250	    const parsed = this.parse(event.data);
251	    if (parsed === undefined) return;
252	
253	    // `UNAUTHENTICATED` en cualquier momento (handshake o canal ya autenticado):
254	    // HU-11-01 RN-12 / AT-11-01-12.
255	    if (readErrorCode(parsed) === 'UNAUTHENTICATED') {
256	      this.handleUnauthenticated(socket);
257	      return;
258	    }
259	
260	    const type = readMessageType(parsed);
261	    if (type === 'authenticated') {
262	      // Conexión exitosa: se resetea el backoff a 1 s (RG-10) y se suscriben los canales.
263	      this.retryCount = 0;
264	      this.setStatus('live');
265	      for (const channel of this.channels) {
266	        this.send(socket, { type: 'subscribe', channel });
267	      }
268	      return;
269	    }
270	
271	    // El resto (snapshots, deltas, `subscribed`, errores no-401) va a la capa de datos.
272	    this.onMessage?.(parsed);
273	  }
274	
275	  private handleUnauthenticated(socket: WebSocketInstanceLike): void {
276	    if (this.socket !== socket) return;
277	    if (this.unauthenticatedNotified) return;
278	    this.unauthenticatedNotified = true;
279	    const tokenUsed = this.tokenUsed;
280	
281	    // La sesión terminó: se cierra el socket y **no** hay reintento (reintentar con un token
282	    // que el servidor ya rechazó sería un bucle). El logout singleton lo resuelve el
283	    // consumidor (RG-8).
284	    this.sessionEnded = true;
285	    this.cancelRetry();
286	    this.closeSocket();
287	    this.setStatus('idle');
288	    this.onUnauthenticated(tokenUsed);
289	  }
290	
291	  /** Error o cierre inesperado del socket ⇒ reconexión con backoff (RG-10). */
292	  private handleDisconnect(socket: WebSocketInstanceLike): void {
293	    if (this.socket !== socket) return;
294	    this.detach(socket);
295	    this.socket = null;
296	
297	    if (this.sessionEnded || !this.started || this.suspended) return;
298	
299	    this.scheduleRetry();
300	  }
301	
302	  private scheduleRetry(): void {
303	    if (this.retryTimer !== null) return;
304	    const delay = this.nextDelayMs();
305	    // Reintentos indefinidos con el delay topeado mientras haya foreground (RG-10).
306	    this.retryCount += 1;
307	    this.setStatus('reconnecting');
308	    this.retryTimer = this.setTimeoutImpl(() => {
309	      this.retryTimer = null;
310	      if (this.sessionEnded || !this.started || this.suspended) return;
311	      this.connect();
312	    }, delay);
313	  }
314	
315	  private cancelRetry(): void {
316	    if (this.retryTimer === null) return;
317	    this.clearTimeoutImpl(this.retryTimer);
318	    this.retryTimer = null;
319	  }
320	
321	  /** Cierra el socket vigente sin disparar la reconexión (se desenganchan los handlers). */
322	  private closeSocket(): void {
323	    const socket = this.socket;
324	    if (socket === null) return;
325	    this.socket = null;
326	    this.detach(socket);
327	    try {
328	      socket.close();
329	    } catch {
330	      // Un socket ya cerrado no es un error del cliente; nada que reportar.
331	    }
332	  }
333	
334	  private detach(socket: WebSocketInstanceLike): void {
335	    socket.onopen = null;
336	    socket.onmessage = null;
337	    socket.onerror = null;
338	    socket.onclose = null;
339	  }
340	
341	  private send(socket: WebSocketInstanceLike, payload: unknown): void {
342	    try {
343	      socket.send(JSON.stringify(payload));
344	    } catch {
345	      // Si el socket se cerró justo antes del envío, el `onclose` dispara la reconexión.
346	      // No se loggea el payload: puede contener el token (HU-11-01 RN-7).
347	    }
348	  }
349	
350	  private parse(data: unknown): unknown {
351	    if (typeof data === 'string') {
352	      try {
353	        return JSON.parse(data);
354	      } catch {
355	        // Mensaje no-JSON: se descarta (el contrato es JSON de texto, HU-09-04).
356	        return undefined;
357	      }
358	    }
359	    if (typeof data === 'object' && data !== null) return data;
360	    return undefined;
361	  }
362	
363	  private setStatus(status: ConnectionStatus): void {
364	    if (this.currentStatus === status) return;
365	    this.currentStatus = status;
366	    this.onStatusChange?.(status);
367	  }
368	}

  1	/**
  2	 * Estado de sesión del cliente mobile (HU-11-01).
  3	 *
  4	 * Se implementa como un store observable sin dependencias de React: la lógica de RN-4,
  5	 * RN-5, RN-6, RN-10 y RN-11 —incluida la garantía de **logout singleton** de RG-8— se
  6	 * puede ejercitar y verificar sin montar la UI.
  7	 *
  8	 * Máquina de estados:
  9	 *
 10	 *   restoring ──(hay token en el almacén cifrado)──► authenticated
 11	 *       │                                                 │
 12	 *       └─(no hay token, o el almacén falla — RN-11)──┐    │ UNAUTHENTICATED (RN-5)
 13	 *                                                     ▼    │ logout del usuario (RN-6)
 14	 *                                                  anonymous ◄─┘
 15	 *
 16	 * La restauración es **optimista** (RN-10): si hay token se entra directo a la vista
 17	 * autenticada, **sin** llamada de validación previa. La expiración se detecta de forma
 18	 * reactiva, cuando la primera petición autenticada (REST o handshake WebSocket) recibe
 19	 * `UNAUTHENTICATED`.
 20	 */
 21	import { SESSION_EXPIRED_MESSAGE } from '../api/errors';
 22	import { deleteToken, readToken, writeToken } from './secureStorage';
 23	
 24	export type SessionStatus = 'restoring' | 'anonymous' | 'authenticated';
 25	
 26	export interface SessionState {
 27	  status: SessionStatus;
 28	  /** Token en memoria. Nunca se renderiza ni se loguea (RN-7). */
 29	  token: string | null;
 30	  /** Aviso a mostrar en la pantalla de login (p. ej. sesión expirada, RN-5). */
 31	  notice: string | null;
 32	}
 33	
 34	type Listener = () => void;
 35	
 36	export class SessionStore {
 37	  private state: SessionState = { status: 'restoring', token: null, notice: null };
 38	  private readonly listeners = new Set<Listener>();
 39	  /**
 40	   * Flujo de logout en curso (RG-8). Mientras haya uno, las activaciones adicionales son
 41	   * **no-ops** y devuelven la misma promesa: un único borrado del token, una única
 42	   * limpieza de estado y una única transición a `anonymous` (y por lo tanto una única
 43	   * navegación al login).
 44	   */
 45	  private logoutInFlight: Promise<void> | null = null;
 46	
 47	  getState(): SessionState {
 48	    return this.state;
 49	  }
 50	
 51	  subscribe(listener: Listener): () => void {
 52	    this.listeners.add(listener);
 53	    return () => {
 54	      this.listeners.delete(listener);
 55	    };
 56	  }
 57	
 58	  private setState(next: Partial<SessionState>): void {
 59	    this.state = { ...this.state, ...next };
 60	    for (const listener of this.listeners) listener();
 61	  }
 62	
 63	  /** Token vigente, para el header `Authorization` y el handshake del WebSocket (RN-5/RN-12). */
 64	  getToken = (): string | null => this.state.token;
 65	
 66	  /**
 67	   * Restauración de sesión al abrir la app (RN-4 + RN-10). Nunca lanza: un fallo del
 68	   * almacén seguro se trata como "sin token" y termina en la pantalla de login (RN-11).
 69	   */
 70	  async restore(): Promise<void> {
 71	    const token = await readToken();
 72	    if (token === null) {
 73	      // AT-11-01-03 / AT-11-01-13: sin token (o con el almacén inaccesible) se muestra el
 74	      // login y **no** se llama a ningún endpoint autenticado.
 75	      this.setState({ status: 'anonymous', token: null });
 76	      return;
 77	    }
 78	    // AT-11-01-02: se entra directo a la vista autenticada, sin validar contra el backend.
 79	    this.setState({ status: 'authenticated', token, notice: null });
 80	  }
 81	
 82	  /**
 83	   * Establece la sesión tras un login exitoso (RN-2 / AT-11-01-01).
 84	   *
 85	   * Persiste **primero** en el almacén cifrado y recién después expone la sesión, para que
 86	   * no exista un estado observable "autenticado pero sin persistir".
 87	   */
 88	  async signIn(token: string): Promise<void> {
 89	    await writeToken(token);
 90	    // Una sesión nueva deja atrás cualquier logout previo: el guard de RG-8 protege un
 91	    // único flujo de cierre, no impide volver a cerrar la sesión siguiente.
 92	    this.logoutInFlight = null;
 93	    this.setState({ status: 'authenticated', token, notice: null });
 94	  }
 95	
 96	  /** Logout explícito del usuario (RN-6). */
 97	  async signOut(): Promise<void> {
 98	    await this.runLogout(null);
 99	  }
100	
101	  /**
102	   * `UNAUTHENTICATED` (401) recibido en una petición autenticada o en el canal privado
103	   * (RN-5 / RN-12): borra el token persistido, limpia el estado y vuelve al login.
104	   *
105	   * Es **singleton** (RG-8 / AT-11-01-14): varios 401 concurrentes producen un único
106	   * borrado y una única navegación.
107	   *
108	   * @param tokenUsed token con el que se hizo la petición que recibió el 401. Un 401 de
109	   * una sesión ya reemplazada (login nuevo mientras la petición vieja viajaba) se ignora.
110	   */
111	  handleUnauthenticated(tokenUsed: string | null = null): Promise<void> {
112	    if (this.logoutInFlight) return this.logoutInFlight;
113	    if (this.state.status !== 'authenticated') return Promise.resolve();
114	    if (tokenUsed !== null && tokenUsed !== this.state.token) return Promise.resolve();
115	    return this.runLogout(SESSION_EXPIRED_MESSAGE);
116	  }
117	
118	  private runLogout(notice: string | null): Promise<void> {
119	    if (this.logoutInFlight) return this.logoutInFlight;
120	    // La limpieza de memoria y la transición a `anonymous` son **síncronas**: cualquier
121	    // otro 401 que llegue mientras el borrado del almacén está en vuelo ya encuentra la
122	    // sesión cerrada, además del guard de `logoutInFlight`.
123	    this.setState({ status: 'anonymous', token: null, notice });
124	    const pending: Promise<void> = deleteToken().finally(() => {
125	      // Sólo se libera el guard si sigue siendo *este* logout el vigente: un `signIn`
126	      // posterior ya lo habrá reemplazado.
127	      if (this.logoutInFlight === pending) this.logoutInFlight = null;
128	    });
129	    this.logoutInFlight = pending;
130	    return pending;
131	  }
132	
133	  /** Descarta el aviso pendiente (se consume al mostrarlo en el login). */
134	  dismissNotice(): void {
135	    if (this.state.notice !== null) this.setState({ notice: null });
136	  }
137	}
138	/**
139	 * Persistencia del token de sesión en el almacenamiento **cifrado** del sistema operativo
140	 * (Keychain en iOS / Keystore en Android) vía Expo SecureStore.
141	 *
142	 * HU-11-01 RN-2: el token se persiste **únicamente** acá. Está **prohibido** guardarlo en
143	 * almacenamiento no cifrado en claro (p. ej. `AsyncStorage`) o en logs; por eso este módulo
144	 * es el **único** punto del cliente que escribe el token, y no importa ningún otro almacén.
145	 *
146	 * HU-11-01 RN-11: si la lectura falla (p. ej. *Keychain item inaccessible* en estado
147	 * *Before First Unlock* tras un reinicio, o el almacén no disponible), el caso se trata
148	 * **como si no hubiera token persistido**. El detalle del error interno no se propaga a la
149	 * UI ni se loguea con datos sensibles (RN-7).
150	 */
151	import * as SecureStore from 'expo-secure-store';
152	
153	/**
154	 * Clave del token en el almacén seguro. SecureStore admite `[A-Za-z0-9._-]`.
155	 *
156	 * Se guarda **sólo el token**: la restauración de sesión de RN-10 es optimista y no
157	 * inspecciona la expiración localmente (la detecta de forma reactiva ante el primer
158	 * `UNAUTHENTICATED`), así que persistir `expiresAt` no cambiaría ningún comportamiento y
159	 * sólo agrandaría la superficie de datos guardados.
160	 */
161	export const TOKEN_KEY = 'cex.mobile.session.token';
162	
163	/** Lee el token persistido. Nunca lanza: un fallo del almacén equivale a "no hay token". */
164	export async function readToken(): Promise<string | null> {
165	  try {
166	    const value = await SecureStore.getItemAsync(TOKEN_KEY);
167	    return typeof value === 'string' && value !== '' ? value : null;
168	  } catch {
169	    // RN-11: se trata como "sin token". No se registra el error (podría incluir la clave o
170	    // el valor del almacén según la plataforma) ni se muestra su detalle en la UI.
171	    return null;
172	  }
173	}
174	
175	/**
176	 * Persiste el token en el almacén cifrado.
177	 *
