309	  const value = useMemo<SessionContextValue>(
310	    () => ({
311	      ...state,
312	      api,
313	      store,
314	      signIn: (token: string) => store.signIn(token),
315	      signOut: () => store.signOut(),
316	      dismissNotice: () => store.dismissNotice(),
317	    }),
