330	 * Navegación del cliente mobile.
331	 *
332	 * El alcance de esta corrida son dos destinos —login y depósito—, así que la navegación se
333	 * **deriva del estado de sesión** en vez de mantener un stack propio: `authenticated` ⇒
334	 * vista autenticada, `anonymous` ⇒ login (HU-11-01 RN-4/RN-5/RN-6).
335	 *
336	 * Que el destino sea función del estado hace que la navegación al login sea **una sola** por
337	 * cierre de sesión aunque lleguen varios `UNAUTHENTICATED` concurrentes (RG-8 /
338	 * AT-11-01-14): el store colapsa los 401 en una única transición y el router en una única
339	 * navegación. `onNavigate` expone cada cambio de destino para poder verificarlo.
340	 */
341	import { useEffect, useRef } from 'react';
342	import { ActivityIndicator, StyleSheet, View } from 'react-native';
343	import { useSession } from '../session/SessionProvider';
344	import { DepositScreen } from '../screens/DepositScreen';
345	import { LoginScreen } from '../screens/LoginScreen';
346	import { colors } from '../ui/theme';
347	
348	export type RouteName = 'splash' | 'login' | 'deposit';
349	
350	export interface RouterProps {
351	  /** Se invoca en cada cambio de destino (incluido el inicial). */
352	  onNavigate?: (route: RouteName) => void;
353	}
354	
355	export function routeForStatus(status: 'restoring' | 'anonymous' | 'authenticated'): RouteName {
356	  if (status === 'restoring') return 'splash';
357	  return status === 'authenticated' ? 'deposit' : 'login';
358	}
359	
360	export function Router({ onNavigate }: RouterProps) {
361	  const { status } = useSession();
362	  const route = routeForStatus(status);
363	  const previous = useRef<RouteName | null>(null);
364	
365	  useEffect(() => {
366	    if (previous.current === route) return;
367	    previous.current = route;
