393	 * Raíz de la app mobile (épica 11).
394	 *
395	 * Alcance de esta corrida: `HU-11-01` (login y persistencia segura del token) y la pantalla
396	 * de depósito de `HU-11-06` (dirección + QR). No hay más pantallas: el backend de las
397	 * épicas 02–08 no está implementado.
398	 */
399	import { StatusBar } from 'expo-status-bar';
400	import { StyleSheet } from 'react-native';
401	import {
402	  SafeAreaProvider,
403	  SafeAreaView,
404	  initialWindowMetrics,
405	} from 'react-native-safe-area-context';
406	import { Router, type RouteName } from './navigation/Router';
407	import { SessionProvider, useSession, type SessionProviderProps } from './session/SessionProvider';
408	import { PrivacyOverlay } from './ui/PrivacyOverlay';
409	import type { AppStateLike } from './ui/appState';
410	import { colors } from './ui/theme';
411	
412	export interface AppProps extends Omit<SessionProviderProps, 'children'> {
413	  /** Observador de navegación (tests). */
414	  onNavigate?: (route: RouteName) => void;
415	}
416	
417	interface ShellProps {
418	  onNavigate?: (route: RouteName) => void;
419	  appState?: AppStateLike;
420	}
