470	import { StyleSheet, Text, View } from 'react-native';
471	import { currentAppState, resolveAppState, type AppStateLike, type AppStateStatus } from './appState';
472	import { colors, spacing } from './theme';
473	
474	export interface PrivacyOverlayProps {
475	  children: ReactNode;
476	  /** Si es `false` no se tapa nada (pantallas no autenticadas: no hay datos que proteger). */
477	  enabled?: boolean;
478	  /** Fuente del ciclo de vida; por defecto el `AppState` de React Native (tests: doble). */
479	  appState?: AppStateLike;
480	}
481	
482	export function PrivacyOverlay({ children, enabled = true, appState }: PrivacyOverlayProps) {
483	  const source = resolveAppState(appState);
484	  const [state, setState] = useState<AppStateStatus>(() => currentAppState(source));
