486	  useEffect(() => {
487	    const subscription = source.addEventListener('change', setState);
488	    return () => subscription.remove();
489	  }, [source]);
490	
491	  const hidden = enabled && state !== 'active';
492	
493	  return (
494	    <View style={styles.container}>
495	      {children}
496	      {hidden ? (
497	        <View style={styles.overlay} testID="privacy-overlay">
498	          <Text style={styles.label}>Contenido protegido</Text>
499	        </View>
500	      ) : null}
501	    </View>
502	  );
503	}
504	
505	const styles = StyleSheet.create({
506	  container: { flex: 1 },
507	  overlay: {
508	    position: 'absolute',
509	    top: 0,
510	    left: 0,
511	    right: 0,
512	    bottom: 0,
513	    // Opaco (sin transparencia): el screenshot del app switcher no debe dejar ver nada.
514	    backgroundColor: colors.background,
515	    alignItems: 'center',
516	    justifyContent: 'center',
517	    padding: spacing.lg,
518	  },
519	  label: { color: colors.textMuted, fontSize: 16 },
520	});
521	/**
522	 * Acceso al ciclo de vida de la app (`AppState` de React Native), inyectable.
523	 *
524	 * Lo consumen el overlay de privacidad (RG-9) y la suspensión/reanudación del canal
