529	
530	export type { AppStateStatus };
531	
532	export interface AppStateSubscriptionLike {
533	  remove(): void;
534	}
535	
536	export interface AppStateLike {
537	  currentState: AppStateStatus | null;
538	  addEventListener(
539	    type: 'change',
540	    handler: (state: AppStateStatus) => void,
541	  ): AppStateSubscriptionLike;
542	}
543	
544	/** `AppState` de React Native, o el doble inyectado. */
545	export function resolveAppState(injected?: AppStateLike): AppStateLike {
546	  return injected ?? (AppState as unknown as AppStateLike);
547	}
