199	/**
200	 * Enlace de React con `SessionStore` (HU-11-01).
201	 *
202	 * Provee el estado de sesión, el `ApiClient` ya configurado con el token vigente y el
203	 * manejo de `UNAUTHENTICATED` (RN-5), y el canal WebSocket privado cuando hay una URL
204	 * configurada (RN-12).
205	 */
206	import {
207	  createContext,
208	  useContext,
209	  useEffect,
210	  useMemo,
211	  useRef,
212	  useSyncExternalStore,
213	  type ReactNode,
214	} from 'react';
215	import { ApiClient, type FetchLike } from '../api/client';
216	import { API_BASE_URL, WS_URL } from '../config';
217	import { resolveAppState, type AppStateLike } from '../ui/appState';
218	import { PrivateChannel } from '../ws/privateChannel';
219	import { SessionStore, type SessionState } from './sessionStore';
220	
221	export interface SessionContextValue extends SessionState {
222	  api: ApiClient;
223	  store: SessionStore;
224	  signIn(token: string): Promise<void>;
225	  signOut(): Promise<void>;
226	  dismissNotice(): void;
227	}
228	
229	const SessionContext = createContext<SessionContextValue | null>(null);
230	
231	export interface SessionProviderProps {
232	  children: ReactNode;
233	  /** Sobrescribe el prefijo de la API (tests / configuración explícita). */
234	  baseUrl?: string;
235	  /** Sobrescribe la implementación de `fetch` (tests). */
236	  fetchImpl?: FetchLike;
237	  /** Store inyectable (tests); por defecto se crea uno nuevo. */
238	  store?: SessionStore;
239	  /** URL del canal privado; vacía = no se conecta (ver `src/config.ts`). */
240	  wsUrl?: string;
241	  /** Fuente del ciclo de vida; por defecto el `AppState` de React Native (tests: doble). */
242	  appState?: AppStateLike;
243	}
244	
245	export function SessionProvider({
246	  children,
247	  baseUrl,
248	  fetchImpl,
249	  store: injectedStore,
250	  wsUrl,
251	  appState,
252	}: SessionProviderProps) {
253	  const storeRef = useRef<SessionStore | null>(injectedStore ?? null);
254	  if (storeRef.current === null) storeRef.current = new SessionStore();
255	  const store = storeRef.current;
256	
257	  const state = useSyncExternalStore(
258	    (listener) => store.subscribe(listener),
259	    () => store.getState(),
260	    () => store.getState(),
261	  );
262	
263	  const api = useMemo(
264	    () =>
265	      new ApiClient({
266	        baseUrl: baseUrl ?? API_BASE_URL,
267	        ...(fetchImpl !== undefined ? { fetchImpl } : {}),
268	        getToken: store.getToken,
269	        // RN-5 / RG-8: el manejo es singleton dentro del store.
270	        onUnauthenticated: (tokenUsed) => {
271	          void store.handleUnauthenticated(tokenUsed);
272	        },
273	      }),
274	    [baseUrl, fetchImpl, store],
275	  );
276	
277	  // RN-4: restauración de sesión al abrir la app. Corre una sola vez por montaje.
278	  useEffect(() => {
279	    void store.restore();
280	  }, [store]);
281	
282	  // RN-12 + RG-5: canal privado con el mismo token del almacén seguro; se suspende en
283	  // background y se reconecta (con snapshot fresco) al volver a foreground. Sólo se activa
284	  // si hay una URL de WebSocket configurada: el backend de esta corrida no expone los
285	  // canales de la épica 09 (HU-09-03/HU-09-04).
286	  const resolvedWsUrl = wsUrl ?? WS_URL;
287	  useEffect(() => {
288	    if (resolvedWsUrl === '' || state.status !== 'authenticated') return;
289	    const channel = new PrivateChannel({
290	      url: resolvedWsUrl,
291	      getToken: store.getToken,
292	      onUnauthenticated: (tokenUsed) => {
293	        void store.handleUnauthenticated(tokenUsed);
294	      },
295	      channels: ['balances'],
296	    });
297	    channel.start();
298	    const subscription = resolveAppState(appState).addEventListener('change', (next) => {
299	      if (next === 'active' || next === 'inactive' || next === 'background') {
300	        channel.handleAppStateChange(next);
301	      }
302	    });
303	    return () => {
304	      subscription.remove();
305	      channel.stop();
306	    };
307	  }, [appState, resolvedWsUrl, state.status, store]);
308	
309	  const value = useMemo<SessionContextValue>(
310	    () => ({
311	      ...state,
312	      api,
313	      store,
314	      signIn: (token: string) => store.signIn(token),
315	      signOut: () => store.signOut(),
316	      dismissNotice: () => store.dismissNotice(),
317	    }),
318	    [state, api, store],
319	  );
320	
321	  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
322	}
323	
324	export function useSession(): SessionContextValue {
325	  const value = useContext(SessionContext);
326	  if (!value) throw new Error('useSession requiere un <SessionProvider> ancestro');
327	  return value;
328	}
329	/**
330	 * Navegación del cliente mobile.
331	 *
332	 * El alcance de esta corrida son dos destinos —login y depósito—, así que la navegación se
333	 * **deriva del estado de sesión** en vez de mantener un stack propio: `authenticated` ⇒
334	 * vista autenticada, `anonymous` ⇒ login (HU-11-01 RN-4/RN-5/RN-6).
335	 *
336	 * Que el destino sea función del estado hace que la navegación al login sea **una sola** por
337	 * cierre de sesión aunque lleguen varios `UNAUTHENTICATED` concurrentes (RG-8 /
338	 * AT-11-01-14): el store colapsa los 401 en una única transición y el router en una única
339	 * navegación. `onNavigate` expone cada cambio de destino para poder verificarlo.
340	 */
341	import { useEffect, useRef } from 'react';
342	import { ActivityIndicator, StyleSheet, View } from 'react-native';
343	import { useSession } from '../session/SessionProvider';
344	import { DepositScreen } from '../screens/DepositScreen';
345	import { LoginScreen } from '../screens/LoginScreen';
346	import { colors } from '../ui/theme';
347	
348	export type RouteName = 'splash' | 'login' | 'deposit';
349	
350	export interface RouterProps {
351	  /** Se invoca en cada cambio de destino (incluido el inicial). */
352	  onNavigate?: (route: RouteName) => void;
353	}
354	
355	export function routeForStatus(status: 'restoring' | 'anonymous' | 'authenticated'): RouteName {
356	  if (status === 'restoring') return 'splash';
357	  return status === 'authenticated' ? 'deposit' : 'login';
358	}
359	
360	export function Router({ onNavigate }: RouterProps) {
361	  const { status } = useSession();
362	  const route = routeForStatus(status);
363	  const previous = useRef<RouteName | null>(null);
364	
365	  useEffect(() => {
366	    if (previous.current === route) return;
367	    previous.current = route;
368	    onNavigate?.(route);
369	  }, [route, onNavigate]);
370	
371	  if (route === 'splash') {
372	    // Restauración de sesión en curso (RN-4). Es una pantalla de espera, no un destino:
373	    // no se llama a ningún endpoint autenticado hasta resolver si hay token (AT-11-01-03).
374	    return (
375	      <View style={styles.splash} testID="splash">
376	        <ActivityIndicator color={colors.accent} />
377	      </View>
378	    );
379	  }
380	
381	  return route === 'deposit' ? <DepositScreen /> : <LoginScreen />;
382	}
383	
384	const styles = StyleSheet.create({
385	  splash: {
386	    flex: 1,
387	    alignItems: 'center',
388	    justifyContent: 'center',
389	    backgroundColor: colors.background,
390	  },
391	});
392	/**
393	 * Raíz de la app mobile (épica 11).
394	 *
395	 * Alcance de esta corrida: `HU-11-01` (login y persistencia segura del token) y la pantalla
396	 * de depósito de `HU-11-06` (dirección + QR). No hay más pantallas: el backend de las
397	 * épicas 02–08 no está implementado.
398	 */
399	import { StatusBar } from 'expo-status-bar';
400	import { StyleSheet } from 'react-native';
401	import {
402	  SafeAreaProvider,
403	  SafeAreaView,
404	  initialWindowMetrics,
405	} from 'react-native-safe-area-context';
406	import { Router, type RouteName } from './navigation/Router';
407	import { SessionProvider, useSession, type SessionProviderProps } from './session/SessionProvider';
408	import { PrivacyOverlay } from './ui/PrivacyOverlay';
409	import type { AppStateLike } from './ui/appState';
410	import { colors } from './ui/theme';
411	
412	export interface AppProps extends Omit<SessionProviderProps, 'children'> {
413	  /** Observador de navegación (tests). */
414	  onNavigate?: (route: RouteName) => void;
415	}
416	
417	interface ShellProps {
418	  onNavigate?: (route: RouteName) => void;
419	  appState?: AppStateLike;
420	}
421	
422	function Shell({ onNavigate, appState }: ShellProps) {
423	  const { status } = useSession();
424	  return (
425	    // RG-9: el overlay de privacidad sólo tapa pantallas **autenticadas**; en el login no
426	    // hay datos de cuenta que proteger del screenshot del app switcher.
427	    <PrivacyOverlay
428	      enabled={status === 'authenticated'}
429	      {...(appState !== undefined ? { appState } : {})}
430	    >
431	      <SafeAreaView style={styles.safe} edges={['top', 'bottom']}>
432	        <StatusBar style="light" />
433	        <Router {...(onNavigate !== undefined ? { onNavigate } : {})} />
434	      </SafeAreaView>
435	    </PrivacyOverlay>
436	  );
437	}
438	
439	export function App(props: AppProps = {}) {
440	  const { onNavigate, ...sessionProps } = props;
441	  const { appState } = props;
442	  return (
443	    // `initialWindowMetrics` evita el primer frame en blanco mientras el proveedor mide.
444	    <SafeAreaProvider initialMetrics={initialWindowMetrics}>
445	      <SessionProvider {...sessionProps}>
446	        <Shell
447	          {...(onNavigate !== undefined ? { onNavigate } : {})}
448	          {...(appState !== undefined ? { appState } : {})}
449	        />
450	      </SessionProvider>
451	    </SafeAreaProvider>
452	  );
453	}
454	
455	const styles = StyleSheet.create({
456	  safe: { flex: 1, backgroundColor: colors.background },
457	});
458	/**
459	 * Overlay de privacidad en background (épica 11, RG-9).
460	 *
461	 * Al recibir `AppState = inactive`/`background` se superpone una capa **opaca** sobre toda
462	 * la pantalla **antes** de que el SO capture el screenshot para el app switcher, para no
463	 * exponer datos de la cuenta (dirección de depósito, balances, historial). Al volver a
464	 * `active` se retira.
465	 *
466	 * Aplica a las pantallas **autenticadas** y no interfiere con el ciclo de vida de las
467	 * suscripciones WebSocket (RG-5), que vive en `SessionProvider`.
468	 */
469	import { useEffect, useState, type ReactNode } from 'react';
470	import { StyleSheet, Text, View } from 'react-native';
471	import { currentAppState, resolveAppState, type AppStateLike, type AppStateStatus } from './appState';
472	import { colors, spacing } from './theme';
473	
474	export interface PrivacyOverlayProps {
475	  children: ReactNode;
476	  /** Si es `false` no se tapa nada (pantallas no autenticadas: no hay datos que proteger). */
477	  enabled?: boolean;
478	  /** Fuente del ciclo de vida; por defecto el `AppState` de React Native (tests: doble). */
479	  appState?: AppStateLike;
480	}
481	
482	export function PrivacyOverlay({ children, enabled = true, appState }: PrivacyOverlayProps) {
483	  const source = resolveAppState(appState);
484	  const [state, setState] = useState<AppStateStatus>(() => currentAppState(source));
485	
486	  useEffect(() => {
487	    const subscription = source.addEventListener('change', setState);
488	    return () => subscription.remove();
489	  }, [source]);
490	
491	  const hidden = enabled && state !== 'active';
492	
493	  return (
494	    <View style={styles.container}>
495	      {children}
496	      {hidden ? (
497	        <View style={styles.overlay} testID="privacy-overlay">
498	          <Text style={styles.label}>Contenido protegido</Text>
499	        </View>
500	      ) : null}
501	    </View>
502	  );
503	}
504	
505	const styles = StyleSheet.create({
506	  container: { flex: 1 },
507	  overlay: {
508	    position: 'absolute',
509	    top: 0,
510	    left: 0,
511	    right: 0,
512	    bottom: 0,
513	    // Opaco (sin transparencia): el screenshot del app switcher no debe dejar ver nada.
514	    backgroundColor: colors.background,
515	    alignItems: 'center',
516	    justifyContent: 'center',
517	    padding: spacing.lg,
518	  },
519	  label: { color: colors.textMuted, fontSize: 16 },
520	});
521	/**
522	 * Acceso al ciclo de vida de la app (`AppState` de React Native), inyectable.
523	 *
524	 * Lo consumen el overlay de privacidad (RG-9) y la suspensión/reanudación del canal
525	 * WebSocket privado (RG-5). Se abstrae para poder dirigir el ciclo de vida desde los tests
526	 * sin depender del SO (RG-11).
527	 */
528	import { AppState, type AppStateStatus } from 'react-native';
529	
530	export type { AppStateStatus };
531	
532	export interface AppStateSubscriptionLike {
533	  remove(): void;
534	}
535	
536	export interface AppStateLike {
537	  currentState: AppStateStatus | null;
538	  addEventListener(
539	    type: 'change',
540	    handler: (state: AppStateStatus) => void,
541	  ): AppStateSubscriptionLike;
542	}
543	
544	/** `AppState` de React Native, o el doble inyectado. */
545	export function resolveAppState(injected?: AppStateLike): AppStateLike {
546	  return injected ?? (AppState as unknown as AppStateLike);
547	}
548	
549	/**
550	 * Estado actual normalizado. `AppState.currentState` puede ser `null` (todavía sin
551	 * determinar) o, en entornos de test sin módulo nativo, un valor que no es un estado
552	 * válido: en ambos casos se asume `active`, que es el estado que **no** oculta nada.
553	 */
554	export function currentAppState(appState: AppStateLike): AppStateStatus {
555	  const value = appState.currentState;
556	  return value === 'active' || value === 'inactive' || value === 'background'
557	    ? value
558	    : 'active';
559	}

