    36	/**
    37	 * Devuelve la dirección con checksum EIP-55.
    38	 *
    39	 * Acepta la entrada con o sin prefijo `0x` y en cualquier caja (por ejemplo la forma
    40	 * enteramente en minúsculas que puede devolver un explorer o un QR ajeno). El algoritmo es
    41	 * el del EIP-55: `Keccak-256` sobre la cadena ASCII del hexadecimal en minúsculas (sin
    42	 * `0x`), y se pasa a mayúscula el dígito `i` si el nibble `i` del hash es `>= 8`.
    43	 *
    44	 * Lanza si la entrada no es `0x` + 40 hex: no hay "mejor esfuerzo" posible sobre una
    45	 * dirección de otro largo, y silenciar el caso podría terminar generando un QR hacia una
    46	 * dirección que no existe (RN-2).
    47	 */
    48	export function toChecksumAddress(value: string): string {
    49	  if (typeof value !== 'string') {
    50	    throw new Error('dirección inválida: se esperaba una cadena de texto');
    51	  }
    52	  const raw = value.startsWith('0x') || value.startsWith('0X') ? value.slice(2) : value;
    53	  if (!/^[0-9a-fA-F]{40}$/.test(raw)) {
    54	    throw new Error('dirección inválida: se esperan 40 dígitos hexadecimales (20 bytes)');
    55	  }
