    58	  const hash = keccak_256(utf8ToBytes(lower));
    59	  let out = '0x';
    60	  for (let i = 0; i < lower.length; i++) {
    61	    const ch = lower[i]!;
    62	    // nibble i del hash: byte i>>1, mitad alta si i es par.
    63	    const nibble = i % 2 === 0 ? hash[i >> 1]! >> 4 : hash[i >> 1]! & 0x0f;
    64	    out += nibble >= 8 ? ch.toUpperCase() : ch;
    65	  }
    66	  return out;
    67	}
