    88	    this.onUnauthenticated = options.onUnauthenticated;
    89	  }
    90	
    91	  async request<T>(path: string, options: RequestOptions = {}): Promise<T> {
    92	    const { method = 'GET', body, auth = false, handleUnauthenticated = true, query } = options;
    93	    const headers: Record<string, string> = { accept: 'application/json' };
    94	    if (body !== undefined) headers['content-type'] = 'application/json';
    95	
    96	    let tokenUsed: string | null = null;
    97	    if (auth) {
    98	      tokenUsed = this.getToken();
    99	      if (tokenUsed) headers.authorization = `Bearer ${tokenUsed}`;
