    83	    super(`ApiError(${code})`);
    84	    this.name = 'ApiError';
    85	    this.code = code;
    86	    this.httpStatus = httpStatus;
    87	    this.details = details;
    88	  }
    89	
    90	  /** `details.issues` normalizado, o `[]` si el error no trae issues utilizables. */
    91	  get issues(): ValidationIssue[] {
    92	    const raw = this.details?.issues;
    93	    if (!Array.isArray(raw)) return [];
    94	    const issues: ValidationIssue[] = [];
    95	    for (const item of raw) {
    96	      if (typeof item === 'string') {
    97	        issues.push({ field: '', message: item });
    98	        continue;
    99	      }
   100	      if (typeof item !== 'object' || item === null) continue;
   101	      const record = item as Record<string, unknown>;
   102	      const field = record.field ?? record.path ?? record.name ?? '';
   103	      const message = record.message ?? record.msg ?? '';
   104	      issues.push({
   105	        field: typeof field === 'string' ? field : String(field),
   106	        message: typeof message === 'string' ? message : '',
   107	      });
   108	    }
   109	    return issues;
   110	  }
   111	
   112	  /**
   113	   * `details.retryAfterSeconds` de `RATE_LIMITED`. Es un **conteo** y viaja como entero
   114	   * JSON, no como string (modelo de errores §3.5, nota de tipos). Se tolera además un
   115	   * string de dígitos por robustez. `null` si no hay un entero no negativo utilizable.
   116	   */
   117	  get retryAfterSeconds(): number | null {
   118	    const raw = this.details?.retryAfterSeconds;
   119	    if (typeof raw === 'number') {
   120	      return Number.isInteger(raw) && raw >= 0 ? raw : null;
   121	    }
   122	    if (typeof raw === 'string' && /^(0|[1-9][0-9]*)$/.test(raw)) {
   123	      const parsed = Number(raw);
   124	      return Number.isSafeInteger(parsed) ? parsed : null;
   125	    }
   126	    return null;
   127	  }
   128	}
   129	
   130	/**
   131	 * Fallo que impide obtener una respuesta de dominio: el servidor no fue alcanzable, la
   132	 * conexión se cortó, o la respuesta no trae un envelope de error del catálogo.
   133	 *
   134	 * Es el caso de HU-11-01 RN-9 (fallo de red durante el login): se distingue de
   135	 * `INVALID_CREDENTIALS` y habilita el reintento.
   136	 */
   137	export class NetworkError extends Error {
   138	  constructor() {
   139	    super('NetworkError');
   140	    this.name = 'NetworkError';
   141	  }
   142	}
   143	
   144	/** Mensaje no técnico y sin detalle sensible para el fallo de red / 500 (RN-9). */
   145	export const CONNECTION_ERROR_MESSAGE = 'No se pudo conectar, reintentá';
   146	
   147	/** Mensaje genérico de credenciales, que no revela si el email existe (RN-3). */
   148	export const INVALID_CREDENTIALS_MESSAGE = 'Email o contraseña incorrectos';
   149	
   150	/** Aviso de sesión expirada al volver a login (RN-5). */
   151	export const SESSION_EXPIRED_MESSAGE = 'Tu sesión expiró, ingresá nuevamente';
   152	
   153	/** Texto por `code` del catálogo, en español y sin datos del error del servidor (RG-3). */
   154	const MESSAGE_BY_CODE: Partial<Record<ErrorCode, string>> = {
   155	  UNAUTHENTICATED: SESSION_EXPIRED_MESSAGE,
   156	  UNAUTHORIZED: 'No tenés permiso para esta operación',
   157	  RATE_LIMITED: 'Demasiados intentos. Esperá unos segundos antes de reintentar',
   158	  VALIDATION_ERROR: 'Revisá los datos ingresados',
   159	  NOT_FOUND: 'El recurso solicitado no existe',
   160	  METHOD_NOT_ALLOWED: CONNECTION_ERROR_MESSAGE,
   161	  INVALID_CREDENTIALS: INVALID_CREDENTIALS_MESSAGE,
   162	  ACCOUNT_NOT_FOUND: 'El recurso solicitado no existe',
   163	  EMAIL_ALREADY_EXISTS: 'Ya existe una cuenta con ese email',
   164	  CHAIN_ID_MISMATCH: 'La red solicitada no es Sepolia',
   165	  CONFLICT: 'La operación no se pudo completar por un conflicto de estado',
   166	  INTERNAL_ERROR: CONNECTION_ERROR_MESSAGE,
   167	};
   168	
   169	/**
   170	 * Mensaje a mostrar para un error cualquiera. Un `code` desconocido (o un fallo de red)
   171	 * cae en el mensaje no técnico de RN-9: nunca se muestra texto proveniente del servidor.
   172	 */
   173	export function messageForError(error: unknown): string {
   174	  if (error instanceof ApiError) {
   175	    if (isErrorCode(error.code)) {
   176	      return MESSAGE_BY_CODE[error.code] ?? CONNECTION_ERROR_MESSAGE;
   177	    }
   178	    return CONNECTION_ERROR_MESSAGE;
   179	  }
   180	  return CONNECTION_ERROR_MESSAGE;
   181	}

