 77	 * rechaza (equivale a un fallo de red).
 78	 */
 79	export function createFetchMock(): FetchMock {
 80	  const requests: RecordedRequest[] = [];
 81	  const handlers: Array<{
 82	    fragment: string;
 83	    handler: (request: RecordedRequest) => Promise<Response> | Response;
 84	  }> = [];
 85	
 86	  const fetchImpl: FetchLike = (input, init) => {
 87	    const headers: Record<string, string> = {};
 88	    const rawHeaders = (init?.headers ?? {}) as Record<string, string>;
 89	    for (const [key, value] of Object.entries(rawHeaders)) headers[key.toLowerCase()] = value;
 90	    const record: RecordedRequest = {
 91	      url: input,
 92	      method: init?.method ?? 'GET',
 93	      headers,
 94	      body: typeof init?.body === 'string' ? init.body : undefined,
 95	    };
 96	    requests.push(record);
 97	    const match = handlers.find((entry) => input.includes(entry.fragment));
 98	    if (!match) return Promise.reject(new Error('sin conectividad'));
 99	    return Promise.resolve(match.handler(record));
100	  };
101	
102	  return {
103	    fetchImpl,
104	    requests,
105	    on(fragment, handler) {
106	      handlers.unshift({ fragment, handler });
107	    },
108	  };
109	}
