 13	import {
 14	  BACKOFF_MAX_MS,
 15	  PrivateChannel,
 16	  type ConnectionStatus,
 17	  type WebSocketInstanceLike,
 18	  type WebSocketLike,
 19	  type WebSocketMessageEventLike,
 20	} from '../src/ws/privateChannel';
 21	
 22	const WS_URL = 'ws://localhost:3000/api/v1/ws';
 23	const TOKEN = 'token-de-sesion-1';
 24	
 25	/** Doble del WebSocket (RG-11): registra lo enviado y permite simular el servidor. */
 26	class FakeWebSocket implements WebSocketInstanceLike {
 27	  static instances: FakeWebSocket[] = [];
 28	
 29	  readonly url: string;
 30	  readonly sent: string[] = [];
 31	  closeCalls = 0;
 32	
 33	  onopen: ((event?: unknown) => void) | null = null;
 34	  onmessage: ((event: WebSocketMessageEventLike) => void) | null = null;
 35	  onerror: ((event?: unknown) => void) | null = null;
 36	  onclose: ((event?: unknown) => void) | null = null;
 37	
 38	  constructor(url: string) {
 39	    this.url = url;
 40	    FakeWebSocket.instances.push(this);
 41	  }
 42	
 43	  send(data: string): void {
 44	    this.sent.push(data);
 45	  }
 46	
 47	  close(): void {
 48	    this.closeCalls += 1;
 49	  }
 50	
 51	  /** Mensajes enviados por el cliente, ya parseados. */
 52	  get sentMessages(): unknown[] {
 53	    return this.sent.map((raw) => JSON.parse(raw) as unknown);
 54	  }
 55	
 56	  simulateOpen(): void {
 57	    this.onopen?.();
 58	  }
 59	
 60	  simulateMessage(message: unknown): void {
 61	    this.onmessage?.({ data: JSON.stringify(message) });
 62	  }
 63	
 64	  simulateDisconnect(): void {
 65	    this.onclose?.();
 66	  }
 67	
 68	  simulateError(): void {
 69	    this.onerror?.();
 70	  }
 71	}
 72	
 73	/** Reloj falso: registra los delays agendados y los ejecuta a pedido (RG-11). */
 74	class FakeTimers {
 75	  private seq = 0;
 76	  private readonly pending = new Map<number, () => void>();
 77	  readonly delays: number[] = [];
 78	
 79	  readonly setTimeoutImpl = ((handler: () => void, delay?: number): number => {
 80	    this.seq += 1;
 81	    this.pending.set(this.seq, handler);
 82	    this.delays.push(delay ?? 0);
 83	    return this.seq;
 84	  }) as unknown as typeof setTimeout;
 85	
 86	  readonly clearTimeoutImpl = ((handle?: unknown): void => {
 87	    this.pending.delete(handle as number);
 88	  }) as unknown as typeof clearTimeout;
 89	
 90	  get pendingCount(): number {
 91	    return this.pending.size;
 92	  }
 93	
 94	  /** Ejecuta los callbacks pendientes (equivale a "pasó el delay"). */
 95	  runPending(): void {
 96	    for (const [id, handler] of [...this.pending]) {
 97	      this.pending.delete(id);
 98	      handler();
 99	    }
100	  }
101	}
102	
103	interface Harness {
104	  channel: PrivateChannel;
105	  timers: FakeTimers;
106	  sockets: FakeWebSocket[];
107	  statuses: ConnectionStatus[];
108	  unauthenticated: Array<string | null>;
109	  messages: unknown[];
110	}
111	
112	function makeChannel(
113	  overrides: {
114	    token?: string | null;
115	    channels?: Array<'orders' | 'balances' | 'withdrawals'>;
116	    random?: () => number;
117	  } = {},
118	): Harness {
119	  FakeWebSocket.instances = [];
120	  const timers = new FakeTimers();
121	  const statuses: ConnectionStatus[] = [];
122	  const unauthenticated: Array<string | null> = [];
123	  const messages: unknown[] = [];
124	  const token = overrides.token === undefined ? TOKEN : overrides.token;
125	
126	  const channel = new PrivateChannel({
127	    url: WS_URL,
128	    getToken: () => token,
129	    onUnauthenticated: (tokenUsed) => unauthenticated.push(tokenUsed),
130	    channels: overrides.channels ?? ['orders', 'balances'],
131	    onMessage: (message) => messages.push(message),
132	    onStatusChange: (status) => statuses.push(status),
133	    webSocketImpl: FakeWebSocket as unknown as WebSocketLike,
134	    setTimeoutImpl: timers.setTimeoutImpl,
135	    clearTimeoutImpl: timers.clearTimeoutImpl,
136	    // Jitter determinista: `0.5` ⇒ ±0 ms, así el delay observado es el base de RG-10.
137	    random: overrides.random ?? ((): number => 0.5),
138	  });
139	
140	  return { channel, timers, sockets: FakeWebSocket.instances, statuses, unauthenticated, messages };
141	}
142	
143	/** Deja el canal autenticado y devuelve el socket vigente. */
144	function connectAndAuthenticate(h: Harness): FakeWebSocket {
145	  h.channel.start();
146	  const socket = h.sockets[h.sockets.length - 1]!;
147	  socket.simulateOpen();
148	  socket.simulateMessage({ type: 'authenticated' });
149	  return socket;
150	}
