/**
 * Utilidades compartidas por la suite de aceptación del cliente mobile.
 *
 * Todo lo que toca el sistema operativo (almacén cifrado, portapapeles, ciclo de vida de la
 * app) se sustituye por dobles inyectados o espiados, de modo que los escenarios se evalúen
 * sin depender de un dispositivo ni del tiempo real (README de la épica 11, RG-11).
 */
import * as SecureStore from 'expo-secure-store';
import type { FetchLike } from '../src/api/client';

/** Respuesta mínima que consume `ApiClient` (`ok`, `status`, `text()`). */
export function jsonResponse(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    text: () => Promise.resolve(body === undefined ? '' : JSON.stringify(body)),
  } as unknown as Response;
}

/** Envelope de error del catálogo (`00-fundaciones/modelo-de-errores.md` §1). */
export function errorResponse(
  status: number,
  code: string,
  details?: Record<string, unknown>,
): Response {
  return jsonResponse(status, {
    error: {
      code,
      message: 'mensaje de diagnóstico del servidor, no evaluable',
      ...(details !== undefined ? { details } : {}),
    },
  });
}

export interface RecordedRequest {
  url: string;
  method: string;
  headers: Record<string, string>;
  body: string | undefined;
}

export interface FetchMock {
  fetchImpl: FetchLike;
  requests: RecordedRequest[];
  /** Encola una respuesta para la próxima petición que matchee el path. */
  on(pathFragment: string, handler: (request: RecordedRequest) => Promise<Response> | Response): void;
}

/**
 * `fetch` falso enrutado por fragmento de path. Sin handler para una ruta, la petición
 * rechaza (equivale a un fallo de red).
 */
export function createFetchMock(): FetchMock {
  const requests: RecordedRequest[] = [];
  const handlers: Array<{
    fragment: string;
    handler: (request: RecordedRequest) => Promise<Response> | Response;
  }> = [];

  const fetchImpl: FetchLike = (input, init) => {
    const headers: Record<string, string> = {};
    const rawHeaders = (init?.headers ?? {}) as Record<string, string>;
    for (const [key, value] of Object.entries(rawHeaders)) headers[key.toLowerCase()] = value;
    const record: RecordedRequest = {
      url: input,
      method: init?.method ?? 'GET',
      headers,
      body: typeof init?.body === 'string' ? init.body : undefined,
    };
    requests.push(record);
    const match = handlers.find((entry) => input.includes(entry.fragment));
    if (!match) return Promise.reject(new Error('sin conectividad'));
    return Promise.resolve(match.handler(record));
  };

  return {
    fetchImpl,
    requests,
    on(fragment, handler) {
      handlers.unshift({ fragment, handler });
    },
  };
}

export interface SecureStoreFake {
  memory: Map<string, string>;
  get: jest.SpyInstance;
  set: jest.SpyInstance;
  remove: jest.SpyInstance;
  /** Hace fallar la lectura, como el Keychain en *Before First Unlock* (RN-11). */
  failReadsWith(error: Error): void;
}

/**
 * Sustituye Expo SecureStore por un almacén en memoria espiado. Es el **único** almacén al
 * que el cliente puede escribir el token (HU-11-01 RN-2).
 */
export function installSecureStoreFake(initial: Record<string, string> = {}): SecureStoreFake {
  const memory = new Map<string, string>(Object.entries(initial));
  let readError: Error | null = null;

  const get = jest
    .spyOn(SecureStore, 'getItemAsync')
    .mockImplementation((key: string) =>
      readError !== null ? Promise.reject(readError) : Promise.resolve(memory.get(key) ?? null),
    );
  const set = jest
    .spyOn(SecureStore, 'setItemAsync')
    .mockImplementation((key: string, value: string) => {
      memory.set(key, value);
      return Promise.resolve();
    });
  const remove = jest.spyOn(SecureStore, 'deleteItemAsync').mockImplementation((key: string) => {
    memory.delete(key);
    return Promise.resolve();
  });

  return {
    memory,
    get,

