import { render, screen, waitFor } from '@testing-library/react-native';
import * as Clipboard from 'expo-clipboard';
import { App } from '/repo/mobile/src/App';
import { TOKEN_KEY } from '/repo/mobile/src/session/secureStorage';
import { CUENTA, DEPOSITO, createFetchMock, installSecureStoreFake, jsonResponse, errorResponse, type FetchMock, type SecureStoreFake } from '/repo/mobile/tests/support';

const BASE_URL = 'http://backend.test/api/v1';
let fetchMock: FetchMock; let secure: SecureStoreFake;
beforeEach(() => {
  fetchMock = createFetchMock();
  secure = installSecureStoreFake({ [TOKEN_KEY]: CUENTA.token });
  jest.spyOn(Clipboard, 'setStringAsync').mockResolvedValue(true);
  fetchMock.on('/me', () => jsonResponse(200, { accountId: CUENTA.accountId, email: CUENTA.email, status: 'ACTIVE', createdAt: '2026-01-01T00:00:00.000Z' }));
});
afterEach(() => jest.restoreAllMocks());

function typeNames(node: any, acc = new Set<string>()): Set<string> {
  if (!node) return acc;
  if (Array.isArray(node)) { node.forEach(n => typeNames(n, acc)); return acc; }
  if (typeof node === 'object' && node.type) { acc.add(String(node.type)); typeNames(node.children, acc); }
  return acc;
}

it('P1b: texto renderizado con address en minúsculas', async () => {
  fetchMock.on('/deposit-address', () => jsonResponse(200, { asset: 'ETH', address: DEPOSITO.address.toLowerCase() }));
  render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
  const el = await screen.findByTestId('deposit-address');
  console.log('TEXTO RENDERIZADO EXACTO:', JSON.stringify(el.props.children));
});

it('P6b: tipos nativos del QR', async () => {
  fetchMock.on('/deposit-address', () => jsonResponse(200, { asset: 'ETH', address: DEPOSITO.address }));
  render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
  await screen.findByTestId('deposit-address');
  const names = [...typeNames(screen.toJSON() as any)];
  console.log('TIPOS:', names.join(', '));
});

it('P5b: tras 401 se ve el login', async () => {
  fetchMock.on('/deposit-address', () => errorResponse(401, 'UNAUTHENTICATED'));
  render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
  await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
  await waitFor(() => { expect(screen.queryByTestId('login-email') ?? screen.queryByTestId('login-submit')).not.toBeNull(); });
  console.log('LOGIN VISIBLE OK; textos:', screen.queryByTestId('login-error')?.props.children);
});

it('P7: RATE_LIMITED e INTERNAL_ERROR', async () => {
  fetchMock.on('/deposit-address', () => errorResponse(429, 'RATE_LIMITED', { retryAfterSeconds: 5 }));
  render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
  console.log('ERROR 429:', JSON.stringify((await screen.findByTestId('deposit-error')).props.children));
});

it('P8: CHAIN_ID_MISMATCH', async () => {
  fetchMock.on('/deposit-address', () => errorResponse(422, 'CHAIN_ID_MISMATCH', { expected: '11155111', got: '1' }));
  render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
  console.log('ERROR CHAIN:', JSON.stringify((await screen.findByTestId('deposit-error')).props.children));
});

it('P9: respuesta 200 con campos extra sensibles se renderiza?', async () => {
  fetchMock.on('/deposit-address', () => jsonResponse(200, { asset: 'ETH', address: DEPOSITO.address, mnemonic: 'abandon abandon abandon', privateKey: '0xdeadbeef', derivationPath: "m/44'/60'/0'/0/0" }));
  render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
  await screen.findByTestId('deposit-address');
  const texts = screen.root ? JSON.stringify(screen.toJSON(), (k, v) => (k === 'Provider' ? undefined : v)) : '';
  console.log('CONTIENE mnemonic:', texts.includes('abandon'), '| privateKey:', texts.includes('deadbeef'), '| derivationPath:', texts.includes("m/44"));
});
EOF
