    13	  initialWindowMetrics,
    14	} from 'react-native-safe-area-context';
    15	import { Router, type RouteName } from './navigation/Router';
    16	import { SessionProvider, useSession, type SessionProviderProps } from './session/SessionProvider';
    17	import { PrivacyOverlay } from './ui/PrivacyOverlay';
    18	import type { AppStateLike } from './ui/appState';
    19	import { colors } from './ui/theme';
    20	
    21	export interface AppProps extends Omit<SessionProviderProps, 'children'> {
