    24	}
    25	
    26	interface ShellProps {
    27	  onNavigate?: (route: RouteName) => void;
    28	  appState?: AppStateLike;
    29	}
    30	
    31	function Shell({ onNavigate, appState }: ShellProps) {
    32	  const { status } = useSession();
    33	  return (
