import { act, render, screen, waitFor } from '@testing-library/react-native';
import * as SecureStore from 'expo-secure-store';
import { App } from '/repo/mobile/src/App';
import { TOKEN_KEY } from '/repo/mobile/src/session/secureStorage';
import { createAppStateFake, createFetchMock, CUENTA, DEPOSITO, jsonResponse } from '/repo/mobile/tests/support';

const BASE = 'http://backend.test/api/v1';

afterEach(() => jest.restoreAllMocks());

it('RN-11: tras un fallo de lectura, el próximo foreground reintenta el acceso al almacén', async () => {
  let fail = true;
  const memory = new Map<string, string>([[TOKEN_KEY, CUENTA.token]]);
  const get = jest.spyOn(SecureStore, 'getItemAsync').mockImplementation((key: string) =>
    fail ? Promise.reject(new Error('Keychain item inaccessible')) : Promise.resolve(memory.get(key) ?? null),
  );
  jest.spyOn(SecureStore, 'setItemAsync').mockResolvedValue(undefined as never);
  jest.spyOn(SecureStore, 'deleteItemAsync').mockResolvedValue(undefined as never);

  const fetchMock = createFetchMock();
  fetchMock.on('/me', () => jsonResponse(200, { accountId: CUENTA.accountId, email: CUENTA.email, status: 'ACTIVE', createdAt: '2026-01-01T00:00:00.000Z' }));
  fetchMock.on('/deposit-address', () => jsonResponse(200, { asset: 'ETH', address: DEPOSITO.address, chainId: '11155111' }));
  const appState = createAppStateFake('active');

  render(<App baseUrl={BASE} fetchImpl={fetchMock.fetchImpl} wsUrl="" appState={appState} />);
  expect(await screen.findByTestId('login-submit')).toBeTruthy();
  expect(get).toHaveBeenCalledTimes(1);

  // El Keychain ya es accesible (el dispositivo se desbloqueó). La app va a background y vuelve.
  fail = false;
  await act(async () => { appState.set('background'); });
  await act(async () => { appState.set('active'); });
  await act(async () => { await Promise.resolve(); });

  // RN-11: "En el próximo intento de foreground reintenta el acceso."
  expect(get.mock.calls.length).toBeGreaterThan(1);
  await waitFor(() => expect(screen.queryByTestId('deposit-address')).not.toBeNull());
});
EOF
