const HABILITADO = process.env.MOBILE_E2E === '1';
const BASE_URL = process.env.MOBILE_E2E_API_BASE_URL ?? 'http://localhost:3000/api/v1';

const describeE2E = HABILITADO ? describe : describe.skip;

/** Cuenta nueva por corrida: el registro es idempotente sólo por email (HU-01-01 RN-4). */
const EMAIL = `mobile-e2e-${Date.now()}@example.com`;
const PASSWORD = 'Contraseña-E2E-12345';

let secure: SecureStoreFake;

describeE2E('Cliente mobile contra el backend real', () => {
  beforeAll(async () => {
    const response = await nodeFetch(`${BASE_URL}/auth/register`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
    });
    if (response.status !== 201) {
      throw new Error(
        `no se pudo registrar la cuenta de prueba (HTTP ${response.status}): ${await response.text()}`,
      );
    }
  });

  beforeEach(() => {
    secure = installSecureStoreFake();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('permite loguearse y ver la dirección de depósito con su QR', async () => {
    render(<App baseUrl={BASE_URL} wsUrl="" fetchImpl={nodeFetch} />);

    fireEvent.changeText(await screen.findByTestId('login-email'), EMAIL);
    fireEvent.changeText(screen.getByTestId('login-password'), PASSWORD);
    fireEvent.press(screen.getByTestId('login-submit'));

    // El token real del backend queda en el almacén cifrado (AT-11-01-01).
    await waitFor(() => expect(secure.set).toHaveBeenCalledWith(TOKEN_KEY, expect.any(String)));
    const token = secure.memory.get(TOKEN_KEY);
    expect(typeof token).toBe('string');
    expect(token).not.toBe('');

    // Dirección de depósito real, derivada por la wallet HD del backend (AT-11-06-01).
    const address = (await screen.findByTestId('deposit-address')).props.children as string;
    expect(/^0x[0-9a-fA-F]{40}$/.test(address)).toBe(true);
    expect(isValidChecksumAddress(address)).toBe(true);
    expect(screen.getByTestId('deposit-network')).toHaveTextContent(/11155111/);
    expect(screen.UNSAFE_getByType(QRCode).props.value).toBe(`ethereum:${address}@11155111`);
    expect(screen.getByTestId('session-email')).toHaveTextContent(EMAIL);

    // El QR de USDC-mock usa el `tokenAddress` que devuelve la API (AT-11-06-26).
    fireEvent.press(screen.getByTestId('deposit-asset-USDC'));
    const respuestaUsdc = (await (
      await nodeFetch(`${BASE_URL}/deposit-address?asset=USDC`, {
        headers: { authorization: `Bearer ${token}` },
      })
    ).json()) as { address: string; tokenAddress: string };
    expect(respuestaUsdc.address).toBe(address);
    await waitFor(() =>
      expect(screen.UNSAFE_getByType(QRCode).props.value).toBe(
        `ethereum:${respuestaUsdc.tokenAddress}@11155111/transfer?address=${address}`,
      ),
    );
  });

  it('con credenciales incorrectas muestra el mensaje genérico y no persiste token', async () => {
    render(<App baseUrl={BASE_URL} wsUrl="" fetchImpl={nodeFetch} />);

