import { act, render, screen, waitFor } from '@testing-library/react-native';
import { App } from '/repo/mobile/src/App';
import { TOKEN_KEY } from '/repo/mobile/src/session/secureStorage';
import {
  CUENTA, DEPOSITO, createAppStateFake, createFetchMock, errorResponse,
  installSecureStoreFake, jsonResponse, type FetchMock, type SecureStoreFake,
} from '/repo/mobile/tests/support';

const BASE = 'http://backend.test/api/v1';
const WS = 'ws://backend.test/api/v1/ws';

class FakeWS {
  static instances: FakeWS[] = [];
  url: string;
  sent: string[] = [];
  closed = 0;
  onopen: ((e?: unknown) => void) | null = null;
  onmessage: ((e: { data: unknown }) => void) | null = null;
  onerror: ((e?: unknown) => void) | null = null;
  onclose: ((e?: unknown) => void) | null = null;
  constructor(url: string) { this.url = url; FakeWS.instances.push(this); }
  send(d: string) { this.sent.push(d); }
  close() { this.closed += 1; }
  open() { this.onopen?.(); }
  msg(m: unknown) { this.onmessage?.({ data: JSON.stringify(m) }); }
}

let fetchMock: FetchMock;
let secure: SecureStoreFake;
let prevWS: unknown;

beforeEach(() => {
  FakeWS.instances = [];
  prevWS = (globalThis as any).WebSocket;
  (globalThis as any).WebSocket = FakeWS;
  fetchMock = createFetchMock();
  secure = installSecureStoreFake();
  fetchMock.on('/me', () => jsonResponse(200, { accountId: CUENTA.accountId, email: CUENTA.email, status: 'ACTIVE', createdAt: '2026-01-01T00:00:00.000Z' }));
  fetchMock.on('/deposit-address', () => jsonResponse(200, { asset: 'ETH', address: DEPOSITO.address, chainId: '11155111' }));
});
afterEach(() => { (globalThis as any).WebSocket = prevWS; jest.restoreAllMocks(); });

it('AT-11-01-12: UNAUTHENTICATED del canal privado limpia la sesión y redirige al login', async () => {
  secure.memory.set(TOKEN_KEY, CUENTA.token);
  const navegaciones: string[] = [];
  const appState = createAppStateFake('active');
  render(<App baseUrl={BASE} fetchImpl={fetchMock.fetchImpl} wsUrl={WS} appState={appState} onNavigate={(r) => navegaciones.push(r)} />);
  await screen.findByTestId('deposit-address');

  await waitFor(() => expect(FakeWS.instances.length).toBe(1));
  const socket = FakeWS.instances[0]!;
  await act(async () => { socket.open(); });
  expect(JSON.parse(socket.sent[0]!)).toEqual({ type: 'auth', token: CUENTA.token });
  await act(async () => { socket.msg({ type: 'authenticated' }); });

  // Token expirado mientras la app estuvo en background: el canal responde UNAUTHENTICATED.
  await act(async () => { socket.msg({ error: { code: 'UNAUTHENTICATED' } }); });

  expect(await screen.findByTestId('login-submit')).toBeTruthy();
  await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
  expect(navegaciones).toEqual(['splash', 'deposit', 'login']);
});

it('AT-11-01-14: 401 de REST y de WS a la vez ⇒ un único borrado y una única navegación', async () => {
  secure.memory.set(TOKEN_KEY, CUENTA.token);
  const navegaciones: string[] = [];
  const appState = createAppStateFake('active');
  render(<App baseUrl={BASE} fetchImpl={fetchMock.fetchImpl} wsUrl={WS} appState={appState} onNavigate={(r) => navegaciones.push(r)} />);
