nextDelayMs(): number {
  const base = Math.min(
    BACKOFF_INITIAL_MS * Math.pow(BACKOFF_FACTOR, this.retryCount),
    BACKOFF_MAX_MS,
  );
  const jitter = (this.random() * 2 - 1) * BACKOFF_JITTER_MS;
  return Math.max(0, base + jitter);
}

// --- internos -------------------------------------------------------------------------

private connect(): void {
  const token = this.getToken();
  // Sin sesión no hay canal privado que abrir (HU-09-04 RN-1: exige token).
  if (token === null || token === '') {
    this.setStatus('idle');
    return;
  }
  const WebSocketImpl = this.webSocketImpl ?? (globalThis as { WebSocket?: WebSocketLike }).WebSocket;
  if (WebSocketImpl === undefined) {
    this.setStatus('idle');
    return;
  }

  this.tokenUsed = token;
  this.unauthenticatedNotified = false;
  this.setStatus('connecting');

  // La url no lleva el token en ningún parámetro (HU-09-04 RN-1).
  const socket = new WebSocketImpl(this.url);
  this.socket = socket;

  socket.onopen = (): void => {
    if (this.socket !== socket) return;
    // Primer mensaje del handshake, antes de cualquier `subscribe` (HU-09-04 RN-1).
    this.send(socket, { type: 'auth', token });
  };
  socket.onmessage = (event: WebSocketMessageEventLike): void => {
    if (this.socket !== socket) return;
    this.handleMessage(socket, event);
  };
  socket.onerror = (): void => {
    this.handleDisconnect(socket);
  };
  socket.onclose = (): void => {
    this.handleDisconnect(socket);
  };
}

private handleMessage(socket: WebSocketInstanceLike, event: WebSocketMessageEventLike): void {
  const parsed = this.parse(event.data);
  if (parsed === undefined) return;

  // `UNAUTHENTICATED` en cualquier momento (handshake o canal ya autenticado):
  // HU-11-01 RN-12 / AT-11-01-12.
  if (readErrorCode(parsed) === 'UNAUTHENTICATED') {
    this.handleUnauthenticated(socket);
    return;
  }

  const type = readMessageType(parsed);
  if (type === 'authenticated') {
    // Conexión exitosa: se resetea el backoff a 1 s (RG-10) y se suscriben los canales.
    this.retryCount = 0;
    this.setStatus('live');
    for (const channel of this.channels) {
      this.send(socket, { type: 'subscribe', channel });
    }
    return;
  }

  // El resto (snapshots, deltas, `subscribed`, errores no-401) va a la capa de datos.
  this.onMessage?.(parsed);
}

private handleUnauthenticated(socket: WebSocketInstanceLike): void {
  if (this.socket !== socket) return;
  if (this.unauthenticatedNotified) return;
  this.unauthenticatedNotified = true;
  const tokenUsed = this.tokenUsed;

  // La sesión terminó: se cierra el socket y **no** hay reintento (reintentar con un token
  // que el servidor ya rechazó sería un bucle). El logout singleton lo resuelve el
  // consumidor (RG-8).
  this.sessionEnded = true;
  this.cancelRetry();
  this.closeSocket();
  this.setStatus('idle');
  this.onUnauthenticated(tokenUsed);
}

