/**
 * Enlace de React con `SessionStore` (HU-11-01).
 *
 * Provee el estado de sesión, el `ApiClient` ya configurado con el token vigente y el
 * manejo de `UNAUTHENTICATED` (RN-5), y el canal WebSocket privado cuando hay una URL
 * configurada (RN-12).
 */
import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useSyncExternalStore,
  type ReactNode,
} from 'react';
import { ApiClient, type FetchLike } from '../api/client';
import { API_BASE_URL, WS_URL } from '../config';
import { resolveAppState, type AppStateLike } from '../ui/appState';
import { PrivateChannel } from '../ws/privateChannel';
import { SessionStore, type SessionState } from './sessionStore';

export interface SessionContextValue extends SessionState {
  api: ApiClient;
  store: SessionStore;
  signIn(token: string): Promise<void>;
  signOut(): Promise<void>;
  dismissNotice(): void;
}

const SessionContext = createContext<SessionContextValue | null>(null);

export interface SessionProviderProps {
  children: ReactNode;
  /** Sobrescribe el prefijo de la API (tests / configuración explícita). */
  baseUrl?: string;
  /** Sobrescribe la implementación de `fetch` (tests). */
  fetchImpl?: FetchLike;
  /** Store inyectable (tests); por defecto se crea uno nuevo. */
  store?: SessionStore;
  /** URL del canal privado; vacía = no se conecta (ver `src/config.ts`). */
  wsUrl?: string;
  /** Fuente del ciclo de vida; por defecto el `AppState` de React Native (tests: doble). */
  appState?: AppStateLike;
}

export function SessionProvider({
  children,
  baseUrl,
  fetchImpl,
  store: injectedStore,
  wsUrl,
  appState,
}: SessionProviderProps) {
  const storeRef = useRef<SessionStore | null>(injectedStore ?? null);
  if (storeRef.current === null) storeRef.current = new SessionStore();
  const store = storeRef.current;

  const state = useSyncExternalStore(
    (listener) => store.subscribe(listener),
    () => store.getState(),
    () => store.getState(),
  );

  const api = useMemo(
    () =>
      new ApiClient({
        baseUrl: baseUrl ?? API_BASE_URL,
        ...(fetchImpl !== undefined ? { fetchImpl } : {}),
        getToken: store.getToken,
        // RN-5 / RG-8: el manejo es singleton dentro del store.
        onUnauthenticated: (tokenUsed) => {
          void store.handleUnauthenticated(tokenUsed);
        },
      }),
    [baseUrl, fetchImpl, store],
  );

  // RN-4: restauración de sesión al abrir la app. Corre una sola vez por montaje.
  useEffect(() => {
    void store.restore();
  }, [store]);

  // RN-12 + RG-5: canal privado con el mismo token del almacén seguro; se suspende en
  // background y se reconecta (con snapshot fresco) al volver a foreground. Sólo se activa
  // si hay una URL de WebSocket configurada: el backend de esta corrida no expone los
  // canales de la épica 09 (HU-09-03/HU-09-04).
  const resolvedWsUrl = wsUrl ?? WS_URL;
  useEffect(() => {
    if (resolvedWsUrl === '' || state.status !== 'authenticated') return;
    const channel = new PrivateChannel({
      url: resolvedWsUrl,
      getToken: store.getToken,
      onUnauthenticated: (tokenUsed) => {
        void store.handleUnauthenticated(tokenUsed);
      },
      channels: ['balances'],
    });
    channel.start();
    const subscription = resolveAppState(appState).addEventListener('change', (next) => {
      if (next === 'active' || next === 'inactive' || next === 'background') {
        channel.handleAppStateChange(next);
      }
    });
    return () => {
      subscription.remove();
      channel.stop();
    };
  }, [appState, resolvedWsUrl, state.status, store]);

  const value = useMemo<SessionContextValue>(
    () => ({
      ...state,
      api,
      store,
      signIn: (token: string) => store.signIn(token),
      signOut: () => store.signOut(),
      dismissNotice: () => store.dismissNotice(),
    }),
    [state, api, store],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): SessionContextValue {
  const value = useContext(SessionContext);
  if (!value) throw new Error('useSession requiere un <SessionProvider> ancestro');
  return value;
}
