/**
 * Cliente HTTP de la API del exchange (contrato de la épica 09).
 *
 * - Ruta base `/api/v1` (HU-09-01 RN-1), configurable por entorno (`src/config.ts`).
 * - Autenticación por header `Authorization: Bearer <token>` (HU-09-02 RN-1 / HU-11-01 RN-5).
 *   El token viaja **sólo** en el header: nunca en la URL, ni en el cuerpo, ni en un log
 *   (HU-11-01 RN-7).
 * - Toda respuesta de error se traduce a `ApiError` con el `code` del catálogo; cualquier
 *   otra falla (red, respuesta ilegible) a `NetworkError` (HU-11-01 RN-9).
 */
import { ApiError, NetworkError } from './errors';

export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

export interface ApiClientOptions {
  /** Prefijo de la API. */
  baseUrl: string;
  /** Implementación de `fetch` (inyectable para tests). */
  fetchImpl?: FetchLike;
  /** Token Bearer vigente, o `null` si no hay sesión. */
  getToken?: () => string | null;
  /**
   * Se invoca cuando una llamada **protegida** responde `UNAUTHENTICATED` (401).
   *
   * Recibe el token con el que se hizo esa petición: permite que el manejo de sesión
   * ignore un 401 tardío de una sesión ya reemplazada, y que el flujo de logout sea
   * singleton (HU-11-01 RN-5, RG-8).
   */
  onUnauthenticated?: (tokenUsed: string | null) => void;
}

export interface RequestOptions {
  method?: 'GET' | 'POST' | 'DELETE';
  body?: unknown;
  /** Adjunta el header `Authorization` si hay token. */
  auth?: boolean;
  /**
   * Si es `false`, un `UNAUTHENTICATED` no dispara el manejo global de sesión. Lo usa el
   * login, que es un endpoint **público**: un 401 ahí es credencial rechazada, no una
   * sesión que expiró.
   */
  handleUnauthenticated?: boolean;
  /** Query params ya en su forma final (se codifican acá). */
  query?: Record<string, string>;
}

function joinUrl(baseUrl: string, path: string): string {
  const base = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
