 */
import { useEffect, useRef } from 'react';
import { ActivityIndicator, StyleSheet, View } from 'react-native';
import { useSession } from '../session/SessionProvider';
import { DepositScreen } from '../screens/DepositScreen';
import { LoginScreen } from '../screens/LoginScreen';
import { colors } from '../ui/theme';

export type RouteName = 'splash' | 'login' | 'deposit';

export interface RouterProps {
  /** Se invoca en cada cambio de destino (incluido el inicial). */
  onNavigate?: (route: RouteName) => void;
}

export function routeForStatus(status: 'restoring' | 'anonymous' | 'authenticated'): RouteName {
  if (status === 'restoring') return 'splash';
  return status === 'authenticated' ? 'deposit' : 'login';
}

export function Router({ onNavigate }: RouterProps) {
  const { status } = useSession();
  const route = routeForStatus(status);
  const previous = useRef<RouteName | null>(null);

  useEffect(() => {
    if (previous.current === route) return;
    previous.current = route;
    onNavigate?.(route);
  }, [route, onNavigate]);

  if (route === 'splash') {
    // Restauración de sesión en curso (RN-4). Es una pantalla de espera, no un destino:
    // no se llama a ningún endpoint autenticado hasta resolver si hay token (AT-11-01-03).
    return (
      <View style={styles.splash} testID="splash">
        <ActivityIndicator color={colors.accent} />
      </View>
    );
  }

  return route === 'deposit' ? <DepositScreen /> : <LoginScreen />;
}

const styles = StyleSheet.create({
  splash: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: colors.background,
  },
});

