  onmessage: ((event: WebSocketMessageEventLike) => void) | null;
  onerror: ((event?: unknown) => void) | null;
  onclose: ((event?: unknown) => void) | null;
}

/**
 * Constructor de WebSocket (el global del runtime, o un doble en los tests — RG-11).
 * Recibe **sólo** la url: el token va en el primer mensaje, nunca en la url (HU-09-04 RN-1).
 */
export type WebSocketLike = new (url: string) => WebSocketInstanceLike;

export interface PrivateChannelOptions {
  /** URL del WS (`ws://host/api/v1/ws`, RG-API-11). */
  url: string;
  /** Token vigente del almacenamiento seguro; `null` si no hay sesión. */
  getToken: () => string | null;
  /**
   * Se invoca cuando el canal recibe `UNAUTHENTICATED` (handshake o mensaje del canal).
   * Recibe el token con el que se autenticó ese intento, para que el manejo de sesión
   * pueda ignorar un 401 tardío de una sesión ya reemplazada (RN-12 + RG-8).
   */
  onUnauthenticated: (tokenUsed: string | null) => void;
  /** Canales privados a los que suscribirse al autenticar. */
  channels?: PrivateChannelName[];
  /** Mensajes ya parseados del servidor (snapshot/deltas). */
  onMessage?: (message: unknown) => void;
  onStatusChange?: (status: ConnectionStatus) => void;
  /** Inyectables para tests (RG-11). */
  webSocketImpl?: WebSocketLike;
  setTimeoutImpl?: typeof setTimeout;
  clearTimeoutImpl?: typeof clearTimeout;
  random?: () => number;
}

type TimerHandle = ReturnType<typeof setTimeout>;

/** Lee `error.code` del envelope uniforme de la épica 09 (RG-3); `null` si no lo respeta. */
function readErrorCode(message: unknown): string | null {
  if (typeof message !== 'object' || message === null) return null;
  const error = (message as Record<string, unknown>).error;
  if (typeof error !== 'object' || error === null) return null;
  const code = (error as Record<string, unknown>).code;
  return typeof code === 'string' && code !== '' ? code : null;
}

/** Lee `type` de un mensaje del protocolo WS; `null` si no lo trae. */
function readMessageType(message: unknown): string | null {
  if (typeof message !== 'object' || message === null) return null;
  const type = (message as Record<string, unknown>).type;
  return typeof type === 'string' && type !== '' ? type : null;
}

export class PrivateChannel {
  private readonly url: string;
  private readonly getToken: () => string | null;
  private readonly onUnauthenticated: (tokenUsed: string | null) => void;
  private readonly channels: PrivateChannelName[];
  private readonly onMessage: ((message: unknown) => void) | undefined;
  private readonly onStatusChange: ((status: ConnectionStatus) => void) | undefined;
  private readonly webSocketImpl: WebSocketLike | undefined;
  private readonly setTimeoutImpl: typeof setTimeout;
  private readonly clearTimeoutImpl: typeof clearTimeout;
  private readonly random: () => number;

  private socket: WebSocketInstanceLike | null = null;
  private retryTimer: TimerHandle | null = null;

