cat >> src/chain/address.ts <<'EOF'

/**
 * `true` si `value` **es** su forma canónica EIP-55 (`toChecksumAddress(value) === value`).
 *
 * Éste —y no `isValidChecksumAddress`— es el criterio correcto para decidir si una
 * dirección que la app va a **mostrar** está bien formada (HU-11-06 RN-2 / AT-11-06-01):
 * los cuatro vectores oficiales del EIP-55 enteramente en minúsculas o en mayúsculas (p. ej.
 * `0x52908400098527886E0F7030069857D2E4169EE7`, cuya forma canónica no tiene ningún dígito
 * `a`-`f` en minúscula) **son** canónicos aunque no transporten un checksum de caja mixta.
 */
export function isChecksumCanonical(value: string): boolean {
  if (!isAddressLike(value)) return false;
  return toChecksumAddress(value.slice(2)) === value;
}

/**
 * `true` si la caja de `value` **transporta** un checksum EIP-55 verificable: tiene dígitos
 * alfabéticos y no está enteramente en minúsculas ni enteramente en mayúsculas.
 *
 * Una dirección "sin checksum" (toda minúscula/mayúscula) no es sospechosa: simplemente no
 * dice nada, y el cliente la canonicaliza. Una con caja **mixta** sí afirma un checksum: si
 * no verifica, la dirección está alterada y corresponde advertirlo.
 */
export function carriesChecksumCase(value: string): boolean {
  if (!isAddressLike(value)) return false;
  const body = value.slice(2);
  if (body.toLowerCase() === body.toUpperCase()) return false; // sin dígitos a-f
  return body !== body.toLowerCase() && body !== body.toUpperCase();
}
