/** Doble controlable de `AppState` para dirigir el ciclo de vida en los tests (RG-11). */
export function createAppStateFake(initial: 'active' | 'inactive' | 'background' = 'active') {
  const handlers = new Set<(state: 'active' | 'inactive' | 'background') => void>();
  const fake = {
    currentState: initial as 'active' | 'inactive' | 'background',
    addEventListener(_type: 'change', handler: (state: never) => void) {
      handlers.add(handler as (state: 'active' | 'inactive' | 'background') => void);
      return {
        remove() {
          handlers.delete(handler as (state: 'active' | 'inactive' | 'background') => void);
        },
      };
    },
    /** Simula la transición del SO. */
    set(state: 'active' | 'inactive' | 'background') {
      fake.currentState = state;
      for (const handler of handlers) handler(state);
    },
  };
  return fake;
}
=====STORE
/**
 * Estado de sesión del cliente mobile (HU-11-01).
 *
 * Se implementa como un store observable sin dependencias de React: la lógica de RN-4,
 * RN-5, RN-6, RN-10 y RN-11 —incluida la garantía de **logout singleton** de RG-8— se
 * puede ejercitar y verificar sin montar la UI.
 *
 * Máquina de estados:
 *
 *   restoring ──(hay token en el almacén cifrado)──► authenticated
 *       │                                                 │
 *       └─(no hay token, o el almacén falla — RN-11)──┐    │ UNAUTHENTICATED (RN-5)
 *                                                     ▼    │ logout del usuario (RN-6)
 *                                                  anonymous ◄─┘
 *
 * La restauración es **optimista** (RN-10): si hay token se entra directo a la vista
 * autenticada, **sin** llamada de validación previa. La expiración se detecta de forma
 * reactiva, cuando la primera petición autenticada (REST o handshake WebSocket) recibe
 * `UNAUTHENTICATED`.
 */
import { SESSION_EXPIRED_MESSAGE } from '../api/errors';
import { deleteToken, readToken, writeToken } from './secureStorage';

export type SessionStatus = 'restoring' | 'anonymous' | 'authenticated';

export interface SessionState {
  status: SessionStatus;
  /** Token en memoria. Nunca se renderiza ni se loguea (RN-7). */
  token: string | null;
  /** Aviso a mostrar en la pantalla de login (p. ej. sesión expirada, RN-5). */
  notice: string | null;
}

type Listener = () => void;

export class SessionStore {
  private state: SessionState = { status: 'restoring', token: null, notice: null };
  private readonly listeners = new Set<Listener>();
  /**
   * Flujo de logout en curso (RG-8). Mientras haya uno, las activaciones adicionales son
   * **no-ops** y devuelven la misma promesa: un único borrado del token, una única
   * limpieza de estado y una única transición a `anonymous` (y por lo tanto una única
   * navegación al login).
   */
  private logoutInFlight: Promise<void> | null = null;
  /**
   * La última lectura del almacén seguro **falló** (RN-11). Habilita el reintento en el
   * próximo foreground; se limpia en cuanto una lectura tiene éxito o hay un login.
   */
  private restoreFailed = false;
  /**
   * El borrado del token no pudo completarse (RN-6). Mientras esté en `true` la sesión no
   * se restaura —aunque el almacén devuelva el token viejo— y se reintenta el borrado en
   * cada foreground.
   */
  private purgePending = false;

  getState(): SessionState {
    return this.state;
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private setState(next: Partial<SessionState>): void {
    this.state = { ...this.state, ...next };
    for (const listener of this.listeners) listener();
  }

  /** Token vigente, para el header `Authorization` y el handshake del WebSocket (RN-5/RN-12). */
  getToken = (): string | null => this.state.token;

  /**
   * Restauración de sesión al abrir la app (RN-4 + RN-10). Nunca lanza: un fallo del
   * almacén seguro se trata como "sin token" y termina en la pantalla de login (RN-11).
   */
  async restore(): Promise<void> {
    if (this.purgePending) {
      // Hubo un logout cuyo borrado no se pudo completar (RN-6): lo que quede en el almacén
      // es un token ya cerrado y no debe restaurar nada. Se reintenta la purga.
      this.setState({ status: 'anonymous', token: null });
      await this.purgeToken();
      return;
    }
    const { available, token } = await readToken();
    this.restoreFailed = !available;
    if (token === null) {
      // AT-11-01-03 / AT-11-01-13: sin token (o con el almacén inaccesible) se muestra el
      // login y **no** se llama a ningún endpoint autenticado.
      this.setState({ status: 'anonymous', token: null });
      return;
    }
    // AT-11-01-02: se entra directo a la vista autenticada, sin validar contra el backend.
    this.setState({ status: 'authenticated', token, notice: null });
  }

  /**
   * Vuelta de la app a **foreground**. Reintenta lo que pudo haber fallado contra el almacén
   * seguro mientras el dispositivo estaba bloqueado o el almacén inaccesible:
   *
   *  - RN-11: si la lectura de la restauración falló, se **reintenta el acceso** («En el
   *    próximo intento de foreground reintenta el acceso»), de modo que la sesión se
   *    restaure sin tener que matar y reabrir la app.
   *  - RN-6: si el borrado del token quedó pendiente tras un logout, se reintenta.
   *
   * Nunca lanza y nunca pisa una sesión viva: sólo actúa si la app está en `anonymous`.
   */
  async handleForeground(): Promise<void> {
    if (this.purgePending) {
      await this.purgeToken();
      return;
    }
    if (this.state.status !== 'anonymous' || !this.restoreFailed) return;
    await this.restore();
  }

  /**
   * Establece la sesión tras un login exitoso (RN-2 / AT-11-01-01).
   *
   * Persiste **primero** en el almacén cifrado y recién después expone la sesión, para que
   * no exista un estado observable "autenticado pero sin persistir".
   */
  async signIn(token: string): Promise<void> {
    await writeToken(token);
    this.restoreFailed = false;
    this.purgePending = false;
    // Una sesión nueva deja atrás cualquier logout previo: el guard de RG-8 protege un
    // único flujo de cierre, no impide volver a cerrar la sesión siguiente.
    this.logoutInFlight = null;
    this.setState({ status: 'authenticated', token, notice: null });
  }

  /** Logout explícito del usuario (RN-6). */
  async signOut(): Promise<void> {
    await this.runLogout(null);
  }

  /**
   * `UNAUTHENTICATED` (401) recibido en una petición autenticada o en el canal privado
   * (RN-5 / RN-12): borra el token persistido, limpia el estado y vuelve al login.
   *
   * Es **singleton** (RG-8 / AT-11-01-14): varios 401 concurrentes producen un único
   * borrado y una única navegación.
   *
   * @param tokenUsed token con el que se hizo la petición que recibió el 401. Un 401 de
   * una sesión ya reemplazada (login nuevo mientras la petición vieja viajaba) se ignora.
   */
  handleUnauthenticated(tokenUsed: string | null = null): Promise<void> {
    if (this.logoutInFlight) return this.logoutInFlight;
    if (this.state.status !== 'authenticated') return Promise.resolve();
    if (tokenUsed !== null && tokenUsed !== this.state.token) return Promise.resolve();
    return this.runLogout(SESSION_EXPIRED_MESSAGE);
  }

  private runLogout(notice: string | null): Promise<void> {
    if (this.logoutInFlight) return this.logoutInFlight;
    // La limpieza de memoria y la transición a `anonymous` son **síncronas**: cualquier
    // otro 401 que llegue mientras el borrado del almacén está en vuelo ya encuentra la
    // sesión cerrada, además del guard de `logoutInFlight`.
    this.setState({ status: 'anonymous', token: null, notice });
    // Un logout invalida cualquier reintento de restauración pendiente (RN-6): no hay sesión
    // que recuperar, sólo un token que borrar.
    this.restoreFailed = false;
    const pending: Promise<void> = this.purgeToken().finally(() => {
      // Sólo se libera el guard si sigue siendo *este* logout el vigente: un `signIn`
      // posterior ya lo habrá reemplazado.
      if (this.logoutInFlight === pending) this.logoutInFlight = null;
    });
    this.logoutInFlight = pending;
    return pending;
  }

  /**
   * Borra el token del almacén cifrado y deja anotado el reintento si no se pudo (RN-6).
   *
