=====ROUTER
/**
 * Navegación del cliente mobile.
 *
 * El alcance de esta corrida son dos destinos —login y depósito—, así que la navegación se
 * **deriva del estado de sesión** en vez de mantener un stack propio: `authenticated` ⇒
 * vista autenticada, `anonymous` ⇒ login (HU-11-01 RN-4/RN-5/RN-6).
 *
 * Que el destino sea función del estado hace que la navegación al login sea **una sola** por
 * cierre de sesión aunque lleguen varios `UNAUTHENTICATED` concurrentes (RG-8 /
 * AT-11-01-14): el store colapsa los 401 en una única transición y el router en una única
 * navegación. `onNavigate` expone cada cambio de destino para poder verificarlo.
 */
import { useEffect, useRef } from 'react';
import { ActivityIndicator, StyleSheet, View } from 'react-native';
import { useSession } from '../session/SessionProvider';
import { DepositScreen } from '../screens/DepositScreen';
import { LoginScreen } from '../screens/LoginScreen';
import { colors } from '../ui/theme';

export type RouteName = 'splash' | 'login' | 'deposit';

export interface RouterProps {
  /** Se invoca en cada cambio de destino (incluido el inicial). */
  onNavigate?: (route: RouteName) => void;
}

export function routeForStatus(status: 'restoring' | 'anonymous' | 'authenticated'): RouteName {
  if (status === 'restoring') return 'splash';
  return status === 'authenticated' ? 'deposit' : 'login';
}

export function Router({ onNavigate }: RouterProps) {
  const { status } = useSession();
  const route = routeForStatus(status);
  const previous = useRef<RouteName | null>(null);

  useEffect(() => {
    if (previous.current === route) return;
    previous.current = route;
    onNavigate?.(route);
  }, [route, onNavigate]);

  if (route === 'splash') {
    // Restauración de sesión en curso (RN-4). Es una pantalla de espera, no un destino:
    // no se llama a ningún endpoint autenticado hasta resolver si hay token (AT-11-01-03).
    return (
      <View style={styles.splash} testID="splash">
        <ActivityIndicator color={colors.accent} />
      </View>
    );
  }

  return route === 'deposit' ? <DepositScreen /> : <LoginScreen />;
}

const styles = StyleSheet.create({
  splash: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: colors.background,
  },
});

/**
 * Pantalla de depósito mobile (HU-11-06, Escenarios 1 y 26 — AT-11-06-01 / AT-11-06-26).
 *
 * Muestra la dirección de depósito de la cuenta con su **QR** y la acción de **copiar**,
 * aclarando la red (**Sepolia**, `chainId = 11155111`) y el activo.
 *
 * Alcance de esta corrida: **sólo** la presentación de la dirección. El seguimiento de
 * depósitos (RN-3) y los retiros quedan fuera porque su backend (épicas 07 y 08) no está
 * implementado.
 *
 * Reglas aplicadas:
 *  - RN-1: la dirección **viene de la API** (`GET /api/v1/deposit-address?asset=`); el
 *    cliente no la deriva ni accede a la seed.
 *  - RN-2: address en texto con checksum EIP-55 **siempre**, QR en formato EIP-681, y una
 *    **única** dirección recibe ETH y USDC-mock.
 *  - RN-11: ante `UNAUTHENTICATED` se limpia la sesión y se vuelve al login (lo hace el
 *    `ApiClient` vía `SessionStore`, flujo singleton RG-8).
 *  - RN-12: nunca se muestra ni se pide mnemonic, seed ni claves privadas.
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import * as Clipboard from 'expo-clipboard';
import QRCode from 'react-native-qrcode-svg';
import { getProfile, type Profile } from '../api/auth';
import { getDepositAddress, type DepositAddress } from '../api/deposits';
import { ApiError, messageForError } from '../api/errors';
import { carriesChecksumCase, isAddressLike, isChecksumCanonical, toChecksumAddress } from '../chain/address';
import { buildDepositUri, MissingTokenAddressError, type DepositAsset } from '../chain/eip681';
import { CHAIN_ID, NETWORK_LABEL } from '../config';
import { useSession } from '../session/SessionProvider';
import { colors, radius, spacing } from '../ui/theme';

const ASSETS: readonly DepositAsset[] = ['ETH', 'USDC'];

const ASSET_LABEL: Record<DepositAsset, string> = {
  ETH: 'ETH (nativo)',
  USDC: 'USDC-mock (ERC-20)',
};

/**
 * Respuesta ya aplicada a la pantalla, junto con el activo que se pidió para obtenerla.
 *
 * El activo viaja con el dato —y no sólo en el estado `asset`— para que el QR se arme
 * **siempre** con la respuesta del activo seleccionado: de lo contrario, la respuesta
 * tardía de un activo anterior podría combinarse con el activo actual (p. ej. la de ETH,
 * que no trae `tokenAddress`, con USDC ya seleccionado) y dejar la pantalla sin QR.
 */
interface DepositEntry {
  asset: DepositAsset;
  response: DepositAddress;
}

export function DepositScreen() {
  const { api, signOut } = useSession();
  const [asset, setAsset] = useState<DepositAsset>('ETH');
  const [data, setData] = useState<DepositEntry | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  /**
   * Número de la última petición disparada. Toda respuesta (o error) que no corresponda a
   * la petición vigente se **descarta**: cambiar de activo mientras la anterior está en
   * vuelo no puede dejar la pantalla mostrando —ni el QR usando— datos de otro activo.
   */
  const requestSeq = useRef(0);

  const load = useCallback(
    async (target: DepositAsset) => {
      const seq = ++requestSeq.current;
      setError(null);
      try {
        const response = await getDepositAddress(api, target);
        if (seq !== requestSeq.current) return;
        if (response.asset !== target) {
          // El contrato (HU-09-01 RN-10) devuelve el activo consultado: una respuesta de
          // otro activo no es usable para armar el QR de éste (RN-2).
          setData(null);
          setError('La API devolvió la dirección de otro activo. Reintentá.');
          return;
        }
        setData({ asset: target, response });
      } catch (err) {
        if (seq !== requestSeq.current) return;
        setData(null);
        // Un `UNAUTHENTICATED` ya disparó el cierre de sesión en el `ApiClient` (RN-11 /
        // RG-8): la app está navegando al login, así que no se muestra ningún error acá.
        const expirada = err instanceof ApiError && err.code === 'UNAUTHENTICATED';
        setError(expirada ? null : messageForError(err));
      }
    },
    [api],
  );

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void load(asset).finally(() => {
      if (!cancelled) setLoading(false);
    });
    return () => {
      cancelled = true;
    };
  }, [asset, load]);

  // El email de la cuenta identifica la sesión abierta. Es la primera petición autenticada
  // del arranque en frío junto con la dirección: si el token restaurado estaba expirado,
  // acá se detecta de forma reactiva (RN-10 de HU-11-01).
  useEffect(() => {
    let cancelled = false;
    getProfile(api).then(
      (loaded) => {
        if (!cancelled) setProfile(loaded);
      },
      () => {
        /* el perfil es informativo: su fallo no bloquea la pantalla de depósito */
      },
    );
    return () => {
      cancelled = true;
    };
  }, [api]);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    void load(asset).finally(() => setRefreshing(false));
  }, [asset, load]);

  // RN-2: se copia exactamente el mismo texto que se muestra, con checksum EIP-55.
  const onCopy = useCallback(async (value: string) => {
    await Clipboard.setStringAsync(value);
    setCopied(true);
  }, []);

  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 2500);
    return () => clearTimeout(timer);
  }, [copied]);

  // Sólo se pinta la respuesta del activo seleccionado (ver `DepositEntry`).
  const entry = data !== null && data.asset === asset ? data : null;
  const rawAddress = entry !== null ? entry.response.address : null;

  // RN-2 / AT-11-06-01: la dirección se **muestra** y se **copia** con checksum EIP-55. La
