=====API
/**
 * Cliente HTTP de la API del exchange (contrato de la épica 09).
 *
 * - Ruta base `/api/v1` (HU-09-01 RN-1), configurable por entorno (`src/config.ts`).
 * - Autenticación por header `Authorization: Bearer <token>` (HU-09-02 RN-1 / HU-11-01 RN-5).
 *   El token viaja **sólo** en el header: nunca en la URL, ni en el cuerpo, ni en un log
 *   (HU-11-01 RN-7).
 * - Toda respuesta de error se traduce a `ApiError` con el `code` del catálogo; cualquier
 *   otra falla (red, respuesta ilegible) a `NetworkError` (HU-11-01 RN-9).
 */
import { ApiError, NetworkError } from './errors';

export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

export interface ApiClientOptions {
  /** Prefijo de la API. */
  baseUrl: string;
  /** Implementación de `fetch` (inyectable para tests). */
  fetchImpl?: FetchLike;
  /** Token Bearer vigente, o `null` si no hay sesión. */
  getToken?: () => string | null;
  /**
   * Se invoca cuando una llamada **protegida** responde `UNAUTHENTICATED` (401).
   *
   * Recibe el token con el que se hizo esa petición: permite que el manejo de sesión
   * ignore un 401 tardío de una sesión ya reemplazada, y que el flujo de logout sea
   * singleton (HU-11-01 RN-5, RG-8).
   */
  onUnauthenticated?: (tokenUsed: string | null) => void;
}

export interface RequestOptions {
  method?: 'GET' | 'POST' | 'DELETE';
  body?: unknown;
  /** Adjunta el header `Authorization` si hay token. */
  auth?: boolean;
  /**
   * Si es `false`, un `UNAUTHENTICATED` no dispara el manejo global de sesión. Lo usa el
   * login, que es un endpoint **público**: un 401 ahí es credencial rechazada, no una
   * sesión que expiró.
   */
  handleUnauthenticated?: boolean;
  /** Query params ya en su forma final (se codifican acá). */
  query?: Record<string, string>;
}

function joinUrl(baseUrl: string, path: string): string {
  const base = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
  const suffix = path.startsWith('/') ? path : `/${path}`;
  return `${base}${suffix}`;
}

/** Extrae `{ code, details }` del envelope uniforme; `null` si el cuerpo no lo respeta. */
function readErrorEnvelope(
  payload: unknown,
): { code: string; details?: Record<string, unknown> } | null {
  if (typeof payload !== 'object' || payload === null) return null;
  const error = (payload as Record<string, unknown>).error;
  if (typeof error !== 'object' || error === null) return null;
  const { code, details } = error as Record<string, unknown>;
  if (typeof code !== 'string' || code === '') return null;
  return {
    code,
    details:
      typeof details === 'object' && details !== null && !Array.isArray(details)
        ? (details as Record<string, unknown>)
        : undefined,
  };
}

export class ApiClient {
  private readonly baseUrl: string;
  private readonly fetchImpl: FetchLike;
  private readonly getToken: () => string | null;
  private readonly onUnauthenticated: ((tokenUsed: string | null) => void) | undefined;

  constructor(options: ApiClientOptions) {
    this.baseUrl = options.baseUrl;
    this.fetchImpl =
      options.fetchImpl ??
      ((input, init) => {
        if (typeof globalThis.fetch !== 'function') {
          return Promise.reject(new NetworkError());
        }
        return globalThis.fetch(input, init);
      });
    this.getToken = options.getToken ?? (() => null);
    this.onUnauthenticated = options.onUnauthenticated;
  }

  async request<T>(path: string, options: RequestOptions = {}): Promise<T> {
    const { method = 'GET', body, auth = false, handleUnauthenticated = true, query } = options;
    const headers: Record<string, string> = { accept: 'application/json' };
    if (body !== undefined) headers['content-type'] = 'application/json';

    let tokenUsed: string | null = null;
    if (auth) {
      tokenUsed = this.getToken();
      if (tokenUsed) headers.authorization = `Bearer ${tokenUsed}`;
    }

    let url = joinUrl(this.baseUrl, path);
    if (query) {
      const search = Object.entries(query)
        .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
        .join('&');
      if (search !== '') url += `?${search}`;
    }

    let response: Response;
    try {
      response = await this.fetchImpl(url, {
        method,
        headers,
        ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
      });
    } catch {
      // Fallo de red: no se filtra el detalle del error subyacente (RN-9).
      throw new NetworkError();
    }

    const raw = await response.text().catch(() => '');
    let payload: unknown = undefined;
    if (raw !== '') {
      try {
        payload = JSON.parse(raw);
      } catch {
        payload = undefined;
      }
    }

    if (!response.ok) {
      const envelope = readErrorEnvelope(payload);
      // Un **401** invalida la sesión aunque el cuerpo no traiga el envelope del catálogo:
      // HU-09-05 RN-1 obliga al backend a emitirlo siempre, pero un proxy o gateway
      // intermedio puede responder 401 con cuerpo vacío o HTML, y quedarse en la vista
      // autenticada con un token muerto contradice RN-5 de HU-11-01.
      const expirada = response.status === 401 && (envelope === null || envelope.code === 'UNAUTHENTICATED');
      if (expirada && handleUnauthenticated) {
        this.onUnauthenticated?.(tokenUsed);
      }
      if (!envelope) {
        // Sin envelope no hay `code` del catálogo que reportar (RG-3): salvo el 401, que es
        // inequívoco, el resto se trata como falla de conexión.
        if (expirada) throw new ApiError('UNAUTHENTICATED', 401);
        throw new NetworkError();
      }
      throw new ApiError(envelope.code, response.status, envelope.details);
    }

    return payload as T;
  }
}

