/**
 * Endpoints de autenticación y perfil (contrato de la épica 09, idéntico al del web —
 * HU-11-01 RN-1).
 *
 *   POST /api/v1/auth/login → 200 { token, tokenType, expiresAt }   (HU-01-02)
 *   GET  /api/v1/me         → 200 { accountId, email, status, createdAt }  (HU-01-04)
 */
import type { ApiClient } from './client';

export interface LoginRequest {
  email: string;
  password: string;
}

/** Respuesta de login. `expiresAt` es ISO 8601 UTC (HU-01-02 RN-3). */
export interface LoginResponse {
  token: string;
  tokenType?: string;
  expiresAt: string;
}

/** Perfil propio: sólo identidad, sin balances ni secretos (HU-01-04 RN-4/RN-5/RN-6). */
export interface Profile {
  accountId: string;
  email: string;
  status: string;
  createdAt: string;
}

export function login(api: ApiClient, credentials: LoginRequest): Promise<LoginResponse> {
  // El login es un endpoint **público** (HU-09-02 RN-1): un 401 acá es
  // `INVALID_CREDENTIALS`, no una sesión expirada, así que no dispara el logout global.
  return api.request<LoginResponse>('/auth/login', {
    method: 'POST',
    body: credentials,
    handleUnauthenticated: false,
  });
}

/**
 * Perfil de la cuenta autenticada. La restauración de sesión de HU-11-01 RN-10 es
 * **optimista** y **no** lo llama: la app lo usa sólo para mostrar el email del usuario ya
 * dentro de la vista autenticada, y un `UNAUTHENTICATED` acá dispara el flujo de RN-5.
 */
export function getProfile(api: ApiClient): Promise<Profile> {
  return api.request<Profile>('/me', { auth: true });
}

