/**
 * Persistencia del token de sesión en el almacenamiento **cifrado** del sistema operativo
 * (Keychain en iOS / Keystore en Android) vía Expo SecureStore.
 *
 * HU-11-01 RN-2: el token se persiste **únicamente** acá. Está **prohibido** guardarlo en
 * almacenamiento no cifrado en claro (p. ej. `AsyncStorage`) o en logs; por eso este módulo
 * es el **único** punto del cliente que escribe el token, y no importa ningún otro almacén.
 *
 * HU-11-01 RN-11: si la lectura falla (p. ej. *Keychain item inaccessible* en estado
 * *Before First Unlock* tras un reinicio, o el almacén no disponible), el caso se trata
 * **como si no hubiera token persistido**. El detalle del error interno no se propaga a la
 * UI ni se loguea con datos sensibles (RN-7).
 */
import * as SecureStore from 'expo-secure-store';

/**
 * Clave del token en el almacén seguro. SecureStore admite `[A-Za-z0-9._-]`.
 *
 * Se guarda **sólo el token**: la restauración de sesión de RN-10 es optimista y no
 * inspecciona la expiración localmente (la detecta de forma reactiva ante el primer
 * `UNAUTHENTICATED`), así que persistir `expiresAt` no cambiaría ningún comportamiento y
 * sólo agrandaría la superficie de datos guardados.
 */
export const TOKEN_KEY = 'cex.mobile.session.token';

/**
 * Resultado de leer el almacén seguro.
 *
 * Distingue **"no hay token"** de **"no se pudo leer"** (RN-11): para la UI ambos casos son
 * el mismo (pantalla de login, sin exponer el detalle del error), pero sólo el segundo
 * habilita el **reintento en el próximo foreground** que exige RN-11.
 */
export interface TokenRead {
  /** `false` si el almacén no pudo leerse (p. ej. Keychain *Before First Unlock*). */
  available: boolean;
  /** Token persistido, o `null` si no hay (o no se pudo leer). */
  token: string | null;
}

/** Lee el token persistido. Nunca lanza: un fallo del almacén equivale a "no hay token". */
export async function readToken(): Promise<TokenRead> {
  try {
    const value = await SecureStore.getItemAsync(TOKEN_KEY);
    return { available: true, token: typeof value === 'string' && value !== '' ? value : null };
  } catch {
    // RN-11: se trata como "sin token". No se registra el error (podría incluir la clave o
    // el valor del almacén según la plataforma) ni se muestra su detalle en la UI.
    return { available: false, token: null };
  }
}

/**
 * Persiste el token en el almacén cifrado.
 *
 * Devuelve `true` si quedó persistido. Si el almacén no está disponible, **no** hay
 * fallback a almacenamiento en claro (RN-2): la sesión sigue viva en memoria hasta que se
 * cierre la app, y la próxima apertura pedirá credenciales.
 */
export async function writeToken(token: string): Promise<boolean> {
  try {
    await SecureStore.setItemAsync(TOKEN_KEY, token);
    return true;
  } catch {
    return false;
  }
}

/**
 * Borra el token del almacén cifrado (RN-5 / RN-6). Nunca lanza.
 *
 * Devuelve `true` si el almacén quedó **sin token utilizable**. Un fallo del borrado NO se
 * puede dar por bueno: el almacén puede estar temporalmente inaccesible **conteniendo** el
 * token (la misma condición que reconoce RN-11), y RN-6 exige que reabrir la app tras el
 * logout **no** restaure la sesión. Por eso:
 *
 *  1. se intenta el borrado;
 *  2. si falla, se intenta **sobrescribir** con la cadena vacía —operación distinta, que
 *     puede tener éxito donde el borrado no lo tuvo—, valor que `readToken` ya trata como
 *     "no hay token";
 *  3. si ambas fallan, se devuelve `false` y quien llama (`SessionStore`) reintenta en el
 *     próximo foreground y bloquea la restauración mientras tanto.
 */
export async function deleteToken(): Promise<boolean> {
  try {
    await SecureStore.deleteItemAsync(TOKEN_KEY);
    return true;
  } catch {
    /* el almacén puede estar inaccesible con el token adentro: se intenta la sobrescritura */
  }
  try {
    await SecureStore.setItemAsync(TOKEN_KEY, '');
    return true;
  } catch {
    return false;
  }
}
