/**
 * Acceso al ciclo de vida de la app (`AppState` de React Native), inyectable.
 *
 * Lo consumen el overlay de privacidad (RG-9) y la suspensión/reanudación del canal
 * WebSocket privado (RG-5). Se abstrae para poder dirigir el ciclo de vida desde los tests
 * sin depender del SO (RG-11).
 */
import { AppState, type AppStateStatus } from 'react-native';

export type { AppStateStatus };

export interface AppStateSubscriptionLike {
  remove(): void;
}

export interface AppStateLike {
  currentState: AppStateStatus | null;
  addEventListener(
    type: 'change',
    handler: (state: AppStateStatus) => void,
  ): AppStateSubscriptionLike;
}

/** `AppState` de React Native, o el doble inyectado. */
export function resolveAppState(injected?: AppStateLike): AppStateLike {
  return injected ?? (AppState as unknown as AppStateLike);
}

/**
 * Estado actual normalizado. `AppState.currentState` puede ser `null` (todavía sin
 * determinar) o, en entornos de test sin módulo nativo, un valor que no es un estado
 * válido: en ambos casos se asume `active`, que es el estado que **no** oculta nada.
 */
export function currentAppState(appState: AppStateLike): AppStateStatus {
  const value = appState.currentState;
  return value === 'active' || value === 'inactive' || value === 'background'
    ? value
    : 'active';
}

