p='tests/hu-11-06-deposito.test.tsx'
s=open(p).read()
anchor = """describe('RN-12 — la pantalla de depósito no expone secretos', () => {"""
nuevo = '''describe('RN-2 — la dirección se muestra y se copia siempre con checksum EIP-55', () => {
  /** Re-renderiza la app con una respuesta de `/deposit-address` a medida. */
  async function renderConDireccion(address: string): Promise<void> {
    cleanup();
    fetchMock = createFetchMock();
    fetchMock.on('/me', perfil);
    fetchMock.on('/deposit-address', () => jsonResponse(200, { asset: 'ETH', address }));
    render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);
    await screen.findByTestId('deposit-address');
  }

  it('canonicaliza una dirección que la API devuelve en minúsculas (texto, copia y QR)', async () => {
    await renderConDireccion(DEPOSITO.address.toLowerCase());

    // El texto que se ve es el canónico, no el que llegó en el cuerpo.
    expect(textoDe('deposit-address')).toBe(DEPOSITO.address);
    // Y el QR codifica exactamente esa misma forma: texto y QR no pueden discrepar (RN-2).
    expect(qrValue()).toBe(`ethereum:${DEPOSITO.address}@11155111`);
    // Una dirección sin caja mixta no afirma ningún checksum: no es sospechosa (RN-2).
    expect(screen.queryByTestId('deposit-address-checksum-warning')).toBeNull();

    fireEvent.press(screen.getByTestId('deposit-copy'));
    await waitFor(() => expect(copiar).toHaveBeenCalledWith(DEPOSITO.address));
  });

  it.each([
    ['All caps (vector oficial del EIP-55)', '0x52908400098527886E0F7030069857D2E4169EE7'],
    ['All Lower (vector oficial del EIP-55)', '0xde709f2102306220921060314715629080e2fb77'],
  ])('no advierte checksum sobre una dirección canónica %s', async (_caso, address) => {
    // Su forma canónica **es** enteramente mayúscula o minúscula: el backend las emite tal
    // cual (~1 de cada 1.900 cuentas) y presentarlas como sospechosas sería un falso
    // positivo sobre una dirección correcta (AT-11-06-01).
    expect(isChecksumCanonical(address)).toBe(true);
    await renderConDireccion(address);

    expect(textoDe('deposit-address')).toBe(address);
    expect(qrValue()).toBe(`ethereum:${address}@11155111`);
    expect(screen.queryByTestId('deposit-address-checksum-warning')).toBeNull();
  });

  it('advierte cuando la caja mixta de la API afirma un checksum que no verifica', async () => {
    // `0x5aAeb...` con la `A` de la posición 3 bajada a minúscula: la API está afirmando un
    // checksum que no cierra, y eso sí corresponde señalarlo.
    await renderConDireccion('0x5aaeb6053F3E94C9b9A09f33669435E7Ef1BeAed');
    expect(await screen.findByTestId('deposit-address-checksum-warning')).toBeTruthy();
    // Aun así se muestra la forma canónica, que es la que respalda al QR (RN-2).
    expect(textoDe('deposit-address')).toBe(DEPOSITO.address);
  });

  it('señala una dirección con formato inválido en vez de mostrar un QR imposible', async () => {
    await renderConDireccion('0x123');
    expect(await screen.findByTestId('deposit-address-format-warning')).toBeTruthy();
    expect(screen.UNSAFE_queryByType(QRCode)).toBeNull();
  });
});

describe('RN-2 — cambiar de activo con una petición en vuelo (AT-11-06-26)', () => {
  it('descarta la respuesta tardía del activo anterior y conserva el QR de USDC', async () => {
    cleanup();
    fetchMock = createFetchMock();
    fetchMock.on('/me', perfil);

    // La respuesta de ETH queda **en vuelo**: se resuelve a mano después de que el usuario
    // ya eligió USDC. Como la de ETH no trae `tokenAddress`, si pisara el estado dejaría a
    // USDC sin QR — exactamente lo que RN-2 / AT-11-06-26 no admiten.
    let responderEth: (response: Response) => void = () => {};
    fetchMock.on('/deposit-address', (request) => {
      if (request.url.includes('asset=USDC')) {
        return jsonResponse(200, {
          asset: 'USDC',
          address: DEPOSITO.address,
          tokenAddress: DEPOSITO.tokenAddress,
        });
      }
      return new Promise<Response>((resolve) => {
        responderEth = resolve;
      });
    });
    render(<App baseUrl={BASE_URL} fetchImpl={fetchMock.fetchImpl} wsUrl="" />);

    // El usuario no espera a que ETH conteste y toca USDC.
    fireEvent.press(await screen.findByTestId('deposit-asset-USDC'));
    const esperado = `ethereum:${DEPOSITO.tokenAddress}@11155111/transfer?address=${DEPOSITO.address}`;
    await waitFor(() => expect(qrValue()).toBe(esperado));

    // Recién ahora contesta ETH, tarde.
    await act(async () => {
      responderEth(jsonResponse(200, { asset: 'ETH', address: DEPOSITO.address }));
      await Promise.resolve();
    });

    expect(screen.getByTestId('deposit-asset-label')).toHaveTextContent(/USDC/);
    expect(qrValue()).toBe(esperado);
    expect(screen.queryByTestId('deposit-qr-unavailable')).toBeNull();
    expect(textoDe('deposit-address')).toBe(DEPOSITO.address);
  });
});

'''
assert anchor in s
s = s.replace(anchor, nuevo + anchor, 1)
open(p,'w').write(s)
