/// <reference types="jest" />
/**
 * Sesión y **canal WebSocket privado** cableados de verdad dentro de `<App>`
 * (`spec/11-cliente-mobile/HU-11-01-login-mobile.md`):
 *
 *  - **Escenario 11 — AT-11-01-12:** un `UNAUTHENTICATED` del canal privado (en el
 *    handshake o en un mensaje del canal ya autenticado) aplica el **mismo** flujo del
 *    Escenario 5: borra el token del almacén cifrado, limpia la sesión y redirige al login.
 *  - **Escenario 13 — AT-11-01-14:** varios 401 concurrentes —peticiones REST en vuelo
 *    **más** el canal WS— producen un **único** borrado del token y una **única**
 *    navegación al login (logout singleton, RG-8).
 *
 * A diferencia de `tests/ws-private-channel.test.ts` —que ejercita `PrivateChannel` en
 * aislamiento— acá se monta la app completa con una `wsUrl` **no vacía**, de modo que se
 * verifique el cableado real `PrivateChannel → SessionStore → Router`. El WebSocket es un
 * doble inyectado por `webSocketImpl` (RG-11): ningún test toca la red ni el tiempo real.
 */
import { act, render, screen, waitFor } from '@testing-library/react-native';
import { App } from '../src/App';
import { SESSION_EXPIRED_MESSAGE } from '../src/api/errors';
import { TOKEN_KEY } from '../src/session/secureStorage';
import type {
  WebSocketInstanceLike,
  WebSocketMessageEventLike,
} from '../src/ws/privateChannel';
import type { RouteName } from '../src/navigation/Router';
import {
  CUENTA,
  DEPOSITO,
  createAppStateFake,
  createFetchMock,
  errorResponse,
  installSecureStoreFake,
  jsonResponse,
  type FetchMock,
  type SecureStoreFake,
} from './support';

const BASE_URL = 'http://backend.test/api/v1';
/** RG-API-11: el WS cuelga de la misma base que el REST y **no** lleva el token en la url. */
const WS_URL = 'ws://backend.test/api/v1/ws';

/** Envelope de error de la épica 09 (RG-3) tal como llega por el canal privado. */
const MENSAJE_UNAUTHENTICATED = {
  error: { code: 'UNAUTHENTICATED', message: 'token expirado, no evaluable' },
};

/**
 * Doble del WebSocket, **local a este archivo** (RG-11): registra lo que envía el cliente y
 * permite simular al servidor sin abrir un socket real.
 */
class FakeWebSocket implements WebSocketInstanceLike {
  static instances: FakeWebSocket[] = [];

  readonly url: string;
  readonly sent: string[] = [];
  closeCalls = 0;

  onopen: ((event?: unknown) => void) | null = null;
  onmessage: ((event: WebSocketMessageEventLike) => void) | null = null;
  onerror: ((event?: unknown) => void) | null = null;
  onclose: ((event?: unknown) => void) | null = null;

  constructor(url: string) {
    this.url = url;
    FakeWebSocket.instances.push(this);
  }

  send(data: string): void {
    this.sent.push(data);
  }

  close(): void {
    this.closeCalls += 1;
  }

  /** Lo que envió el cliente, ya parseado y en orden. */
  get sentMessages(): unknown[] {
    return this.sent.map((raw) => JSON.parse(raw) as unknown);
  }

  simulateOpen(): void {
    this.onopen?.();
  }

  simulateMessage(message: unknown): void {
    this.onmessage?.({ data: JSON.stringify(message) });
  }
}

/** Promesa con su resolución expuesta, para dejar peticiones REST **en vuelo**. */
function deferred<T>(): { promise: Promise<T>; resolve: (value: T) => void } {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((resolver) => {
    resolve = resolver;
  });
  return { promise, resolve };
}

let fetchMock: FetchMock;
let secure: SecureStoreFake;
let appState: ReturnType<typeof createAppStateFake>;
let navegaciones: RouteName[];

/** Rutas de la vista autenticada respondiendo 200: en estos casos el 401 llega por el WS. */
function stubAutenticadasOk(): void {
  fetchMock.on('/me', () =>
    jsonResponse(200, {
      accountId: CUENTA.accountId,
      email: CUENTA.email,
      status: 'ACTIVE',
      createdAt: '2026-01-01T00:00:00.000Z',
    }),
  );
  fetchMock.on('/deposit-address', () =>
    jsonResponse(200, {
      asset: 'ETH',
      address: DEPOSITO.address,
      network: 'sepolia',
      chainId: '11155111',
    }),
  );
}

function renderApp() {
  return render(
    <App
      baseUrl={BASE_URL}
      fetchImpl={fetchMock.fetchImpl}
      wsUrl={WS_URL}
      webSocketImpl={FakeWebSocket}
      appState={appState}
      onNavigate={(route) => navegaciones.push(route)}
    />,
  );
}

/**
 * Espera a que la sesión restaurada abra el canal privado y simula el `open` del socket,
 * que es lo que dispara el handshake.
 */
async function abrirSocket(): Promise<FakeWebSocket> {
  await waitFor(() => expect(FakeWebSocket.instances.length).toBeGreaterThan(0));
  const socket = FakeWebSocket.instances[0];
  await act(async () => {
    socket.simulateOpen();
  });
  return socket;
}

/** Deja correr las microtareas pendientes (respuestas REST ya resueltas). */
async function drenar(): Promise<void> {
  for (let i = 0; i < 8; i += 1) await Promise.resolve();
}

beforeEach(() => {
  fetchMock = createFetchMock();
  // AT-11-01-02: hay un token persistido, así que la app arranca ya autenticada. Que esté
  // expirado sólo se descubre de forma reactiva (RN-10).
  secure = installSecureStoreFake({ [TOKEN_KEY]: CUENTA.token });
  appState = createAppStateFake();
  navegaciones = [];
  FakeWebSocket.instances = [];
});

afterEach(() => {
  jest.restoreAllMocks();
});

describe('Escenario 11 — Reconexión WebSocket con token expirado [AT-11-01-12]', () => {
  it('el handshake usa el token del almacén cifrado y nunca lo pone en la url (RN-12)', async () => {
    stubAutenticadasOk();
    renderApp();
    const socket = await abrirSocket();

    // El token sale del almacén **cifrado**, el mismo que usa el REST (RN-12).
    expect(secure.get).toHaveBeenCalledWith(TOKEN_KEY);
    // HU-09-04 RN-1: viaja en el **primer** mensaje, jamás en la url/query.
    expect(socket.url).toBe(WS_URL);
    expect(socket.url).not.toContain(CUENTA.token);
    expect(socket.sentMessages[0]).toEqual({ type: 'auth', token: CUENTA.token });
  });

  it('un UNAUTHENTICATED en el handshake limpia la sesión y redirige al login', async () => {
    stubAutenticadasOk();
    renderApp();
    const socket = await abrirSocket();
    expect(socket.sentMessages[0]).toEqual({ type: 'auth', token: CUENTA.token });

    // El servidor rechaza el token del handshake (expiró mientras la app estuvo en
    // background).
    await act(async () => {
      socket.simulateMessage(MENSAJE_UNAUTHENTICATED);
    });

    // Mismo flujo del Escenario 5: borrado del token persistido...
    await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
    expect(secure.memory.has(TOKEN_KEY)).toBe(false);
    // ...limpieza del estado y redirección al login, con el aviso de sesión expirada.
    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    expect(screen.getByTestId('login-notice')).toHaveTextContent(SESSION_EXPIRED_MESSAGE);
    expect(navegaciones).toEqual(['splash', 'deposit', 'login']);
    // El canal se cierra y no reintenta con un token ya rechazado.
    expect(socket.closeCalls).toBeGreaterThan(0);

    // Y la sesión **no** se restaura sola: ni siquiera al volver de background (RN-6).
    await act(async () => {
      appState.set('background');
    });
    await act(async () => {
      appState.set('active');
    });
    await drenar();
    expect(navegaciones).toEqual(['splash', 'deposit', 'login']);
    expect(screen.getByTestId('login-submit')).toBeTruthy();
    // Sin sesión no hay canal privado que abrir: no se creó un socket nuevo.
    expect(FakeWebSocket.instances).toHaveLength(1);
  });

  it('un UNAUTHENTICATED del canal ya autenticado aplica el mismo flujo', async () => {
    stubAutenticadasOk();
    renderApp();
    const socket = await abrirSocket();

    // Handshake OK ⇒ suscripción a los canales privados (HU-09-04 RN-2).
    await act(async () => {
      socket.simulateMessage({ type: 'authenticated' });
    });
    expect(socket.sentMessages).toEqual([
      { type: 'auth', token: CUENTA.token },
      { type: 'subscribe', channel: 'balances' },
    ]);
    // Hasta acá la sesión sigue viva.
    expect(navegaciones).toEqual(['splash', 'deposit']);
    expect(secure.remove).not.toHaveBeenCalled();

    // El token expira **durante** la suscripción: el canal responde con el envelope de error.
    await act(async () => {
      socket.simulateMessage(MENSAJE_UNAUTHENTICATED);
    });

    await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
    expect(secure.memory.has(TOKEN_KEY)).toBe(false);
    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    expect(navegaciones).toEqual(['splash', 'deposit', 'login']);
    expect(socket.closeCalls).toBeGreaterThan(0);
  });
});

describe('Escenario 13 — Logout singleton ante múltiples 401 [AT-11-01-14]', () => {
  /**
   * Deja las dos peticiones autenticadas de la vista (`/me` y `/deposit-address`) **en
   * vuelo** y devuelve sus resolutores, para poder hacerlas fallar con 401 en el mismo
   * instante que el canal WS.
   */
  function peticionesEnVuelo(): { responder: () => void } {
    const perfil = deferred<Response>();
    const direccion = deferred<Response>();
    fetchMock.on('/me', () => perfil.promise);
    fetchMock.on('/deposit-address', () => direccion.promise);
    return {
      responder() {
        perfil.resolve(errorResponse(401, 'UNAUTHENTICATED'));
        direccion.resolve(errorResponse(401, 'UNAUTHENTICATED'));
      },
    };
  }

  it('un solo borrado del token y una sola navegación con 401 de REST y WS a la vez', async () => {
    const rest = peticionesEnVuelo();
    renderApp();
    const socket = await abrirSocket();

    // La pantalla autenticada ya disparó sus peticiones con el token restaurado...
    await waitFor(() =>
      expect(fetchMock.requests.filter((request) => request.headers.authorization !== undefined))
        .toHaveLength(2),
    );
    for (const request of fetchMock.requests) {
      expect(request.headers.authorization).toBe(`Bearer ${CUENTA.token}`);
    }
    expect(socket.sentMessages[0]).toEqual({ type: 'auth', token: CUENTA.token });

    // ...y ahora los tres 401 llegan de forma concurrente: dos por REST y uno por el canal.
    await act(async () => {
      rest.responder();
      socket.simulateMessage(MENSAJE_UNAUTHENTICATED);
      await drenar();
    });

    await waitFor(() => expect(screen.getByTestId('login-submit')).toBeTruthy());
    await drenar();

    // RG-8: un **único** borrado del token...
    expect(secure.remove).toHaveBeenCalledTimes(1);
    expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY);
    expect(secure.memory.has(TOKEN_KEY)).toBe(false);
    // ...y una **única** navegación al login, sin repetirla ni volver a la vista autenticada.
    expect(navegaciones).toEqual(['splash', 'deposit', 'login']);
    expect(navegaciones.filter((route) => route === 'login')).toHaveLength(1);
    expect(screen.getByTestId('login-notice')).toHaveTextContent(SESSION_EXPIRED_MESSAGE);
  });

  it('tampoco se duplica si el 401 del canal llega después de los de REST', async () => {
    const rest = peticionesEnVuelo();
    renderApp();
    const socket = await abrirSocket();
    await waitFor(() =>
      expect(fetchMock.requests.filter((request) => request.headers.authorization !== undefined))
        .toHaveLength(2),
    );

    // Los 401 de REST cierran la sesión primero; el mensaje del canal es un no-op (llegue
    // al store o lo descarte el propio canal ya detenido).
    await act(async () => {
      rest.responder();
      await drenar();
      socket.simulateMessage(MENSAJE_UNAUTHENTICATED);
    });

    await waitFor(() => expect(screen.getByTestId('login-submit')).toBeTruthy());
    await drenar();

    expect(secure.remove).toHaveBeenCalledTimes(1);
    expect(navegaciones).toEqual(['splash', 'deposit', 'login']);
  });
});

