describe('Escenario 6 — Logout borra el token [AT-11-01-06]', () => {
  it('borra el token del almacén y de memoria, vuelve al login y no restaura al reabrir', async () => {
    secure.memory.set(TOKEN_KEY, CUENTA.token);
    const { unmount } = renderApp();

    fireEvent.press(await screen.findByTestId('logout'));

    expect(await screen.findByTestId('login-submit')).toBeTruthy();
    await waitFor(() => expect(secure.remove).toHaveBeenCalledWith(TOKEN_KEY));
    expect(secure.memory.has(TOKEN_KEY)).toBe(false);
    unmount();

    // Reabrir la app vuelve a pedir credenciales.
    renderApp();
