/// <reference types="jest" />
/**
 * Sesión y **canal WebSocket privado** cableados de verdad dentro de `<App>`
 * (`spec/11-cliente-mobile/HU-11-01-login-mobile.md`):
 *
 *  - **Escenario 11 — AT-11-01-12:** un `UNAUTHENTICATED` del canal privado (en el
 *    handshake o en un mensaje del canal ya autenticado) aplica el **mismo** flujo del
 *    Escenario 5: borra el token del almacén cifrado, limpia la sesión y redirige al login.
 *  - **Escenario 13 — AT-11-01-14:** varios 401 concurrentes —peticiones REST en vuelo
 *    **más** el canal WS— producen un **único** borrado del token y una **única**
 *    navegación al login (logout singleton, RG-8).
 *
 * A diferencia de `tests/ws-private-channel.test.ts` —que ejercita `PrivateChannel` en
 * aislamiento— acá se monta la app completa con una `wsUrl` **no vacía**, de modo que se
 * verifique el cableado real `PrivateChannel → SessionStore → Router`. El WebSocket es un
 * doble inyectado por `webSocketImpl` (RG-11): ningún test toca la red ni el tiempo real.
 */
import { act, render, screen, waitFor } from '@testing-library/react-native';
import { App } from '../src/App';
import { SESSION_EXPIRED_MESSAGE } from '../src/api/errors';
import { TOKEN_KEY } from '../src/session/secureStorage';
import type {
  WebSocketInstanceLike,
  WebSocketMessageEventLike,
} from '../src/ws/privateChannel';
import type { RouteName } from '../src/navigation/Router';
import {
  CUENTA,
  DEPOSITO,
  createAppStateFake,
  createFetchMock,
  errorResponse,
  installSecureStoreFake,
  jsonResponse,
  type FetchMock,
  type SecureStoreFake,
} from './support';

const BASE_URL = 'http://backend.test/api/v1';
/** RG-API-11: el WS cuelga de la misma base que el REST y **no** lleva el token en la url. */
const WS_URL = 'ws://backend.test/api/v1/ws';

/** Envelope de error de la épica 09 (RG-3) tal como llega por el canal privado. */
const MENSAJE_UNAUTHENTICATED = {
  error: { code: 'UNAUTHENTICATED', message: 'token expirado, no evaluable' },
};

/**
 * Doble del WebSocket, **local a este archivo** (RG-11): registra lo que envía el cliente y
 * permite simular al servidor sin abrir un socket real.
 */
class FakeWebSocket implements WebSocketInstanceLike {
  static instances: FakeWebSocket[] = [];

  readonly url: string;
  readonly sent: string[] = [];
  closeCalls = 0;

  onopen: ((event?: unknown) => void) | null = null;
  onmessage: ((event: WebSocketMessageEventLike) => void) | null = null;
  onerror: ((event?: unknown) => void) | null = null;
  onclose: ((event?: unknown) => void) | null = null;

  constructor(url: string) {
    this.url = url;
    FakeWebSocket.instances.push(this);
  }

  send(data: string): void {
    this.sent.push(data);
  }

  close(): void {
